window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gineco-gin-3"]={"block":"medcurso:medcurso-gineco-gin-3","label":"Medcurso · GIN 3","count":464,"questions":[{"id":"medcurso-gineco-gin-3-343757","number":"343757","sourceNumber":"343757","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 35 anos, comparece à consulta ginecológica na UBS com queixa de\namenorreia há um ano e meio, assim como insônia e irritabilidade. Traz consigo os seguintes\nexames: FSH: 108 Prolactina: 10 ng/ml TSH: 2 mU/L t4 livre: 0,9 ng/dl beta HCG negativo. Diante\ndesse quadro clínico, a conduta mais adequada é:","options":{"A":"Iniciar a terapia de reposição hormonal, caso a paciente não tenha contraindicação ao uso de\nestrogênios, pois trata-se de um quadro de insuficiência ovariana prematura.","B":"Encaminhar ao endocrinologista, pois trata-se de um quadro de hipertireoidismo.","C":"Solicitar RMN de crânio para investigar se a paciente apresenta adenoma hipofisário.","D":"Os exames estão normais, portanto, trata-se de um quadro de anovulação crônica e a paciente\ndeve prosseguir a investigação da irritabilidade\ne insônia com o psiquiatra."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343761","number":"343761","sourceNumber":"343761","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Considere verdadeiro (V) ou falso (F) as afirmações sobre incontinência urinária de\nacordo com os consensos da International\nContinence Society (ICS). ( ) Incontinência urinária é\ndefinida como qualquer perda involuntária de urina. ( ) Com base nos sinais e sintomas, a\nincontinência urinária de esforço (IUE) é a perda de urina que ocorre durante a tosse, espirro ou\nesforço físico. ( ) A enurese noturna é definida como a perda inconsciente de urina em gotas que\nocorre durante o sono e às vezes pela manhã ao acordar. ( ) Os sintomas urinários de\narmazenamento que podem ser provocados por diferentes condições são: incontinência urinária de\nesforço (IUE), urgência, urge-incontinência, infecções do trato urinário inferior. A sequência\ncorreta\nse estabelece em:","options":{"A":"V-F-V-F.","B":"V-V-F-F.","C":"F-V-F-V.","D":"V-F-F-F."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343766","number":"343766","sourceNumber":"343766","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente hipertensa de longa data comparece ao atendimento ambulatorial com queixa\nde incontinência urinária para avaliação médica.\nQual dos fatores a seguir é transitório e reversível\ne atua somente na intensificação da queixa da paciente?","options":{"A":"Obesidade.","B":"Menopausa.","C":"Uso de inibidores da enzima conversora da angiotensina (IECA).","D":"Multiparidade."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343767","number":"343767","sourceNumber":"343767","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa que contempla os efeitos do hipoestrogenismo característico no\nclimatério:","options":{"A":"Atrofia do epitélio urogenital, ressecamento vaginal e aumento na atividade de osteoclastos.","B":"Tendência à melhora no perfil lipídico.","C":"Aumento da atividade de osteoblastos.","D":"Menor chance de sintomas urinários, como disúria e urgência miccional."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343771","number":"343771","sourceNumber":"343771","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 48 anos, nuligesta, IMC= 23 kg/m2, refere que levanta cerca de 8 vezes a\nnoite para urinar e que na maioria das vezes precisa ir às pressas ao banheiro, com medo de se\nurinar. Relata ainda que esta situação vem interferindo em sua vida social pois chegou a urinar nas\nroupas, pois não alcançou o banheiro a tempo. Nega comorbidades. Ao exame físico: ausência de\nperdas urinárias na manobra de Valsalva e ausência de distopias genitais. A principal hipótese\ndiagnóstica e seu respectivo tratamento, nesse caso, são:","options":{"A":"Incontinência urinária de esforço, tratar com cirurgia de \"\"sling\"\".","B":"Incontinência urinária de urgência, tratar com anticolinérgicos.","C":"Bexiga hiperativa, tratar com cirurgia de \"\"sling\"\".","D":"Incontinência urinária mista, tratar com adrenérgicos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-345475","number":"345475","sourceNumber":"345475","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 51 anos, com queixa de \"calores noturnos\" e diminuição de libido, em\namenorréia há 1 ano, deseja iniciar terapia\nhormonal. Exame de sangue com LDL de 90 mg/dl, HDL\n60 de mg/dl e triglicerídeos de 300 mg/dl. A opção para esse caso é:","options":{"A":"Estradiol por via oral.","B":"Estrogênios conjugados.","C":"Tibolona.","D":"Estriol via vaginal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-345482","number":"345482","sourceNumber":"345482","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 60 anos, com menopausa aos 50 anos, não realizou nenhuma terapia\nhormonal, queixa de aumento de frequência miccional, urgência com incontinência esporádicas e\nnoctúria há 2 anos, observando piora dos sintomas. Com base neste quadro clínico, assinale a\nalternativa que apresenta o diagnóstico:","options":{"A":"Incontinência urinária de esforço.","B":"Bexiga hiperativa.","C":"Cistite intersticial.","D":"Infecção urinária."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-291778","number":"291778","sourceNumber":"291778","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos de idade, sem comorbidades, foi submetida a histerectomia total por\nleiomiomatose uterina há 11 anos. Vem em consulta médica pois há 8 meses vem queixando de\nfogachos e insônia, além de ressecamento vaginal que antes não apresentava. Trouxe mamografia\nrecente: BIRADS 3. A mamografia do ano anterior apresentava a mesma imagem sem modificação\nde características ou volume. Também trouxe resultado de densitometria óssea realizada\nrecentemente evidenciando T score: -0,8 DP (desvio padrão) em fêmur proximal e T score: -0,4 DP\nem coluna lombar. Ao exame físico sem alterações. PA: 115x75mmHg e FC: 72bpm. A paciente\ndeseja tratamento para os sintomas. Indique a melhor conduta com relação ao tratamento para os\nsintomas climatéricos da paciente.","options":{"A":"Terapia hormonal combinada com estrogênio e progesterona, por via oral.","B":"Terapia hormonal isolada com estrogênio.","C":"Uso de antidepressivo tricíclico.","D":"Estrogênio em gel para uso transdérmico e progesterona em forma de implante subdérmico."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-291780","number":"291780","sourceNumber":"291780","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos de idade, sem comorbidades, foi submetida a histerectomia total por\nleiomiomatose uterina há 11 anos. Vem em consulta médica pois há 8 meses vem queixando de\nfogachos e insônia, além de ressecamento vaginal que antes não apresentava. Trouxe mamografia\nrecente: BIRADS 3. A mamografia do ano anterior apresentava a mesma imagem sem modificação\nde características ou volume. Também trouxe resultado de densitometria óssea realizada\nrecentemente evidenciando T score: -0,8 DP (desvio padrão) em fêmur proximal e T score: -0,4 DP\nem coluna lombar. Ao exame físico sem alterações. PA: 115x75mmHg e FC: 72bpm. A paciente\ndeseja tratamento para os sintomas. Com relação ao resultado da densitometria óssea da\npaciente, é correto afirmar:","options":{"A":"A paciente apresenta osteopenia e merece tratamento através do uso de cálcio e vitamina D.","B":"A densitometria óssea apresenta um resultado normal, não tendo sinais de osteopenia ou\nosteoporose.","C":"A paciente apresenta osteopenia e merece tratamento através do uso de cálcio, vitamina D e\nbisfosfonato.","D":"A paciente apresenta osteoporose e, além da terapia de reposição hormonal, deverá fazer uso\nde cálcio, vitamina D e bisfosfonato."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-251892","number":"251892","sourceNumber":"251892","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A instabilidade do músculo detrusor pode ser uma causa de incontinência urinária na\nmulher. Seu tratamento é preferencialmente clínico e deve ser administrada a seguinte categoria de\nmedicações:","options":{"A":"Antiadrenérgicos.","B":"Adrenérgicos.","C":"Anticolinérgicos.","D":"Colinérgicos."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-251915","number":"251915","sourceNumber":"251915","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Residente de Medicina de Família em seu primeiro mês na UBS ficou responsável de\norganizar a roda de conversa mensal com o Grupo de Idosos com o tema Osteoporose. Durante a\natividade com vários idosos de ambos os sexos houve várias perguntas e dúvidas sobre o tema.\nOsteoporose é um distúrbio esquelético crônico e progressivo, de origem multifatorial, que acomete\nprincipalmente, pessoas idosas, tanto homens quanto mulheres, estas geralmente, após a\nmenopausa. Assinale a alternativa correta que descreve indicações para realização de\ndensitometria óssea, a qual permite estabelecer o diagnóstico da osteoporose. Leia as proposições\nabaixo: I. O exame de densitometria óssea é indicado para mulheres acima de 65 anos e homens\nacima de 70 anos. II. O exame de densitometria óssea é indicado para todas as mulheres acima de\n55 anos e homens acima de 60 anos. III. Pode ser indicado para mulheres abaixo de 65 anos e\nhomens abaixo de 70 anos que tenha um dos critérios: Baixo Peso (Índice de Massa Corporal\nmenos que 18,5 kg/m²), fratura prévia e que fazem uso de medicações que aumentam o risco de\nOsteoporose. IV. Pode ser indicado para todas as mulheres acima de 55 anos com fratura prévia,\nque tem doenças e faz uso de medicações que aumentam o risco de Osteoporose. Assinale a\nalternativa INCORRETA.","options":{"A":"I e III.","B":"I e II.","C":"III e II.","D":"II e IV."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-217663","number":"217663","sourceNumber":"217663","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A colpoplastia com técnica de Kelly-Kennedy é indicada para:","options":{"A":"Incontinência urinária de esforço.","B":"Retocele.","C":"Cistocele com defeito central.","D":"Prolapso uterino grau I."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183190","number":"183190","sourceNumber":"183190","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma senhora de 78 queixa-se de perda urinária frequente. Sem outra especificação,\nqual a principal causa para essa queixa na\nreferida faixa etária?","options":{"A":"incontinência urinária de esforço anatômico.","B":"Diverticulo uretral.","C":"Incontinência urinária de urgência.","D":"Fístula urinária.","E":"Incontinência urinária por regurgitação (overflow)."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-182714","number":"182714","sourceNumber":"182714","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A instabilidade do músculo detrusor pode ser uma causa de incontinência urinária na\nmulher. O tratamento desse problema é preferencialmente clínico e deve ser administrada a\nseguinte categoria de medicações:","options":{"A":"Antiadrenérgicos.","B":"Adrenérgicos.","C":"Anticolinérgicos.","D":"Colinérgicos."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-108767","number":"108767","sourceNumber":"108767","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 55 anos de idade, IMC de 24, G5P5NA0, menopausa aos 50 anos,\nassintomática, vai ao ginecologista para mostrar os resultados dos exames. A ultrassonografia\nendovaginal que evidencia eco endometrial de 6mm. Qual a conduta mais adequada?","options":{"A":"Expectante, retornar se sangramento;","B":"Indicar curetagem uterina fracionada;","C":"Indicar biópisia com cureta de Novak;","D":"Indicar histerectomia."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-66920","number":"66920","sourceNumber":"66920","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 55a, menopausa há 7 anos, faz Terapia de Reposição Hormonal (TRH), com\nestrogênio e progesterona, por via oral há 6 anos, indicada por sintomas vasomotores intensos.\nRefere melhora desses sintomas com o tratamento e vem para consulta com exames laboratoriais\nnormais. A melhor conduta em relação à TRH é:","options":{"A":"Interromper, pois ela já usou por mais de 5 anos;","B":"Interromper quando a mulher completar 60 anos de idade;","C":"Interromper por 1 mês e, se não tiver sintomas, manter sem a TRH;","D":"Manter a TRH;"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-66990","number":"66990","sourceNumber":"66990","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A conduta no sangramento pós-menopausa com ultrassonografia transvaginal normal\né:","options":{"A":"Administração de estrogênio;","B":"Administração de estrogênio e progestogênio;","C":"Histeroscopia;","D":"Histerectomia total abdominal;"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-66954","number":"66954","sourceNumber":"66954","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O fator de risco mais importante para o desenvolvimento da osteoporose é o(a):","options":{"A":"Tabagismo;","B":"Uso de álcool;","C":"Falta de atividade física;","D":"Idade;"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37051","number":"37051","sourceNumber":"37051","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A principal estrutura responsável pelo fechamento e sustentação do assoalho pélvico é:","options":{"A":"Músculo elevador do ânus.","B":"Aponeurose do músculo retoabdominal.","C":"Músculo transverso do períneo.","D":"Arco tendíneo do períneo.","E":"Músculo bulbocavernoso."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37052","number":"37052","sourceNumber":"37052","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Fazem parte do mecanismo da continência urinária na mulher, exceto:","options":{"A":"Angulação do colo vesical.","B":"Trofismo da mucosa e vasos da uretra.","C":"Esfíncter uretral.","D":"Músculos de sustentação da pelve.","E":"Esfíncter vesical interno."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343209","number":"343209","sourceNumber":"343209","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 51 anos, em fase de climatério, com queixas importantes de fogachos\ne insônia, questiona o ginecologista a respeito\nda terapia hormonal. Refere ter muito medo de\ncâncer e que prefere ter os sintomas a correr o risco de uma neoplasia. O ginecologista deve\norientar a paciente que a TRH diminui o risco relativo de câncer de:","options":{"A":"Bexiga","B":"Ovário","C":"Cólon","D":"Mama"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-315200","number":"315200","sourceNumber":"315200","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 55 anos de idade, G5P5NA0, vem ao ambulatório com queixa de perda\nurinária durante o coito e ao tossir, além de intenso ?ressecamento? vaginal e dispareunia. Sobre o\nquadro citado, assinale a alternativa CORRETA.","options":{"A":"O estudo urodinâmico não é um exame necessário para identificação da incontinência urinária,\numa vez que está claro tratar-se de uma\nincontinência urinária por distopia genital.","B":"O uso de estrógenos tópicos, a exemplo do promestrieno, pode ser uma escolha para manejo da\nreduzida lubrificação vaginal.","C":"A multiparidade e o estágio da vida reprodutiva da paciente em questão em nada se associam\nao quadro de incontinência urinária.","D":"O exame físico não se faz necessário na busca pela etiologia da incontinência urinária e a\nfisioterapia pélvica certamente não constitui uma opção terapêutica no caso relatado.","E":"Essa paciente, sem dúvida, deverá receber terapia de reposição hormonal oral, considerando\nseu desconforto durante a relação sexual."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-283733","number":"283733","sourceNumber":"283733","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos de idade, sem comorbidades, foi submetida a histerectomia total por\nleiomiomatose uterina há 11 anos. Vem em consulta médica pois há 8 meses vem queixando de\nfogachos e insônia, além de ressecamento vaginal que antes não apresentava. Trouxe mamografia\nrecente: BIRADS 3. A mamografia do ano anterior apresentava a mesma imagem sem modificação\nde características ou volume. Também trouxe resultado de densitometria óssea realizada\nrecentemente evidenciando T score: -0,8 DP (desvio padrão) em fêmur proximal e T score: -0,4 DP\nem coluna lombar. Ao exame físico sem alterações. PA: 115x75mmHg e FC: 72bpm. A paciente\ndeseja tratamento para os sintomas. Indique a melhor conduta com relação ao tratamento para os\nsintomas climatéricos da paciente.","options":{"A":"Terapia hormonal combinada com estrogênio e progesterona, por via oral.","B":"Terapia hormonal isolada com estrogênio.","C":"Uso de antidepressivo tricíclico.","D":"Estrogênio em gel para uso transdérmico e progesterona em forma de implante subdérmico."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-283735","number":"283735","sourceNumber":"283735","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos de idade, sem comorbidades, foi submetida a histerectomia total por\nleiomiomatose uterina há 11 anos. Vem em consulta médica pois há 8 meses vem queixando de\nfogachos e insônia, além de ressecamento vaginal que antes não apresentava. Trouxe mamografia\nrecente: BIRADS 3. A mamografia do ano anterior apresentava a mesma imagem sem modificação\nde características ou volume. Também trouxe resultado de densitometria óssea realizada\nrecentemente evidenciando T score: -0,8 DP (desvio padrão) em fêmur proximal e T score: -0,4 DP\nem coluna lombar. Ao exame físico sem alterações. PA: 115x75mmHg e FC: 72bpm. A paciente\ndeseja tratamento para os sintomas. Com relação ao resultado da densitometria óssea da paciente,\né correto afirmar:","options":{"A":"A paciente apresenta osteopenia e merece tratamento através do uso de cálcio e vitamina D.","B":"A densitometria óssea apresenta um resultado normal, não tendo sinais de osteopenia ou\nosteoporose.","C":"A paciente apresenta osteopenia e merece tratamento através do uso de cálcio, vitamina D e\nbisfosfonato.","D":"A paciente apresenta osteoporose e, além da terapia de reposição hormonal, deverá fazer uso\nde cálcio, vitamina D e bisfosfonato."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-279072","number":"279072","sourceNumber":"279072","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 48 anos, com queixa de menstruações a cada 3 ? 4 meses, associado à\ndiminuição da lubrificação vaginal. O melhor exame para o correto diagnóstico é","options":{"A":"LH","B":"FSH","C":"Estradiol","D":"Progesterona"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-280447","number":"280447","sourceNumber":"280447","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Músculo que não compõe o períneo anterior","options":{"A":"Bulbocavernoso.","B":"Isquiocavernoso.","C":"Transverso Superficial do Períneo.","D":"Elevador do Ânus."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-278131","number":"278131","sourceNumber":"278131","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Considere as seguintes situações I. Trombose Venosa Profunda. II. Demência Senil. III.\nCâncer de Mama. IV. Câncer de Intestino. Representam contra-indicações ao uso de Terapia\nHormonal contendo estrogênio e progesterona","options":{"A":"I e II","B":"I e III","C":"III e IV","D":"I e IV"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-231371","number":"231371","sourceNumber":"231371","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à Terapia de Hormonal da Menopausa (THM), assinale a opção correta:","options":{"A":"Dentre as indicações, destacam?se o alívio dos sintomas vasomotores, proteção cardiovascular,\nprevenção de Alzheimer e melhora do bem\nestar e sexualidade.","B":"Está comprovada a prevenção secundária de doença cardio vascular.","C":"Câncer estrogênio?dependente ativo ou recente é uma das contra?indicações relativas.","D":"Na escolha do esquema terapêutico, deve?se dar preferência por hormônios idênticos aos\nfabricados pelos ovários: estradiol e progesterona.","E":"O tempo de uso deve ser sempre o maior possível, com o objetivo de obter maior proteção\nóssea."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-219873","number":"219873","sourceNumber":"219873","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 59 anos, G5P5, data da última menstruação aos 50 anos, IMC = 26,1\nkg/m², tabagista com doença pulmonar obstrutiva\ncrônica refere perda de urina ao esforço há 3\nanos com piora do quadro nos últimos 8 meses. Nega outros sintomas urinários. Qual a conduta\nMAIS INDICADA para essa paciente?","options":{"A":"Intervenções no estilo de vida, uso de pessário vaginal.","B":"Intervenções no estilo de vida, cirurgia para correção da perda de urina.","C":"Intervenções no estilo de vida, fisioterapia do assoalho pélvico.","D":"Terapia comportamental, sling retropúbico."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-219852","number":"219852","sourceNumber":"219852","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 49 anos, G0P0, refere ciclos menstruais irregulares com pouco fluxo,\nassociado a ondas de calor, irritabilidade,\nalteração do sono e diminuição do desejo sexual há 6\nmeses. Quanto à abordagem integral e não farmacológica das queixas climatéricas dessa paciente,\nqual das medidas abaixo NÃO deve ser proposta:","options":{"A":"Abordagem motivacional quanto ao estilo de vida saudável.","B":"Orientar anticoncepção no climatério.","C":"Práticas integrativas e complementares como a fitoterapia.","D":"Rastreamento de osteoporose."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216330","number":"216330","sourceNumber":"216330","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação aos seguintes sintomas: I. Taquicardia; II. Tremor fino de extremidades; III.\nInsuficiência cardíaca congestiva; IV. Edema agudo de pulmão. Os sintomas que têm relação com\no uso de terbutalina são","options":{"A":"I, II e III, apenas.","B":"I, II e IV, apenas.","C":"II, III e IV, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216338","number":"216338","sourceNumber":"216338","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O exame considerado suficiente para diagnóstico de menopausa é","options":{"A":"LH.","B":"FSH.","C":"Progesterona na primeira fase do ciclo.","D":"TSH."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212240","number":"212240","sourceNumber":"212240","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O aumento da expectativa de vida na população em geral permite maior observação de\nafecções mais prevalentes na faixa etária mais avançada, como os prolapsos de órgãos pélvicos\n(POP). Apesar de não haver ameaça a vida, é uma causa importante de morbidade. Para auxiliar\nno diagnóstico, a Sociedade Internacional de Continência (ICS) aprovou o sistema de Quantificação\ndos Prolapsos de Órgãos Pélvicos (POP-Q), o qual permite avaliar e determinar o tipo e a\ngravidade dos prolapsos através de pontos pré-determinados, como visto na figura a seguir. Em\nrelação ao POP-Q, qual a alternativa correta?","options":{"A":"Os pontos são medidos em milímetros e podem ser negativos ou positivos.","B":"Mesmo existindo a presença dos pontos C e D, a avaliação do compartimento apical é\nfacultativa.","C":"Com o advento do POP-Q, não é mais necessário avaliar o órgão genital externo à manobra de\nValsalva.","D":"Proporciona padronização das medidas,permitindo, assim, uniformização dos resultados vistos\npor diferentes observadores.","E":"Pode-se afirmar que é um sistema mais elaborado para auxiliar no diagnóstico preciso dos\nprolapsos genitais e vem sendo adotado na prática clínica pela maioria dos médicos."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/212240.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216242","number":"216242","sourceNumber":"216242","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher é submetida à histerectomia total abdominal e retorna após 26 dias referindo\nperda involuntária de urina pela vagina. O teste\ncom azul de metileno resulta positivo. A fístula é,\nportanto,","options":{"A":"vesico-vaginal.","B":"vesico-uterina.","C":"uretero-vaginal.","D":"reto-vaginal."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-215205","number":"215205","sourceNumber":"215205","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao risco de câncer de mama em usuárias de terapia de reposição hormonal,\né CORRETO dizer que:","options":{"A":"Aumenta o risco a partir do momento em que inicia a TRH.","B":"Aumenta o risco a partir de dois anos de TRH.","C":"Aumenta o risco a partir de cinco anos de TRH.","D":"Aumenta o risco a partir de oito anos de TRH."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-187767","number":"187767","sourceNumber":"187767","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher com 51 anos de idade, com queixas de oligomenorréia e \"fogachos\" há 6\nmeses. Os exames clínico e ginecológico são normais. Qual é o diagnóstico clínico e o exame\nMAIS ADEQUADOS para confirmar o diagnóstico?","options":{"A":"Climatério pós-menopausa - Ultrassonografia Pélvica Transvaginal","B":"Climatério pré-menopausa - Dosagem de FSH, LH e Estradiol","C":"Disfunção hipotalâmica - Dosagem de TSH, FSH e LH","D":"Hiperprolactinemia - Ressonância Magnética da hipófise"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-181329","number":"181329","sourceNumber":"181329","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre o padrão hormonal de uma paciente pós-menopausal, é correto afirmar:","options":{"A":"FSH, LH e Estradiol elevados.","B":"Prolactina e Progesterona altas.","C":"FSH elevado, Prolactina e Estradiol alto.","D":"FSH e LH elevados e Estradiol baixo.","E":"Estradiol baixo, Progesterona baixa e FSH baixo."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183033","number":"183033","sourceNumber":"183033","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 47 anos, refere amenorreia há 3 meses. Nega uso de anticoncepcional,\nmas nega gravidez, uma vez que não teve\nrelações sexuais nos últimos 6 meses. A abordagem\ninicial mais adequada e o provável diagnóstico são:","options":{"A":"dosagem de FSH / menopausa precoce.","B":"ultrassom endovaginal / menopausa precoce.","C":"dosagem de FSH / síndrome dos ovários policísticos.","D":"teste da progesterona / síndrome dos ovários policísticos."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-182744","number":"182744","sourceNumber":"182744","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à utilização de Tibolona na Terapia de Reposição Hormonal, assinale a\nalternativa INCORRETA:","options":{"A":"não melhora os sintomas climatéricos","B":"aumenta a densidade mineral óssea","C":"deve ser administrada de forma contínua","D":"não necessita de associação com progesterona, mesmo em pacientes com útero"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-182757","number":"182757","sourceNumber":"182757","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em mulher de 40 anos, obesa, com quadro de incontinência urinária, cujo estudo\nurodinâmico revelou hipermobilidade vesical, a melhor conduta terapêutica é:","options":{"A":"Oxibutinina via oral","B":"Perineoplastia anterior","C":"Cirurgia de Manchester","D":"Cirurgia tipo Sling"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183559","number":"183559","sourceNumber":"183559","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"NÃO se deve indicar tratamento com análogos de GnRh para mulheres","options":{"A":"com diagnóstico de endometriose.","B":"com miomatose uterina.","C":"menopausadas.","D":"com infertilidade."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-161120","number":"161120","sourceNumber":"161120","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A Artéria Pudenda Interna é ramo da:","options":{"A":"Ilíaca Interna.","B":"Obturatória.","C":"Hemorroidária Superior.","D":"Uterina."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-161151","number":"161151","sourceNumber":"161151","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 57 anos, não usuária de terapia de reposição hormonal, apresenta\nsangramento via vaginal. O ultrassom evidencia\neco endometrial de 14 mm. Diante de tal quadro\nclínico, assinale a alternativa contendo a MELHOR conduta.","options":{"A":"Histerossalpingografia.","B":"Histeroscopia.","C":"Laparoscopia.","D":"Histerossonografia."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-131400","number":"131400","sourceNumber":"131400","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 63 anos, com histórico de hipertensão controlada, infarto do miocárdio\naos 61 anos e tromboflebite há 2 meses, está\nsolicitando terapia de reposição hormonal. Qual a\ncondição desta paciente é uma nítida contra-indicação para a terapia estrogênica neste momento?","options":{"A":"Hipertensão Atual.","B":"Infarto do miocárdio há 2 anos.","C":"Tromboflebite recente.","D":"Apenas a A e B.","E":"Nenhuma."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-131368","number":"131368","sourceNumber":"131368","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à pelve feminina, assinale a alternativa incorreta:","options":{"A":"O estreito superior da pequena bacia é delimitado por uma linha imaginária que vai da borda\nsuperior da sínfise púbica ao promontório.","B":"No estreito superior da pequena bacia, o diâmetro transverso é menor que o ântero-posterior.","C":"Durante a passagem do feto pelo canal de parto, o segmento mais difícil é o pólo cefálico.","D":"É constituída de partes ósseas, músculos e aponeuroses.","E":"Ao examinarmos uma bacia, durante o exame de toque, os pontos que devemos observar são o\npromontório, as espinhas ilíacas e o ângulo sub-púbico."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134292","number":"134292","sourceNumber":"134292","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 48 anos, G3P3A0C0, obesa, refere perda de urina aos pequenos esforços\nhá 2 anos, refere ter tido este ano 4\nepisódios de infecção de trato urinário, refere bola na vagina,\nnega infecção no momento e outras queixas. Diante de tal caso, a principal hipótese diagnóstica é:","options":{"A":"Pielonefrite.","B":"Hiperatividade detrusora.","C":"Incontinência urinária de esforço.","D":"Bexiga neurogênica."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134104","number":"134104","sourceNumber":"134104","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 40 anos, obesa, G2P2A0C2, refere nictúria (4 vezes por noite), urgência\nmiccional, perda de urina aos pequenos esforços e urgincontinência, nega disúria, febre e\n\nmal-estar, fez exame de urina I que foi normal. Exame ginecológico com cistocele grau II. Qual\nseria o próximo passo para se chegar ao tratamento dessa paciente?","options":{"A":"Cirurgia de Kelly-Kennedy.","B":"Estudo urodinâmico.","C":"Cirurgia de colpoperineoplastia.","D":"Urina de 24 horas."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134312","number":"134312","sourceNumber":"134312","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 49 anos, hígida, com vida sexual ativa, refere estar sem menstruar há 1\nano e meio, refere fogachos e nega\nantecedente de câncer. O que podemos tomar de conduta\nnesse caso para prevenir o risco de doença cardiovascular a essa paciente?","options":{"A":"Fazer uso de AAS 100 mg / dia.","B":"Fazer uso de anticoagulante contínuo.","C":"Fazer uso de ômega 3 por 10 anos.","D":"Fazer uso de TH por 1 ano."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134051","number":"134051","sourceNumber":"134051","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 40 anos, com incontinência urinária aos mínimos esforços, nictúria e\ncom urgincontinência. Nega ITU. Segundo a paciente já foi submetida a uma colpoperineoplastias\nem sucesso. Exame físico não apresenta distopias. Qual exame seria necessário para o tratamento\ndessa paciente?","options":{"A":"Uretrocistografia miccional.","B":"Ultrassonografia pélvica.","C":"Urografia excretora.","D":"Estudo urodinâmico."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134355","number":"134355","sourceNumber":"134355","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 50 anos, G3P3A0C0, vida sexual ativa, refere há 4 meses não menstruar e\na sentir calorões intensos que sobem para o\npescoço e face à noite e na madrugada, irritação e\ninsônia. Diante desse caso, qual exame NÃO seria importante para o diagnóstico e possível\ntratamento?","options":{"A":"Mamografia.","B":"Dosagem de TSH.","C":"US endovaginal.","D":"Dosagem de Beta HCG."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134882","number":"134882","sourceNumber":"134882","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 52 anos, G6P6A0C0, DUM = há 9 meses, vida sexual ativa, refere perdas\nde urina aos pequenos esforços há 8 meses,\nnictúria (4 vezes), urgência miccional e\nurgincontinência. Nega febre, disúria e polaciúria. Fez exame especular e exame de urina I com\nurocultura que estavam normais. Diante de tal caso, qual outro exame seria importante para a\nconclusão diagnóstica?","options":{"A":"Estudo urodinâmico.","B":"US abdominal.","C":"Urografia escretora.","D":"Exame de Papanicolau."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-109771","number":"109771","sourceNumber":"109771","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 49 anos, G3P3A0C0, vida sexual ativa com coito interrompido, refere estar\nem amenorreia há 60 dias, irritação, mal-estar,\nmastalgia e inchaço no corpo. Dos exames citados\nabaixo, qual NÃO é necessário ser realizado?","options":{"A":"Dosagem de BetaHCG.","B":"Dosagem de FSH.","C":"Ultrassonografia endovaginal.","D":"Curetagem uterina de prova."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-86596","number":"86596","sourceNumber":"86596","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diagnóstico da instabilidade do detrusor é firmado por:","options":{"A":"Urofluxometria.","B":"Eletromiografia do detrusor.","C":"Ultrassom do colo vesical.","D":"Uretrocistografia.","E":"Cistometria."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-86593","number":"86593","sourceNumber":"86593","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Quanto à Incontinência Urinária de esforço, é CORRETO afirmar:","options":{"A":"O aumento da pressão uretral é o fator etiológico mais importante.","B":"A atividade hormonal é causa fisiológica primária, aumentando a incidência de IUE com a idade.","C":"A colpoperineoplastia é a cirurgia que melhor oferece proteção vascular e nervosa à uretra.","D":"a e b estão corretas.","E":"Todas estão corretas."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-158406","number":"158406","sourceNumber":"158406","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao prolapso de mucosa uretral, qual a alternativa correta?","options":{"A":"Ocorre principalmente em mulheres no menacme.","B":"Ocorre principalmente no puerpério.","C":"O tratamento geralmente é cirúrgico.","D":"Pode ser tratado com estrogênio local.","E":"Geralmente está relacionado ao prolapso uterino."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-49574","number":"49574","sourceNumber":"49574","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São opções para o tratamento da osteoporose na mulher, EXCETO:","options":{"A":"Bifosfonatos.","B":"Raloxifeno.","C":"Ranelato de estrôncio.","D":"Isoflavona de soja.","E":"Terapia de reposição hormonal."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-13135","number":"13135","sourceNumber":"13135","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sistema de descrição quantitativa dos prolapsos genitais e que exige medida de oito\npontos na vagina e assim criar um perfil vaginal em série:","options":{"A":"POT-K.","B":"POP-Q.","C":"POP-X.","D":"POT-X.","E":"POT-Q."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-286751","number":"286751","sourceNumber":"286751","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 58 anos, 50 quilos, menopausada há 8 anos, tabagista, sedentária, diabética.\nFoi ao ginecologista com resultado de\ndensitometria óssea com T score menor que - 2,6 desvios\npadrão. Qual o diagnóstico segundo a Organização Mundial de Saúde?","options":{"A":"Osteopenia","B":"Osteoporose estabelecida","C":"Osteoporose","D":"Normal para a faixa etária"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-252266","number":"252266","sourceNumber":"252266","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Senhora Maria Clara com 70 anos de idade, casada, dona de casa. Veio ao\nambulatório de ginecologia encaminhada\npelo médico de família e comunidade por apresentar\nperda de urina há cinco anos ao tossir ou espirrar, porém há um ano refere urgência e\nurgeincontinência, sem nocturia. 5G4P1A com três partos normais e uma cesárea, sendo o último\nhá 35 anos, com o maior RN pesando 4 kg. Menopausa aos 45 anos, não realizou terapia\nhormonal. Relata ser hipertensa fazendo tratamento há 15 anos. Ao exame físico e ginecológico foi\nobservado obesidade grau II, IMC: 36 kg/m² e perda de urina sincrônica à manobra de valsalva pelo\nmeato uretral em posição ginecológica. Atrofia genital. Ao toque útero e ovários involuidos. Trouxe\nexames solicitados pelo médico de família com esses resultados: Urina I normal, Urocultura\nnegativa e Estudo urodinâmico: ausência de contração involuntária do detrusor com pressão de\nperda (VLPP): 45 cmH2O, capacidade cistometrica = 300ml com resíduo pós-miccional de 30ml.\n\nEm relação ao caso qual a hipótese diagnóstica e conduta:","options":{"A":"Incontinência Urinária de Esforço (IUE) por defeito esfincteriano e obesidade Grau II. O\ntratamento é cirúrgico - SLING com orientação para perda de peso.","B":"IUE por defeito esfincteriano e obesidade Grau II. O tratamento é fisioterapia do assoalho\npélvico, se não houver melhora indicar cirurgia\nde SLING com orientação para a perda de peso.","C":"IUE por hipermobilidade do colo vesical e obesidade Grau III. O tratamento é cirúrgico ? SLING\ne orientar perda de peso.","D":"IUE por hipermobilidade do colo vesical e obesidade Grau II. O tratamento é fisioterapia do\nassoalho pélvico e cirurgia de BURCH com orientação para a perda de peso."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-208316","number":"208316","sourceNumber":"208316","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 72 anos de idade, casada, professora aposentada. Veio ao ambulatório\nde ginecologia encaminhada pelo clínico por\napresentar perda de urina há 10 meses ao tossir ou\nespirrar, caminhar rapidamente e ao realizar atividade física, como correr na esteira. Nega\nurgência, urgeincontinência e noctúria. 3G3P0A. Os três partos foram cesáreas, sendo o último há\n40 anos com maior RN pesando 4 kg. Menopausa aos 50 anos não realizou terapia hormonal.\n\nNega comorbidades. Ao exame físico e ginecológico foi observado obesidade grau I, IMC: 31 kg/m²\ne perda de urina sincrônica pelo meato\nuretral à manobra de valsalva em posição ginecológica.\n\nTrouxe exames solicitados pelo médico clínico com esses resultados: Urina I normal, Urocultura\nnegativa e Estudo urodinâmico: ausência de\ncontração involuntária do detrusor com pressão de\nperda (ALPP - abdominal leak point pressure): 40 cmH?O. Em relação ao caso qual o diagnóstico e\nconduta:","options":{"A":"Incontinência Urinária de Esforço (IUE) por defeito esfincteriano e obesidade Grau I. O\ntratamento é cirúrgico - SLING e orientar a perda de peso.","B":"IUE por defeito esfincteriano e obesidade Grau I. O tratamento é fisioterapia do assoalho pélvico\ne cirurgia de BURCH com orientação para a perda\nde peso.","C":"IUE por hipermobilidade do colo vesical e obesidade Grau I. O tratamento é cirúrgico - SLING e\norientar perda de peso.","D":"IUE por hipermobilidade do colo vesical e obesidade Grau I. O tratamento é fisioterapia do\nassoalho pélvico e cirurgia de BURCH com orientação para a perda de peso."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-176053","number":"176053","sourceNumber":"176053","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sra. Helena, professora, 45 anos veio encaminhada de São Paulo de Olivença para o\nambulatório de ginecologia por perder urina. Como não conseguiu agendamento, foi a um médico\nclínico na UBS que a avaliou, solicitou exames e agilizou o seu atendimento com o colega\nginecologista que atende no hospital\n\nuniversitário. A Sra. Helena chegou ao ambulatório de ginecologia do hospital universitário com\nqueixa de perda de urina aos esforços como tossir, espirrar e gargalhar há 2 anos e há 1 ano com\nurgência miccional. Negando urgeincontinência e disúria. Relatou que há 3 anos realizou\nhisterectomia por mioma uterino. 3G3P sendo o último parto há 10 anos, foram três cesáreas.\n\nÚltima menstruação há 3 anos. Trouxe exames solicitados pelo médico da UBS, urina tipo I normal,\nurinocultura negativa e estudo urodinâmico com urofluxometria normal, resíduo miccional = 40 ml,\ncistometria sem anormalidades com VLPP = 100 cmH?O. Ao exame: IMC = 33 kg/m². Foi\nobservado perda de urina sincrônica à manobra de Valsalva pelo meato externo da uretra em\nlitotomia, sem descida da parede vaginal anterior, posterior nem apical. Qual o diagnóstico e\nconduta mais adequada para esse caso?","options":{"A":"Fístula vesicovaginal ? cateterismo intermitente.","B":"Incontinência urinária de esforço por hipermobilidade do colo vesical ? sling por via\nretropúbica.","C":"Síndrome da bexiga hiperativa ? terapia comportamental e anticolinérgico.","D":"Incontinência urinária mista ? cirurgia de Burch."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-151903","number":"151903","sourceNumber":"151903","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 50 anos com fratura da extremidade distal do rádio após queda da própria\naltura. Menopausa precoce, aos 41 anos, sem\ntratamento específico. Suspeita-se de osteoporose.\nQual é o exame indicado para esse diagnóstico?","options":{"A":"Densitometria óssea.","B":"Cintilografia óssea.","C":"RX de mãos com punhos.","D":"Dosagem no sangue do cálcio, fósforo e fosfatase alcalina."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-151894","number":"151894","sourceNumber":"151894","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 55 anos, professora, casada, com dois filhos, o mais jovem tem 25 anos, dois\npartos por via vaginal. Há 6 meses apresenta queixa de perda de urina ao tossir ou espirrar,\nurgência, urgeincontinência e noctúria. Trouxe exames de urina tipo I, urocultura e estudo\nurodinâmico. Os exames laboratoriais de urina estavam normais e ao estudo urodinâmico foi\nobservado contrações involuntárias do detrusor a cistometria, pressão de perda ao esforço (VLPP)\n45 cmH2O, resíduo pós miccional 30 ml, pressão detrusora 35cmH2O. A capacidade cistométrica\nmáxima 450 ml. Achado positivo na história familiar, mãe e irmão com glaucoma. O diagnóstico e a\nmelhor conduta para esse caso é:","options":{"A":"Bexiga hiperativa, o tratamento é medicamentoso com anticolinérgico.","B":"Incontinência urinária mista, tratamento cirúrgico com cirurgia de alça por se tratar de um\ndefeito\nesficteriano uretal e fisioterapia.","C":"Incontinência urinária mista, tratamento cirúrgico com cirurgia de alça por hipermobilidade\nanatômica da uretra e fisioterapia.","D":"Incontinência urinária de esforço, tratamento cirúrgico colpossuspensão retropública por\nhipermobilidade anatômica da uretra e fisioterapia."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-151907","number":"151907","sourceNumber":"151907","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O fechamento normal da uretra é mantido por uma combinação de fatores intrínsecos e\nextrínsecos. Os fatores extrínsecos incluem:","options":{"A":"Músculo levantador do ânus e vasos sanguíneos.","B":"Fáscia parietal da pélvis e músculos estriados e lisos da parede da uretra.","C":"Músculos estriados e lisos da parede da uretra e coaptação epitelial das pregas do revestimento\nuretral.","D":"Músculos levantadores do ânus, fáscia parietal da pélvis e suas fixações às paredes laterais da\npelve e à uretra."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-151915","number":"151915","sourceNumber":"151915","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 60 anos de idade, viúva aposentada foi ao ginecologistica\n\nqueixando-se de \"bola na vagina\". Ao exame físico uroginecológico, ela apresenta o ponto de maior\nprolapso no compartimento médio em 0 (zero), e o ponto de maior prolapso na parede anterior em\n\n-1 e na parede posterior em -2. O estadio do POP-Q (Sistema de Quantificação do Prolapso de\nórgãos Pélvicos) dessa paciente é:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-151952","number":"151952","sourceNumber":"151952","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao prolapso dos órgãos pélvicos: I. O sistema de sustentação do útero e da\nvagina é dividido em três níveis, o nível I é o complexo de ligamentos uterossacro / transverso do\ncolo, que mantém o comprimento e o eixo da vagina. II. Os distúrbios mais comuns da sustentação\npélvica são retoceles e cistoceles, enteroceles e prolapso uterino, resultante da fraqueza do tecido\nconjuntivo endopélvico, da sustentação do músculo levantador do ânus ou de ambos. III. As\nestruturas de sustentação pélvica são: os músculos e os tecidos conjuntivo do assoalho pélvico, o\ntecido fibromuscular da parede abdominal e o tecido conjuntivo endopélvico. IV. Em geral, a\nescolha do tratamento depende da intensidade dos sintomas e do grau de prolapso, levando-se em\nconta a saúde geral e o nível de atividade da paciente. Assinale a alternativa CORRETA:","options":{"A":"Somente as afirmativas I e III estão corretas.","B":"Somente as afirmativas I, II e III estão corretas.","C":"Somente as afirmativas I, II e IV estão corretas.","D":"Somente as afirmativas II, III e IV estão corretas."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-139117","number":"139117","sourceNumber":"139117","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma senhora de 65 anos, que apresentou uma fratura de baixo impacto e foi\ndiagnosticada com osteoporose, que fatores de risco deve-se pesquisar para esta condição?","options":{"A":"Obesidade, baixa estatura e etnia negra.","B":"Baixa ingestão de leite, etnia negra e tabagismo.","C":"Consumo excessivo de café, atividade física excessiva e insuficiente ingestão de proteínas.","D":"Hereditariedade, tabagismo e uso abusivo de álcool."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-129728","number":"129728","sourceNumber":"129728","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 69 anos veio ao ambulatório de ginecologia encaminhada de Carauari, com\nqueixa de perda de urina aos esforços há 5 anos, mas há 1 ano apresenta urgência miccional e\nurge-incontinência. IIIGIIIP0A todos os partos foram por via alta. Ao estudo urodinâmico, foi\nobservado contração involuntária do detrusor e perda de urina com pressão de perda inferior a 60\ncmH2O. Qual o diagnóstico e a melhor conduta para esse caso?","options":{"A":"Incontinência urinária mista e deve ser tratada com Colpossuspenção retro púbica e\nanticolinérgico.","B":"Incontinência urinária mista e deve ser tratada com anticolinérgico e cirurgia de alça.","C":"Incontinência urinária de esforço e deve ser realizado tratamento conservador supervisionado\npor fisioterapeuta.","D":"Incontinência urinária de esforço e a cirurgia realizada deve ser a cirurgia de alça."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-129749","number":"129749","sourceNumber":"129749","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"M.A.P., 70 anos, com história de bola na vagina há 8 anos. Informa que há 6 meses\napresenta dor quando tem relação sexual.\nSem queixa de perda de urina. 12G12P0A, último parto\nhá 35 anos, nenhum parto aconteceu em hospital. Ao exame, foi realizado o POP-Q (sistema de\nQuantificação do Prolapso de Órgão Pélvico) que mostrou o seguinte: Aa +2; Ap +1; Ba +3 e Bp +2;\nC +5; DX e CVT 8 cm. O tratamento para essa paciente é:","options":{"A":"Cirurgia para fixar a cúpula vaginal e correção da distopia de parede anterior e posterior.","B":"Histerectomia vaginal e correção da distopia de parede anterior e posterior.","C":"Cirurgia para fixar a cúpula vaginal e correção da distopia de parede posterior.","D":"Colpocleise."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-107875","number":"107875","sourceNumber":"107875","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a afirmativa CORRETA:","options":{"A":"O diafragma da pelve é formado pelos músculos elevador do ânus e bulbo- pubo- coccigeo\njuntamente com suas fáscias superior e inferior.","B":"O levantador do anus ajuda os músculos da parede abdominal a reter os conteúdos abdominal e\npélvico. Durante o parto o elevador do ânus o levantador do ânus sustenta a cabeça do feto\ndurante a dilatação cervical.","C":"Os vasos pélvicos não desempenham nenhum papel na sustentação pélvica.","D":"O ramo genital do nervo genitofemoral entra na fossa obturatória, emergem no canal inguinal e\nseguem na frente do tuber isquiático até a região lateral dos lábios maiores."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-103876","number":"103876","sourceNumber":"103876","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre a menopausa e a transição perimenopausa, marque a alternativa CORRETA:","options":{"A":"Durante a transição menopausal, os ciclos menstruais não apresentam variações na\nregularidade e nas características do fluxo.","B":"Nessa fase ocorre gradativa diminuição da produção estrogênica e consequente aumento das\ngonadotrofinas hipofisárias, caracterizando um estado de hipogonadismo hipergonadotrófico.","C":"As ondas de calor constituem o sintoma mais comum. Manifestam-se como sensação transitória\nsúbita e intensa de calor na pele, que começam\nnos membros inferiores e vão até a face.","D":"O hipoestrogenismo pode influenciar os níveis de colesterol, ocorrendo um aumento nas taxas\nde HDL e diminuição nas de LDL, situação que\nprotege contra as doenças cardiovasculares."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-81995","number":"81995","sourceNumber":"81995","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"As fístulas genitourinárias mais comuns são:","options":{"A":"Vesicouterinas","B":"Vesicocervicais","C":"Ureterovaginais","D":"Vesicovaginais","E":"Retovaginais"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-81001","number":"81001","sourceNumber":"81001","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São estruturas que compreendem o diafragma pélvico:","options":{"A":"Ligamento cardinal e uterossacro","B":"Músculo bulbocavernoso e ileococcígeo","C":"Músculo transverso profundo e transverso superficial do períneo","D":"Músculo elevador do ânus e coccígeo","E":"Músculo puborretal e ligamento uterossacro"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-61578","number":"61578","sourceNumber":"61578","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à osteoporose, assinale a afirmativa CORRETA:","options":{"A":"O Raloxifeno, Alendronato, Risedronato e teriparatida são medicações antirreabsortivas\nutilizadas no tratamento da osteoporose.","B":"A ingestão adequada de Cálcio elemento de acordo com a recomendação National Osteoporosis\nFoundation (NOF) é de 800 mg/dia para mulheres acima de 50 anos.","C":"O ranelato de estrôncio e o ácido zoledrônico são medicações de ação mista utilizadas no\ntratamento da osteoporose. Portanto promovem tanto a formação dessa quanto impedem a\nreabsorção.","D":"As indicações potenciais para a realização de Densitometria Óssea incluem: Hipogonadismo,\nfraturas por baixo impacto, osteopenia ao exame\nradiográfico convencional e uso crônico de\nvarfarina.","E":"A Sociedade Internacional de Densitometria Clínica (ISDC) e a Sociedade Brasileira de\nDensitometria Clínica (SBDens) estabelecem que\nos T-scores e Z-scores devem aparecer nos\nrelatórios de densitometria óssea em crianças e adolescentes e serem analizados em conjunto para\navaliação da massa óssea."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-60929","number":"60929","sourceNumber":"60929","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Analisando a Incontinência Urinária de Esforço (IUE), NÃO se pode afirmar que:","options":{"A":"Geralmente mais em multíparas que em nulíparas.","B":"Decorre do aumento da contratilidade do músculo detrusor.","C":"Frequentemente associada à Distopia do Colo Vesical.","D":"A pressão de perda urinária é uma medida urodinâmica importante no diagnóstico de IUE.","E":"A pressão intravesical supera a pressão que o mecanismo de fechamento da uretra posterior\npode suportar."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-46692","number":"46692","sourceNumber":"46692","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O útero em geral está em posição mediana anteversoflexão. Para manter esta situação\ndentro do contexto da pelve, ele dispõe de\num complexo sistema de fixação, representado pelos\naparelhos de sustentação, suspenção e contenção, que se caracteriza respectivamente por:","options":{"A":"Diafragma pélvico principal, retinaculum uteri e fáscia endopélvica.","B":"Fáscia endopélvica, diafragma pélvico principal e músculo transverso profundo.","C":"Retinaculum uteri, fáscia endopélvica e diafragma pélvico e esfíncter estriado do ânus.","D":"Diafragma pélvico principal, músculos transverso profundo e levantador do ânus e fáscia\nendopélvica.","E":"Retinaculum uteri, músculo transverso profundo e suas aponeuroses e contração dos músculos\nabdominais."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-46719","number":"46719","sourceNumber":"46719","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre o climatério, pode-se dizer:","options":{"A":"A menopausa é um marco do climatério, correspondendo a um dos últimos ciclos menstruais,\nsomente reconhecido depois de passados 12 meses\nda sua ocorrência, geralmente em torno dos\n48 aos 50 anos de idade.","B":"O tratamento hormonal deve ser encarado como uma opção terapêutica, não sendo necessárias\nindicações específicas.","C":"O climatério é definido como um processo patológico, sendo a transição entre o período\nreprodutivo e o não reprodutivo da vida da mulher.","D":"As modificações orgânicas que ocorrem na mulher durante o climatério obrigatoriamente\nimplicam na diminuição do prazer, e podem\ninfluenciar a resposta sexual, que pode ser mais lenta.","E":"Os sintomas clássicos relacionados com o processo de hipotrofia genital que decorrem do\nhipoestrogenismo são: ressecamento vaginal, prurido, irritação, ardência e sensação de pressão."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-26595","number":"26595","sourceNumber":"26595","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual o melhor instrumento para o diagnóstico de osteroporose?","options":{"A":"ressonância magnética","B":"raios-x","C":"ultrassonografia","D":"cintilografia radioisotópica","E":"densitometria óssea"},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-26500","number":"26500","sourceNumber":"26500","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na paciente pós-menopausa sem terapia de reposição hormonal, o limite máximo da\necografia endometrial é de:","options":{"A":"1 mm.","B":"5 mm.","C":"8 mm.","D":"10 mm.","E":"12 mm."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-13245","number":"13245","sourceNumber":"13245","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Marque a que não constitui contraindicação absoluta para a terapia de reposição\nhormonal-TRH no climatério:","options":{"A":"Insuficiência hepática grave.","B":"Doença tromboembólica.","C":"Câncer de Endométrio.","D":"Sangramento genital não-diagnosticado.","E":"Diabete melito."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-13251","number":"13251","sourceNumber":"13251","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Os fatores de risco para osteoporose na pós-menopausa incluem todos os abaixo,\nexceto:","options":{"A":"Ser negra.","B":"História familiar.","C":"Baixa ingestão de cálcio durante a vida.","D":"Menopausa cirúrgica.","E":"Ser idosa."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-7493","number":"7493","sourceNumber":"7493","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação a etiologia das fístulas gênito-urinárias, o uso de fórcipe, colporrafias\nanteriores e irradiação pélvica, são causas de:","options":{"A":"Fístula uretro-vaginal.","B":"Fístula vesico-vaginal.","C":"Fístula uretero-vaginal.","D":"Lesão ureteral.","E":"Fístula cérvico-vaginal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-10013","number":"10013","sourceNumber":"10013","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual o melhor instrumento para o diagnóstico de osteoporose?","options":{"A":"Ressonância magnética.","B":"Raios-x.","C":"Densitometria óssea.","D":"Ultrassonografia.","E":"Cintilografia radioisotópica."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-62819","number":"62819","sourceNumber":"62819","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 65 anos de idade, assintomática, sem comorbidades, apresentou a\nmenopausa aos 50 anos de idade, comparece ao\nconsultório médico com o objetivo de iniciar a\nterapia hormonal da menopausa. O procedimento é:","options":{"A":"Indicar terapia de reposição hormonal por via oral.","B":"Indicar terapia de reposição hormonal por via transdérmica.","C":"Indicar terapia de reposição hormonal por via subcutânea.","D":"Indicar terapia de reposição hormonal por via percutânea.","E":"Não indicar terapia de reposição hormonal."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-49280","number":"49280","sourceNumber":"49280","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 57 anos de idade, diabética, menopausada há cinco anos, apresenta queixa de\nurgeincontinência urinária. Ao exame físico, não se observa perda urinária à manobra valsalva.\n\nApresenta sumário de urina e urocultura normais. Para conduzir esse caso:","options":{"A":"não é necessário prosseguir a investigação, provavelmente se trata de etiologia psicossomática.","B":"deve-se realizar urografia excretora.","C":"deve-se realizar estudo urodinâmico.","D":"deve-se solicitar ultrassonografia de rins e vias urinárias.","E":"deve-se solicitar passagem de cateter de duplo J."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-49282","number":"49282","sourceNumber":"49282","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 65 anos de idade, menopausada há 15 anos, sem terapia hormonal da\nmenopausa, apresenta queixa de dispareunia superficial. Ao exame clínico, observa-se atrofia\nurogenital, vagina pouco elástica e colo uterino apagado. A paciente não apresenta\ncontraindicações para uso de hormônios. A melhor opção terapêutica para esse caso é indicar:","options":{"A":"combinação estroprogestativa de uso oral.","B":"combinação estroprogestativa de uso transdérmico.","C":"combinação estroprogestativa de uso injetável.","D":"estrogênio de uso oral, apenas.","E":"estrogenoterapia de uso tópico, vaginal."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-34979","number":"34979","sourceNumber":"34979","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 40 anos de idade, G4P4AO, quatro partos vaginais, IMC: 35, tabagista há 20\nanos, apresenta quadro de perda urinária aos esforços de tosse. Ao exame físico, não se observa\nperda urinária à manobra de Valsalva. A próxima conduta é:","options":{"A":"realizar cirurgia de Kelly-Kennedy.","B":"realizar cirurgia de Burch.","C":"prescrever oxibutinina.","D":"solicitar ultrassonografia de rins e vias urinárias.","E":"solicitar estudo urodinâmico."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-27462","number":"27462","sourceNumber":"27462","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 60 anos de idade, menopausada, há 8 anos, evolui com sintomas de atrofia\nurogenital e dispareunia. Nega fogachos, irritabilidade e insônia no momento. Hipertensa em uso de\ncaptopril 50 mg/dia. Nega diabetes, cardiopatia, hepatopatia ou acidentes tromboembólicos prévios.\nNega histórico pessoal ou familiar de câncer de mama ou de endométrio. Refere osteoporose em\ntratamento com bifosfonatos. Ao exame, PA: 135 X 85 mmHg, IMC: 31. Mamas: sem alterações.\n\nAparelho gênito-urinário: vulva e vagina atróficas. Útero intrapélvico. Ovários não palpáveis.\nExames complementares de rotina para introdução de terapia hormonal sem alterações. Dos\nesquemas propostos, o indicado para essa paciente é:","options":{"A":"estrógenos conjugados 0,625 mg, via oral.","B":"estrógenos conjugados 0,625 mg, via vaginal.","C":"tibolona 1,25 mg, via oral.","D":"valerato de estradiol 1mg + acetato de noretisterona 0,5 mg, via oral.","E":"estradiol 1 mg, gel percutâneo."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-27468","number":"27468","sourceNumber":"27468","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos de idade, menopausada, IMC: 39, G5P5AO, partos vaginais, refere\nqueixa de perda urinária aos esforços de tosse e ao abaixar, que interferem na qualidade de vida.\nUrocultura negativa. Sumário de urina sem alterações. Estudo urodinâmico demonstrou PPE:\n65cmH²O, com ausência de contrações não inibidas do detrusor. O tratamento indicado para\ncorreção da incontinência urinária dessa paciente é:","options":{"A":"colpossuspensão à Burch.","B":"SLlNG transobturatório.","C":"injeção periuretral de colágeno bovino.","D":"cloridrato de oxibutinina.","E":"cirurgia de Kelly-Kennedy"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-11156","number":"11156","sourceNumber":"11156","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 55 anos de idade, sem sintomas menopausais, com história familiar materna de\nosteoporose e densitometria óssea de coluna lombar com T-score L1-L4 de -2,6 desvios-padrão. A\nopção terapêutica, nesse caso, é:","options":{"A":"carbonato ou citrato de cálcio associado à vitamina D.","B":"terapia hormonal e cálcio associado à vitamina D.","C":"bifosfonatos associados ao cálcio e à vitamina D.","D":"exercício associado ao cálcio e à vitamina D.","E":"terapia hormonal e exercícios."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-15791","number":"15791","sourceNumber":"15791","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 48 anos de idade, vem ao consultório apresentando irregularidades\nmenstruais, calorões, insônia e depressão. Ao\nexame: TA:120 X 80 mmHg, pulso de 80 bpm,\ntemperatura de 37°C. Tireoide normal à palpação, A.R. e A.C.V. sem alterações. Mamas simétricas\nsem nodulações. Abdome e genitais não revelam massas. A melhor terapêutica, a longo prazo,\nrecomendada frente aos sintomas apresentados é:","options":{"A":"estrogenioterapia.","B":"hormônio tireoidiano.","C":"antidepressivo.","D":"associação de estrogênio e progesterona.","E":"raloxifeno."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-15793","number":"15793","sourceNumber":"15793","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 48 anos de idade, vem ao consultório apresentando irregularidades\nmenstruais, calorões, insônia e depressão. Ao\nexame: TA: 120 x 80 mmHg, pulso de 80 bpm,\ntemperatura de 37°C. Tireoide normal à palpação, A.R. e A.C.V. sem alterações. Mamas simétricas\nsem nodulações. Abdome e genitais não revelam massas. A associação com câncer de mama está\ndemonstrada no Women?s Health Initiative Study com a seguinte terapêutica:","options":{"A":"Estrogênios conjugados e medroxiprogesterona.","B":"Estradiol e trimegestona","C":"Tibolona.","D":"Estradiol e levonorgestrel.","E":"Raloxifeno."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343365","number":"343365","sourceNumber":"343365","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 51 anos, em fase de climatério, com queixas importantes de fogachos\ne insônia, questiona o ginecologista a respeito\nda terapia hormonal. Refere ter muito medo de\ncâncer e que prefere ter os sintomas a correr o risco de uma neoplasia. O ginecologista deve\norientar a paciente que a TRH diminui o risco relativo de câncer de:","options":{"A":"Bexiga.","B":"Ovário.","C":"Cólon.","D":"Mama."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-281893","number":"281893","sourceNumber":"281893","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Não faz parte do diafragma urogenital:","options":{"A":"Bulboesponjoso.","B":"Transverso superficial do períneo.","C":"Elevador do ânus.","D":"Isquiocavernoso."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-215591","number":"215591","sourceNumber":"215591","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Um efeito indesejável do uso dos SERMs (moduladores seletivos de recaptação do\nestrogênio) é:","options":{"A":"Risco de doença tromboembólica semelhante à terapia com estrogênio.","B":"Risco aumentado de fratura por osteoporose.","C":"Aumento do risco de câncer de mama.","D":"Aumento do risco de câncer de endométrio."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-162495","number":"162495","sourceNumber":"162495","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério é definido pela Organização Mundial da Saúde como uma fase biológica\nda vida e não como um processo patológico. Em\nrelação a essa fase da vida da mulher, é correta\nafirmar que","options":{"A":"a densitometria óssea está indicada em todas as mulheres a partir dos 50 anos.","B":"a reposição hormonal é o tratamento de escolha para as mulheres no climatério.","C":"a ultrassonografia transvaginal não é recomendada para mulheres em vigência de terapia\nhormonal.","D":"a solicitação de exames hormonais, na maioria das vezes, não é necessária sendo o diagnóstico\ndo climatério eminentemente clínico.","E":"a mulher está no climatério quando apresenta: irregularidade menstrual, fogachos, alterações de\nhumor ou distúrbios do sono, e sintomas de atrofia geniturinária (ressecamento vaginal,\ndispareunia)."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157716","number":"157716","sourceNumber":"157716","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual é o processo fisiopatológico que acarreta as modificações urogenitais na mulher,\nna pós-menopausa?","options":{"A":"Hiperprolactinemia.","B":"Hipoestrogenismo.","C":"Hiperandrogenismo.","D":"Hipoandrogenismo."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157722","number":"157722","sourceNumber":"157722","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Durante consulta de rotina, a paciente o procura para saber quais riscos estariam\nassociados ao uso prolongado de reposição\nhormonal no climatério. Segundo diretrizes atualizadas\nsobre a TH (terapia hormonal), você diria que há evidências de maior risco de","options":{"A":"trombose venosa profunda e câncer de mama.","B":"câncer de mama e de intestino.","C":"câncer de colo uterino.","D":"câncer de endométrio e colo uterino."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157728","number":"157728","sourceNumber":"157728","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente apresentando incontinência urinária aos médios esforços. Evidenciado\nhipermobilidade do colo vesical, indique a\nalternativa contendo a cirurgia que NÃO está indicada\nnesse caso.","options":{"A":"Sling.","B":"Burch.","C":"T.V.T.","D":"Kelly-Kennedy."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157645","number":"157645","sourceNumber":"157645","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em pacientes climatéricas em terapia de reposição hormonal, os exames que devem\nser realizados anualmente são, com EXCEÇÃO de","options":{"A":"colpocitologia oncológica.","B":"dosagem hormonal.","C":"mamografia.","D":"ultrassom endovaginal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-139758","number":"139758","sourceNumber":"139758","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa em que a afirmativa esteja INCORRETA.","options":{"A":"A terapêutica de reposição hormonal combinada (estrogênio e progesterona) pós-menopausa\nmelhora a qualidade de vida.","B":"A terapêutica de reposição hormonal combinada (estrogênio e progesterona) pós-menopausa\ndiminui a incidência de infarto do miocárdio\n(IAM).","C":"A terapêutica de reposição hormonal combinada (estrogênio e progesterona) pós-menopausa\naumenta a incidência de câncer de\nendométrio.","D":"A terapêutica de reposição hormonal combinada (estrogênio e progesterona) pós-menopausa\npreserva a força muscular."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134695","number":"134695","sourceNumber":"134695","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente obesa, G3P3A0C0, com queixa de perda de urina aos mínimos esforços e\nexame Estudo Urodinâmico com diagnóstico de\nIncontinência Urinária do tipo III. Qual é a MELHOR\nconduta nesse caso?","options":{"A":"Antidepressivo tricíclico.","B":"Oxibutinina.","C":"Cirurgia de Kelly Kennedy.","D":"Cirurgia de Sling."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-134773","number":"134773","sourceNumber":"134773","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 50 anos, G3P3A0C0, vida sexual ativa, menopausada há 3 anos, refere\nperda de urina involuntariamente e com\nesforços físicos. Fez um exame de estudo urodinâmico,\ncujo resultado foi hiperatividade detrusora. Com esse diagnóstico, o tratamento pode ser realizado\nda seguinte forma, EXCETO:","options":{"A":"Antiespasmódico / cloridrato de oxibutinina.","B":"Cirurgia de Kelly-Kennedy.","C":"Anticolinérgico / brometo de propantelina.","D":"Técnicas comportamentais / biofeedback, psicoterapia e hipnose."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-111925","number":"111925","sourceNumber":"111925","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente obesa, G3P3A0C0, com queixa de perda de urina aos mínimos esforços e\nexame Estudo Urodinâmico com diagnóstico de\nIncontinência Urinária do tipo III. Qual é a MELHOR\nconduta nesse caso?","options":{"A":"Antidepressivo tricíclico.","B":"Oxibutinina.","C":"Cirurgia de Kelly Kenedy.","D":"Cirurgia de sling."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-350833","number":"350833","sourceNumber":"350833","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 72 anos, G3P3 (vaginais), hipertensa e cardiopata, procura atendimento\nginecológico pela ocorrência de sangue em\nsuas roupas íntimas. Exame físico constata prolapso\nuterino estádio 3 com ulceração por atrito. Sobre prolapso genital, marque o item correto.","options":{"A":"O diagnóstico de prolapso uterino pode ser suspeitado pelo exame físico, mas só pode ser\nconfirmado através de ultrassom transvaginal.","B":"Nos casos de prolapso uterino em que o tratamento cirúrgico é indicado, a histerectomia é\nsuficiente, sendo opcional o emprego de técnica de fixação do ápice vaginal.","C":"Pessário é um dispositivo inserido na vagina para fornecer suporte estrutural a um ou mais\ncompartimentos vaginais e é uma das opções terapêuticas para o caso acima.","D":"O tratamento do prolapso genital com cirurgia obliterativa (colpocleise) não é mais utilizado na\natualidade, pois não apresenta vantagem frente às demais técnicas."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-350831","number":"350831","sourceNumber":"350831","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 51 anos, refere durante consulta ginecológica, problemas de sono, fadiga e\nirritabilidade. Percebe libido e lubrificação vaginal diminuídas, além de \"ondas de calor\"\nfrequentes\ne de moderada intensidade. Sua última menstruação foi há 4 meses. Nega cirurgias prévias e\nantecedentes pessoais de câncer ginecológico. Prima com diagnóstico de câncer de mama aos 48\nanos. De acordo com a história e quadro clínico, assinale a alternativa correta.","options":{"A":"A terapia hormonal está contraindicada neste caso, dada a história familiar de câncer de mama.","B":"O diagnóstico é confirmado pela dosagem sérica de hormônios esteroides, gonadotrofinas,\ninibina B e hormônio antimulleriano.","C":"A paciente encontra-se na menopausa, uma vez que a faixa etária e os sintomas referidos são\ncondizentes com esta fase da vida da mulher.","D":"A indicação primária da terapia hormonal sistêmica é o tratamento de sintomas vasomotores\nintensos e moderados, associados ao\nclimatério."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-350829","number":"350829","sourceNumber":"350829","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 64 anos, G6P5(vaginais) A1, comparece à consulta ginecológica referindo,\nhá 2 anos, perca progressiva de urina ao\ntossir e espirrar e questiona o médico sobre necessidade\nde cirurgia para elevar a bexiga. Na anamnese, não há sintomas de urgência miccional e o médico\nevidencia perda urinária ao exame físico com manobras. Considerando o quadro clínico da paciente\nacima é INCORRETO afirmar:","options":{"A":"A multiparidade e a idade são fatores de risco relacionados à perda urinária aos esforços.","B":"O tratamento cirúrgico padrão-ouro para a incontinência urinária de esforço (IUE) é a\nsustentação da uretra média com tela (sling transobturatório ou sling retropúbico).","C":"O estudo urodinâmico na IUE, apresenta alterações típicas: perca urinária ao esforço durante\naumento da pressão abdominal, na ausência de contrações não inibidas do detrusor.","D":"Modificações do estilo de vida, perda ponderal e fisioterapia da musculatura do assoalho pélvico\npouco contribuem para melhora das queixas na IUE, sendo indicadas para casos de\nurgeincontinência."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321370","number":"321370","sourceNumber":"321370","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 51 anos, casada, procura atendimento por ondas de calor que ocasionam\ndespertares noturnos há cerca de 6 meses, além\nde ressecamento vaginal e dispareunia superficial\nleve. Foi histerectomizada por miomatose há 2 anos, tendo cessado o uso de dienogeste há 1 ano.\nTem histórico de tia materna com câncer de mama. Ao exame: PA = 120/75 mmHg, mucosa\nvaginal hipotrófica, útero ausente. Demais, sem alterações. Traz mamografia, exames séricos e\ncitopatológico de colo uterino atuais normais. A dosagem de FSH foi de 40 mUI/mL. Qual o\ntratamento mais adequado para essa paciente?","options":{"A":"Estrogênio isolado transdérmico.","B":"Estrogênio transdérmico e progestágeno via oral.","C":"Venlafaxina, reiniciando o uso de dienogeste por via oral.","D":"Fitoestrogênios via oral, associados a estrogênio vaginal em baixas doses."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321374","number":"321374","sourceNumber":"321374","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Lia, 36 anos, asiática, costureira; G2P2 (cesáreas); IMC = 36; procura ambulatório\nreferindo perda urinária durante tosse, espirro\nao realizar atividade física. Qual fator de risco pode\nestar relacionado?","options":{"A":"Cesárea.","B":"Profissão.","C":"Obesidade.","D":"Raça asiática."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-292886","number":"292886","sourceNumber":"292886","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 45 anos, obesa, com queixa de perda de urina ao tossir, espirrar e ao\ncaminhar. Realizou estudo urodinâmico que observou detrusor estável e pressão de perda à\nmanobra de Valsalva de 42cmH2O. Qual a melhor opção terapêutica para tratamento da\nincontinência urinária?","options":{"A":"Agente de preenchimento uretral.","B":"Colposuspensão retropúbica.","C":"Sling retropúbico.","D":"Colpoperineoplastia."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-292887","number":"292887","sourceNumber":"292887","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 85 anos, com queixa de bola na vagina. Ao exame físico, apresenta prolapso\nuterino estadio 4. Paciente hipertensa e diabética em uso de insulina e não deseja procedimento\ncirúrgico. Qual melhor opção terapêutica?","options":{"A":"Pessário vaginal.","B":"Histerectomia total vaginal.","C":"Fisioterapia do assoalho pélvico.","D":"Colpoplastia anterior e posterior."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-259774","number":"259774","sourceNumber":"259774","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 55 anos, casada, com queixa de bola na vagina. Ao exame, apresenta POP-Q:\nAa +3, Ba +4, C 0, HG 4, CP 3, CVT 8, Ap\n+2, Bp +2, D -1. Teste de estresse negativo. Qual a\nmelhor conduta?","options":{"A":"Cirurgia de Le Fort.","B":"Cirurgia de Manchester.","C":"Histerectomia vaginal total, colpoplastia anterior e colpoplastia posterior.","D":"Histeropexia sacroespinhal, colpoplastia anterior e colpoplastia posterior."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-259787","number":"259787","sourceNumber":"259787","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 50 anos, procura unidade básica de saúde relatando calores noturnos\nintensos há cerca de 6 meses, sendo mais de\n10 episódios durante a noite. Refere ainda insônia e\nirritabilidade associadas. Menopausa há 1 ano. Tem histórico de carcinoma ductal invasivo em\nmama direita há 2 anos, vindo em uso de tamoxifeno desde então. Nega outras medicações. Qual\na conduta terapêutica medicamentosa mais indicada para esse caso?","options":{"A":"Clonidina.","B":"Paroxetina.","C":"Isoflavona.","D":"Venlafaxina."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-259788","number":"259788","sourceNumber":"259788","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 47 anos, procura atendimento com queixa de dor suprapúbica ao enchimento\nvesical há uns quatro meses, sem melhora.\nA dor às vezes piora na semana anterior à\nmenstruação e alivia com a micção. Relata que vem urinando mais de 10 vezes ao dia. Nega perda\nde urina ou queixas vaginais. Ao exame físico, não apresenta anormalidades, exceto leve dor à\npalpação da parede vaginal anterior no toque vaginal. Após sumário de urina normal e urinocultura\nnegativa, qual o exame complementar mais indicado a seguir?","options":{"A":"Cistoscopia.","B":"Biópsia de bexiga.","C":"Urografia excretora.","D":"Estudo urodinâmico."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234026","number":"234026","sourceNumber":"234026","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 48 anos foi referenciada ao reumatologista com diagno?stico recente de\nartrite reumatoide. Encontra-se em uso de\ncorticoide e realizou densitometria o?ssea e o T-escore\nna coluna lombar (L1-L4) foi -2,3. Desde enta?o, vem em uso de carbonato de ca?lcio e vitamina D.\nCiclos menstruais irregulares. Negou outros antecedentes patolo?gicos ou uso de outras\nmedicac?o?es. Negava tabagismo ou etilismo. Sua ma?e teve osteoporose menopausal. Ao\nexame, IMC 24 kg/m2, altura 158 cm, sem cifose ou escoliose. Exames laboratoriais: 25-OH\nvitamina D 30 ng/mL ( VR: > 20 ng/dL) , ca?lcio 9,5 mg/dL (VR: 8,5 - 10,2 mg/dl), fo?sforo 3,0 mg/dl\n(VR: 2,5- 4,5 mg/dL) e PTH 42 pg/ml (VR: 10-65 pg/mL). Radiografia de coluna tora?cica na?o\nrevelou sinais de fratura vertebral. LEGENDA: VR: valor de refere?ncia; IMC: i?ndice de massa\ncorporal; PTH: paratormo?nio. Qual a medicac?a?o mais indicada para esta paciente?","options":{"A":"Raloxifeno.","B":"Teriparatida.","C":"Denosumab.","D":"Risendronato."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234094","number":"234094","sourceNumber":"234094","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 89 anos, com queixa de bola na vagina e dificuldade miccional. Ao exame físico\npara Quantificação do Prolapso de Órgãos Pélvicos (POP-Q), apresentou: Aa=+3, Ba=+6, C=+7,\nHG=5, CP=3, CVT=8, Ap=+3, Bp=+6, D=+5. Hipertensa de difícil controle pressórico e cardiopata.\nQual tratamento indicado?","options":{"A":"Fisioterapia.","B":"Pessário vaginal.","C":"Histerectomia vaginal.","D":"Colpoplastia anterior e posterior."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199799","number":"199799","sourceNumber":"199799","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma senhora de 56 anos, G4A0P4, todos partos vaginais, apresenta constipação há\ncerca de 30 anos, após o nascimento do\nprimeiro filho, com piora progressiva. Atualmente,\nconsegue evacuar todos os dias porém com necessidade de esforço intenso, chegando a ficar\nsentada no aparelho sanitário por até uma hora e às vezes necessitando de digitação para\nremoção das fezes, o que lhe causa grande impacto em qualidade de vida. Já tentou o tratamento\ncom laxativos, fibras alimentares e mudança de hábitos de vida sem sucesso. Já realizou exame de\nmanometria anorretal que foi normal. Qual o diagnóstico mais provável?","options":{"A":"Inércia colônica.","B":"Síndrome do intestino irritável.","C":"Prolapso de parede vaginal posterior (retocele).","D":"Síndrome da contração paradoxal do puborretal (anismo)."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199660","number":"199660","sourceNumber":"199660","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 77 anos, sem vida sexual, apresenta queixa de bola na vagina. Ao exame:\nPOP-Q: Aa +2; Ba +2; C -6; HG 4; CP 4; CVT 8; Ap -2; Bp -2; D ---. Ao teste de esforço com\nredução do prolapso observa-se perda urinária, sincrônica à tosse. Estudo urodinâmico com\nredução do prolapso evidenciou pressão de perda de 120 cm H?O. Qual a melhor conduta?","options":{"A":"Colpocleise e sling retropúbico.","B":"Colpoplastia anterior e sling transobturatório.","C":"Reeducação miccional e fisioterapia do assoalho pélvico.","D":"Colpoplastia anterior e fixação de cúpula em ligamento sacroespinhal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199682","number":"199682","sourceNumber":"199682","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 50 anos procura atendimento com queixa de ondas de calor frequentes,\ninstabilidade emocional e insônia há alguns meses.\nRefere antecedente de trombose venosa\nprofunda há dois anos. Nega outras comorbidades ou uso de medicações. Qual a melhor conduta\nterapêutica?","options":{"A":"Clonidina via oral.","B":"Fitoestrogênios via oral.","C":"17B-estradiol adesivo transdérmico.","D":"17B-estradiol associado a drosperinona via oral."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-172975","number":"172975","sourceNumber":"172975","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 39 anos, com queixa de perda urinária aos grandes esforços, como tossir e\nespirrar. Nega urgência urinária ou noctúria. Ao exame físico: ausência de prolapso genital e teste\nde esforço negativo. Qual exame inicial deve ser solicitado?","options":{"A":"Cistoscopia.","B":"Estudo urodinâmico.","C":"Sumário de urina e urinocultura.","D":"Ultrassonografia de vias urinárias."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-173034","number":"173034","sourceNumber":"173034","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 55 anos, com menopausa há 2 anos, procura atendimento ginecológico por\napresentar queixas de fogachos, insônia e alteração de humor. Aos exames complementares,\napresenta apenas hipertrigliceridemia de comorbidade, nega cirurgias prévias e os exames de\nimagem de rotina foram normais. Qual a melhor opção de tratamento, nesse caso?","options":{"A":"Uso de terapia hormonal oral com valerato de estradiol isolado.","B":"Uso de terapia hormonal oral com valerato de estradiol e drospirenona.","C":"Uso de derivados da isoflavona e progesterona micronizada natural vaginal.","D":"Uso de terapia hormonal percutânea de gel de estradiol e progesterona micronizada natural\nvaginal."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-150813","number":"150813","sourceNumber":"150813","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente feminina, 55 anos, portadora de artrite reumatoide diagnosticada há 20 anos,\ncomparece ao ambulatório de clínica médica para avaliação de rotina. Encontra-se com bom\ncontrole do quadro articular com o uso de metotrexato 15 mg/semana e prednisona 7,5 mg/dia,\nconforme prescrição do reumatologista. Qual a conduta plausível quanto ao rastreio e prevenção de\nosteoporose para a paciente?","options":{"A":"Não solicitar exames e não prescrever medicações.","B":"Não solicitar exames e prescrever suplementação de cálcio e vitamina D.","C":"Solicitar densitometria óssea e prescrever alendronato sódico, nesta consulta.","D":"Solicitar densitometria óssea e prescrever alendronato sódico, conforme o resultado do exame."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-150798","number":"150798","sourceNumber":"150798","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 75 anos, casada, ativa sexualmente, com queixa de sensação de bola e peso\nna vagina há cerca de 5 anos. Ao exame físico,\na quantificação do prolapso de órgãos pélvicos\n(POP-Q): Aa = +3; Ba = +8; C = +9; HG = 4; CP = 3; CVT = 11; Ap = +3; Bp = +8; D = +9. Qual\n\ndiagnóstico e tratamento mais recomendados?","options":{"A":"Prolapso de parede vaginal anterior E-III, posterior E-III e uterino E-IV; histerectomia vaginal\nassociada a colpocleise.","B":"Prolapso de parede vaginal anterior E-IV, posterior E-IV e uterino E-IV; histerectomia vaginal\nassociada a colpocleise.","C":"Prolapso de parede vaginal anterior E-IV, posterior E-IV e uterino E-IV; histerectomia vaginal\nassociada a fixação no ligamento uterossacral.","D":"Prolapso de parede vaginal anterior E-III, posterior E-III e uterino E-IV; histerectomia vaginal\nassociada a fixação no ligamento sacro espinhal, colpoplastia anterior e posterior."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-126985","number":"126985","sourceNumber":"126985","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 80 anos, viúva; tabagista, IMC = 40 kg/m2; diabética; com prolapso anterior\n(Ba = +6); posterior (Bp = +4) e apical\n(C = +6) (POP-Q). Nega incontinência urinária aos\nesforços e urgeincontinência. Sem vida sexual ativa. À redução do prolapso, não observamos\nperda de urina aos esforços. Foram observadas úlceras na mucosa vaginal exteriorizada. Sobre\no caso clínico e seu tratamento, assinale a alternativa CORRETA:","options":{"A":"A histerectomia via vaginal associada a sling transobturatório é o procedimento indicado.","B":"A sacrocolpopexia abdominal não está indicada uma vez que não corrige o prolapso apical.","C":"A colpocleise pode ser indicada se a paciente não tiver mais intenção de ter relação sexual.","D":"O uso de pessário vaginal não está indicado uma vez que a paciente apresenta prolapso\navançado\n\ne úlceras na mucosa."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-81322","number":"81322","sourceNumber":"81322","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 60 anos de idade, 49 Kg e 1,56 m de altura, vem ao consultório médico\nsolicitando orientação terapêutica para as suas dores lombares e cervicais. Ao ser interrogada,\núltima menstruação aos 45 anos, teve asma e usava corticoides nas frequentes crises de então e\naté hoje ?tem crises de intolerância à lactose?, pois não consegue seguir a dieta recomendada.\n\nSua irmã teve câncer de mama aos 54 anos. Trazia laudo da densitometria óssea visualizada na\nfigura abaixo (VER IMAGEM). Qual a melhor terapêutica farmacológica para o caso em questão?","options":{"A":"Alendronato de sódio.","B":"Calcitonina de salmão.","C":"Estrogênio/progestacional.","D":"Cálcio combinado com vitamina D."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/81322.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-65681","number":"65681","sourceNumber":"65681","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 51 anos de idade, nulípara, sem terapia hormonal, vem apresentando\num quadro de sangramento uterino após um ano e\nmeio da menopausa. Apresentou dois episódios\nde sinusiorragia recentemente. O exame ginecológico foi normal. Diante do exame\nultrassonográfico mostrado na figura (VER IMAGEM), qual o procedimento diagnóstico mais bem\nindicado para a avaliação do problema da paciente?","options":{"A":"Histerossonografia.","B":"Vídeo-histeroscopia.","C":"AMIU, aspiração manual intrauterina.","D":"Dilatação e curetagem uterina fracionada.","E":"Biópsia endometrial com cureta de Novak ou Duncan ou pipelle."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/65681.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-30867","number":"30867","sourceNumber":"30867","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Maria José, 49 anos, consulta um ginecologista por apresentar rubor facial e calores\nrepentinos associados à sudorese, também chamados de fogachos. Os sintomas mais comumente\ndecorrem de:","options":{"A":"Disfunção térmica no hipotálamo.","B":"Vasoconstricção periférica.","C":"Temperatura aumentada do núcleo arqueado.","D":"Secreção pulsátil do hormônio luteinizante.","E":"Deficiência de esteroides sexuais."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37634","number":"37634","sourceNumber":"37634","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação a evidências que corroboram o uso da terapia de reposição hormonal no\nclimatério, assinale a alternativa incorreta.","options":{"A":"A avaliação para osteoporose com\ndensitometria óssea é recomendada apenas\npara as mulheres que apresentam fatores de\nrisco, não sendo recomendado para a\npopulação em geral.","B":"Há evidência sugerindo que a terapia de\nreposição hormonal tenha ação profilática\ncontra infecções urinárias de repetição.","C":"Uma série de estudos observacionais\nsugere um efeito protetor do estrogênio nas\npacientes portadoras de cardiopatia\nisquêmica.","D":"A terapia estrogênica isolada aumenta\nsignificativamente o ganho de peso."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-32539","number":"32539","sourceNumber":"32539","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Dos ligamentos seguintes, os que fornecem maior sustentação ao útero com fins de\nprevenção de prolapso são os ligamentos:","options":{"A":"redondos.","B":"infundibulopélvicos.","C":"uterossacros.","D":"cardinais.","E":"próprios dos ovários."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-36998","number":"36998","sourceNumber":"36998","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 56 anos de idade, menopausada desde os 48 anos, tem como única\nqueixa secura vaginal que leva ao desconforto na relação sexual com seu marido. Após\ninvestigação clínica, conclui-se que ela não apresenta comorbidades. O caso deve ser mais bem\nconduzido com a prescrição de terapia:","options":{"A":"progestagênica isolada.","B":"hormonal combinada sistêmica.","C":"estrogênica tópica.","D":"estrogênica sistêmica."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37469","number":"37469","sourceNumber":"37469","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Dona Josefa, de 51 anos de idade, com história de amenorreia há aproximadamente\num ano, apresenta-se com secura vaginal e ondas\nde calor há dois meses, associados ao\nnervosismo, à insônia, a dores musculares e cansaço físico. Além disso, refere palpitações\nesporádicas, incontinência urinária, diminuição da libido e constipação. Quais são os critérios\nclínico e laboratorial para o diagnóstico de Dona Josefa?","options":{"A":"Amenorreia por mais de 90 dias e LH aumentado.","B":"Amenorreia por mais de 90 dias e FSH diminuído.","C":"Amenorreia por mais de 12 meses e LH aumentado.","D":"Amenorreia por mais de 12 meses e FSH aumentado.","E":"Amenorreia por mais de 12 meses e FSH diminuído."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-24344","number":"24344","sourceNumber":"24344","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A urgeincontinência decorre da hiperatividade da seguinte estrutura anatômica:","options":{"A":"Músculo levantador do ânus;","B":"Fáscia vesical;","C":"Músculo detrusor;","D":"Ligamento de Mackenrodt."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-27738","number":"27738","sourceNumber":"27738","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"De acordo com a classificação POP-Q (Pelvic Organ Prolapse Quantification) proposta\npela Sociedade Internacional de Continência, NÃO\né correta a seguinte descrição:","options":{"A":"D: ponto mais profundo do fundo de saco posterior","B":"Aa: linha média da parede vaginal anterior 3 cm acima do hímen","C":"C: ponto mais distal do colo uterino ou cúpula vaginal, se histerectomia prévia","D":"gh: medida do hiato genital (do meio do meato uretral externo até a margem posterior do hímen)","E":"Bp: análogo posterior do ponto Aa"},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-6910","number":"6910","sourceNumber":"6910","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Como se denomina o espaço entre as fibras que compõem o diafragma pélvico\nprincipal por onde se dão os prolapsos genitais?","options":{"A":"Retinaculum uteri.","B":"Espaço pélvico subperitoneal.","C":"Hiato urogenital.","D":"Losângulo de Michaelis.","E":"Espaço de Retzius."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9093","number":"9093","sourceNumber":"9093","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Aparecida, 48 anos, branca, casada, G2P2A0, procurou seu médico de família com\nqueixa de irregularidade menstrual com\nalterações na quantidade do fluxo, da duração e frequência\ndos ciclos. Queixou-se também de ondas de calor. Aparecida é tabagista, sedentária, obesa,\nhipertensa. Assinale a alternativa que contenha apenas fatores de risco para fraturas por\nosteoporose presentes em Aparecida:","options":{"A":"Ser casada, branca e sedentária.","B":"Ser branca, sedentária, tabagista.","C":"Ser sedentária, obesa e hipertensa.","D":"Ser G2P2A0, tabagista e sedentária."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9096","number":"9096","sourceNumber":"9096","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Aparecida, 48 anos, branca, casada, G2P2A0, procurou seu médico de família com\nqueixa de irregularidade menstrual com\nalterações na quantidade do fluxo, da duração e frequência\ndos ciclos. Queixou-se também de ondas de calor. Aparecida é tabagista, sedentária, obesa,\nhipertensa. Em relação à definição do período que vive Aparecida, qual seria o MELHOR\ndiagnóstico do médico de família?","options":{"A":"Climatério/perimenopausa.","B":"Climatério/menopausa.","C":"Climatério precoce.","D":"Climatério tardio."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-13456","number":"13456","sourceNumber":"13456","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 64 anos sem sintomatologia significativa, com menopausa há 14 anos, com\nútero intacto, história familiar de câncer de mama na mãe, osteoporose detectada à densitometria\ne hipercolesterolemia. Está indicado:","options":{"A":"Estrogênio associado à progesterona.","B":"Raloxifeno.","C":"Tibolona.","D":"Progesterona sintética.","E":"Estrógeno conjugado."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-7272","number":"7272","sourceNumber":"7272","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual o achado mais constante na transição para a menopausa?","options":{"A":"Elevação de progesterona.","B":"Elevação de estriol.","C":"Elevação de FSH.","D":"Queda de estradiol.","E":"Queda de estriol."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-16019","number":"16019","sourceNumber":"16019","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 51 anos relata início recente de fogachos e dispareunia. Sua\nmenopausa ocorreu há seis meses. Marque a causa mais\nprovável de sua dispareunia:","options":{"A":"Vestibulite vulvar.","B":"Vaginose bacteriana.","C":"Cisto da glândula de Bartholin.","D":"Vaginite atrófica.","E":"Vaginite por cândida."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-14039","number":"14039","sourceNumber":"14039","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual é o primeiro hormônio a apresentar queda no climatério?","options":{"A":"FSH.","B":"LH.","C":"Inibina.","D":"S-DHEA.","E":"Prolactina."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-14046","number":"14046","sourceNumber":"14046","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Durante avaliação de rotina de paciente na pós-menopausa, a densitometria mostrou\nT-score 2,7 DP abaixo da média do adulto\njovem. Qual das alternativas abaixo mostra tratamento\ninapropriado para esta paciente?","options":{"A":"Carbonato de cálcio + vitamina D.","B":"Risedronato.","C":"Alendronato.","D":"Calcitonina.","E":"Teriparatida."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-349731","number":"349731","sourceNumber":"349731","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa correta que apresenta uma medicação osteoformadora indicada\nno tratamento da osteoporose de alto e muito alto\nrisco de fraturas.","options":{"A":"Alendronato.","B":"Denosumabe.","C":"Ácido Zoledrônico.","D":"Teriparatida.","E":"Raloxifeno."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-365574","number":"365574","sourceNumber":"365574","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Nas pacientes climatéricas, com sintomas vasomotores associados a contraindicações\nao uso de terapias de reposição hormonal, como\no câncer de mama, a terapia com outras\nmedicações torna-se importante. A respeito do assunto, assinale a alternativa correta.","options":{"A":"Nas pacientes com hipoestrogenismo vaginal, cremes à base de estradiol podem ser utilizados,\nmesmo nas pacientes com câncer de mama com receptores positivos.","B":"O uso de venlafaxina e desvenlafaxina permite o controle dos sintomas vasomotores, sem uso\nde hormônios, com eficácia semelhante.","C":"Na síndrome urogenital da menopausa, o uso de terapias à base de laser e radiofrequência\napresenta eficácia demonstrada para controle dos\nsintomas vasomotores.","D":"Nas pacientes com desejo sexual hipoativo, o uso da tibolona pode demonstrar eficácia, mesmo\nsem tratamento da atrofia genital."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-365572","number":"365572","sourceNumber":"365572","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O sistema nervoso autônomo influencia diretamente a bexiga e o aparelho urinário. Nas\npacientes com bexiga hiperativa, alguns receptores vesicais são importantes e se relacionam com o\ntratamento medicamentoso. Quanto ao uso dos anticolinérgicos, assinale a alternativa correta.","options":{"A":"Os receptores nicotínicos vesicais interagem com os medicamentos para a bexiga hiperativa,\nimpedindo a contração da musculatura detrusora.","B":"Os receptores muscarínicos M2 e M3 se encontram presentes também nas glândulas salivares,\ngerando a xerostomia como efeito colateral ao uso dos anticolinérgicos.","C":"Os receptores B3 vesicais são inibidos pelo uso dos anticolinérgicos, permitindo o relaxamento\nvesical durante a fase de armazenamento\nvesical.","D":"Os anticolinérgicos agem nos receptores alfa da uretra, permitindo maior contração esfincteriana\ne a consequente inibição da perda urinária."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-365571","number":"365571","sourceNumber":"365571","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O prolapso é uma doença muito prevalente e, em geral, relaciona-se com a\nincontinência urinária. Vários são os fatores de\nrisco para o desenvolvimento do prolapso. A esse\nrespeito, assinale a alternativa correta.","options":{"A":"Os fatores de risco que se relacionam com o prolapso incluem a idade, o aumento da pressão\nabdominal em doenças como obesidade e DPOC, além do número de partos.","B":"O tratamento do prolapso apical (DeLancey III) consiste, principalmente, na histerectomia\nvaginal, sem necessidade de plicatura\nposterior como a fixação sacroespinhosa ou a aproximação\ndos paramétrios.","C":"A classificação de Baden Walker permite a classificação visual, de forma objetiva, dos prolapsos,\npermitindo que haja uma reprodutibilidade adequada.","D":"Na classificação de POP-Q, a paciente histerectomizada deixa de apresentar o ponto C, e a\ncúpula vaginal passa a ser classificada pelo ponto D"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-365565","number":"365565","sourceNumber":"365565","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na pelve feminina, diversos ligamentos são importantes para a sustentação dos órgãos\npélvicos. No que tange a esse assunto, assinale a alternativa correta.","options":{"A":"O ligamento sacroespinhoso possui, em seu limite medial, a artéria glútea superior e, no limite\nlateral, o nervo obturatório.","B":"O nervo hipogástrico margeia o ligamento sacroespinhoso, com chance de lesão caso a fixação\nocorra no terço médio.","C":"O nervo pudendo situa-se na porção lateral do ligamento sacroespinhoso, e a raiz nervosa de\nS4, na porção medial do ligamento. Por essa razão, a fixação deve ocorrer no terço médio.","D":"O músculo isquiococcigeo situa-se na porção inferior do ligamento sacroespinhoso, podendo ser\nutilizado como parte do complexo de fixação na cirurgia."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-322189","number":"322189","sourceNumber":"322189","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 53 anos vem ao ambulatório de uroginecologia referindo perda urinária.\nPossui histórico de 5 partos via vaginal e apresenta menopausa há 7 anos, sem terapia de\nreposição hormonal. No exame físico ginecológico, apresenta prolapso da parede anterior grau 1,\nsem perda urinária à Valsalva. Apresenta resultado de estudo urodinâmico que revelou a presença\nde contrações não inibidas do músculo detrusor como único achado. Nesse caso, a abordagem\nterapêutica inicial é:","options":{"A":"Correção cirúrgica do prolapso de útero e da parede vaginal anterior por via vaginal.","B":"Terapia de reposição hormonal apenas com estrogênio via oral.","C":"Colpossacrofixação.","D":"Tratamento comportamental podendo ou não associar anticolinérgicos.","E":"Correção de parede vaginal anterior com tela, via vaginal."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-322205","number":"322205","sourceNumber":"322205","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A bexiga hiperativa é uma das causas de perda urinária na mulher e está relacionada à\nhiperatividade do músculo detrusor. Sobre esse assunto, é correto afirmar que","options":{"A":"o tratamento da bexiga hiperativa é cirúrgico com sling transobturatório.","B":"para o diagnóstico, é imprescindível a realização do estudo urodinâmico em todos os casos.","C":"para o tratamento, é possível usar medicações anticolinérgicas e técnica de biofeedback.","D":"a imipramina é o tratamento de primeira escolha.","E":"a bexiga hiperativa acontece devido ao prolapso de parede vaginal anterior."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-305342","number":"305342","sourceNumber":"305342","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O termo menopausa se refere a um ponto no tempo um ano após a cessação da\nmenstruação. A média de idade das mulheres\nvivenciando seu último período menstrual (FMP, de\nFinal Menstrual Period) é 51,5 anos, mas a cessação das menstruações, causada por insuficiência\novariana, pode ocorrer em qualquer idade. A transição menopáusica é um evento hormonal e\nsociocultural complexo. Diante do exposto, assinale a alternativa correta.","options":{"A":"É preferível o uso de estrogênio isolado em paciente com história suspeita ou confirmada de\ncâncer de mama.","B":"Em pacientes não histerectomizadas, devemos fazer o uso, preferencialmente, de estrogênio\nisolado.","C":"A terapia de reposição hormonal na menopausa não atua como fator protetor de fratura\nosteoporóticas.","D":"O uso do estrogênio pode ser feito em pacientes que tiveram endometriose prévia.","E":"A terapia de reposição hormonal está indicada na presença de sintomas que impactam na\nqualidade de vida da mulher. Quando presente sintomas de diminuição da função sexual e libido,\npode-se adicionar androgênio à TRH, como no Tibolona®."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-298943","number":"298943","sourceNumber":"298943","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Um paciente de 72 anos de idade possui diagnóstico de osteoporose há um ano, em\ntratamento, e histórico de fratura de quadril há cerca de sete meses. Procurou atendimento na\nequipe Estratégia Saúde da Família (ESF) por ter apresentado torção do tornozelo direito em sua\ncaminhada matinal, com queixa de intensa dor local e dificuldade para deambular. Ao exame físico,\ndemonstra dor à palpação, limitação da movimentação articular e discreto edema local. Tendo em\nvista esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. A partir do\nexame físico, é possível presumir possibilidade de fratura, sendo importante realizar radiografia do\nlocal da lesão para confirmação diagnóstica e adequado tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-298944","number":"298944","sourceNumber":"298944","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Um paciente de 72 anos de idade possui diagnóstico de osteoporose há um ano, em\ntratamento, e histórico de fratura de quadril há cerca de sete meses. Procurou atendimento na\nequipe Estratégia Saúde da Família (ESF) por ter apresentado torção do tornozelo direito em sua\ncaminhada matinal, com queixa de intensa dor local e dificuldade para deambular. Ao exame físico,\ndemonstra dor à palpação, limitação da movimentação articular e discreto edema local. Tendo em\nvista esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\n\nConsiderando o histórico prévio de fraturas dessa paciente, e possivelmente outra fratura atual, é\nimportante orientar medidas que reduzam risco de novas lesões, sendo a densitometria óssea o\nmelhor indicador para o risco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284332","number":"284332","sourceNumber":"284332","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos de idade, com paridade G8P8(N8C0)A0 e vida sexual ativa,\nqueixa-se de \"bola na vagina\". O exame ginecológico, à inspeção estática e dinâmica, revelou\nexistência de distopia genital, conforme o seguinte: Aa = +3; Ba = +6; C = +5; D = X; Bp = +5; Ap =\n\n+2; CVT = 9; HG = 6; e CP = 1. Com base nos achados de quantificação de prolapso dos órgãos\npélvicos (POPq) expressos nessa situação\nhipotética, julgue o item a seguir. A reconstrução do\ncorpo perineal seria uma das alternativas cirúrgicas necessárias para o restabelecimento anatômico\nda paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284333","number":"284333","sourceNumber":"284333","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos de idade, com paridade G8P8(N8C0)A0 e vida sexual ativa,\nqueixa-se de \"bola na vagina\". O exame ginecológico, à inspeção estática e dinâmica, revelou\nexistência de distopia genital, conforme o seguinte: Aa = +3; Ba = +6; C = +5; D = X; Bp = +5; Ap =\n\n+2; CVT = 9; HG = 6; e CP = 1. Com base nos achados de quantificação de prolapso dos órgãos\npélvicos (POPq) expressos nessa situação\nhipotética, julgue o item a seguir. A colpocleise à Le Fort\nseria uma alternativa cirúrgica razoável para a paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284334","number":"284334","sourceNumber":"284334","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos de idade, com paridade G8P8(N8C0)A0 e vida sexual ativa,\nqueixa-se de \"bola na vagina\". O exame ginecológico, à inspeção estática e dinâmica, revelou\nexistência de distopia genital, conforme o seguinte: Aa = +3; Ba = +6; C = +5; D = X; Bp = +5; Ap =\n\n+2; CVT = 9; HG = 6; e CP = 1. Com base nos achados de quantificação de prolapso dos órgãos\npélvicos (POPq) expressos nessa situação hipotética, julgue o item a seguir. A histerectomia\nvaginal seria uma alternativa cirúrgica razoável para a paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284335","number":"284335","sourceNumber":"284335","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos de idade, com paridade G8P8(N8C0)A0 e vida sexual ativa,\nqueixa-se de \"bola na vagina\". O exame ginecológico, à inspeção estática e dinâmica, revelou\nexistência de distopia genital, conforme o seguinte: Aa = +3; Ba = +6; C = +5; D = X; Bp = +5; Ap =\n\n+2; CVT = 9; HG = 6; e CP = 1. Com base nos achados de quantificação de prolapso dos órgãos\npélvicos (POPq) expressos nessa situação hipotética, julgue o item a seguir. A colpofixação\nsacroespinhosa seria uma alternativa cirúrgica possível para a paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284336","number":"284336","sourceNumber":"284336","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos de idade, com paridade G8P8(N8C0)A0 e vida sexual ativa,\nqueixa-se de \"bola na vagina\". O exame ginecológico, à inspeção estática e dinâmica, revelou\nexistência de distopia genital, conforme o seguinte: Aa = +3; Ba = +6; C = +5; D = X; Bp = +5; Ap =\n\n+2; CVT = 9; HG = 6; e CP = 1. Com base nos achados de quantificação de prolapso dos órgãos\npélvicos (POPq) expressos nessa situação hipotética, julgue o item a seguir. A colposacrofixação\nseria uma alternativa cirúrgica possível para a paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-261276","number":"261276","sourceNumber":"261276","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente possui diagnóstico de menopausa precoce.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-261277","number":"261277","sourceNumber":"261277","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente possui apenas dois fatores de risco para osteoporose, identificados no respectivo\nhistórico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-261278","number":"261278","sourceNumber":"261278","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\navaliação complementar dessa paciente deve incluir, entre outros exames, a dosagem de vitamina\nD, calcemia, fosfatase alcalina, creatinina, TSH e paratormônio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-261279","number":"261279","sourceNumber":"261279","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\nhipótese de hiperparatireoidismo secundário deve ser considerada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-261280","number":"261280","sourceNumber":"261280","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente não deveria ter realizado densitometria óssea, já que esse exame deve ser solicitado a\npartir dos 65 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-284349","number":"284349","sourceNumber":"284349","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Durante a realização do estudo urodinâmico, valores de pressão de perda acima de 90\ncmH?O fundamentaram o diagnóstico de incontinência urinária de esforço decorrente de fator\nintrínseco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274418","number":"274418","sourceNumber":"274418","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente menopausada de 60 anos apresenta queixa de fogachos intensos, com\nrepercussão social e emocional. Após avaliação\nginecológica, a paciente solicita prescrição de\nterapia hormonal (TH), entretanto apresenta diversas comorbidades, listadas nas alternativas. O\nmédico contraindicou a TH devido à","options":{"A":"diabetes melito controlada.","B":"hepatite C crônica.","C":"hipertensão arterial controlada.","D":"osteoporose.","E":"porfiria."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-196658","number":"196658","sourceNumber":"196658","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Certa paciente de 48 anos de idade, G3P3A0, com obesidade grau 1, comparece a\numa consulta ginecológica de rotina. Refere\nque a última menstruação foi há três semanas, com\nciclo menstrual regular de 28 dias. Envergonhada, relata que tem molhado a roupa íntima de urina\ncom frequência, pois sente um desejo súbito de urinar e não consegue contê-lo até ir ao banheiro,\no que a desestimula de sair de casa. Informa que toma cerca de três xícaras de café preto por dia.\nNega perda urinária quando tosse ou realiza algum esforço. Apresenta pressão arterial de 130\nmmHg x 80 mmHg. FC de 68 bpm, saturação de 98% em ar ambiente. Sem perda urinária ao\nexame físico. Com relação a esse caso clínico, julgue o item a seguir. A paciente apresenta\nincontinência urinária de urgência, devendo-se orientar medidas comportamentais como primeira\nlinha de tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-196704","number":"196704","sourceNumber":"196704","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 61 anos de idade comparece a uma consulta ginecológica de rotina.\nRefere menopausa há seis anos e nega sintomas\nclimatéricos atuais. Informa que ultimamente tem\nsofrido quedas frequentes em casa e questiona se possui algum risco de fraturas ósseas. Relata\nsedentarismo, tabagismo e baixa ingesta de alimentos contendo cálcio. Com base nesse caso\nclínico e nos conhecimentos médico correlatos, julgue o item a seguir. Deve-se pensar em solicitar\ndensitometria óssea.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-196705","number":"196705","sourceNumber":"196705","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 61 anos de idade comparece a uma consulta ginecológica de rotina.\nRefere menopausa há seis anos e nega sintomas\nclimatéricos atuais. Informa que ultimamente tem\nsofrido quedas frequentes em casa e questiona se possui algum risco de fraturas ósseas. Relata\nsedentarismo, tabagismo e baixa ingesta de alimentos contendo cálcio. Com base nesse caso\nclínico e nos conhecimentos médico correlatos, julgue o item a seguir. Deve-se orientar a paciente\nà realização de exercício físico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-196598","number":"196598","sourceNumber":"196598","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 61 anos de idade comparece a uma consulta ginecológica de rotina.\nRefere menopausa há seis anos e nega sintomas\nclimatéricos atuais. Informa que ultimamente tem\nsofrido quedas frequentes em casa e questiona se possui algum risco de fraturas ósseas. Relata\nsedentarismo, tabagismo e baixa ingesta de alimentos contendo cálcio. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Tabagismo não é fator de\nrisco para osteopenia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-154358","number":"154358","sourceNumber":"154358","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 52 anos de idade , apresenta queixa de perda urinária episódica quando ri ou\ntosse. Hipertensa, faz uso de losartana há três anos. G4P4C0A0, sua ultima menstruação foi aos\n47 anos de idade. Ao exame físico, encontra-se IMC = 29 kg/m². Foi realizado o POP-Q com o\nseguinte resultado: Aa +3, Ba +6, C -2, Hg 4, Cp 1,5, TVL 7, Ap -3 , Bp -2, D -9. Com relação a\nesse caso clínico, é correto afirmar que o diagnóstico é de","options":{"A":"prolapso uterino.","B":"incontinência urinária de urgência.","C":"enterocele.","D":"prolapso de cúpula vaginal.","E":"cistocele."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-131833","number":"131833","sourceNumber":"131833","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa que não configura uma contraindicação para a terapêutica\nhormonal da menopausa:","options":{"A":"Doença coronariana ou cerebrovascular.","B":"Sangramento vaginal de causa desconhecida.","C":"Lesão precursora para câncer de mama.","D":"Hipertensão arterial controlada.","E":"Doença hepática descompensada."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-135024","number":"135024","sourceNumber":"135024","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Julgue o item subsecutivo, que trata de distúrbios endócrinos, hematológicos,\nreumatológicos e renais encontrados com\nfrequência em pacientes que procuram ambulatório de\nginecologia. Situação hipotética: Uma mulher de cinquenta e quatro anos de idade, cuja\nmenopausa se iniciou havia um ano, procurou atendimento médico, apresentando queixa de\nhirsutismo leve e ressecamento da mucosa vaginal. Assertiva: Nesse caso, o mais provável é que\nessa sintomatologia seja resultado da redução do SHBG e dos estrogênio que ocorre nas mulheres\napós a falência ovariana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-140641","number":"140641","sourceNumber":"140641","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito da terapêutica hormonal da menopausa, julgue o item a seguir. Os\nestrogênios endógenos e exógenos estimulam a\nsíntese hepática da angiotensina, que, por sua\nvez, promove o aumento da aldosterona plasmática mediante a ativação do sistema renina -\nangiotensina - aldosterona.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-105576","number":"105576","sourceNumber":"105576","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 54 anos de idade compareceu à consulta de rotina com o\nginecologista. Referiu perda de urina a médios\nesforços e sangramento vaginal há duas semanas.\nAntecedentes ginecológicos: menarca aos doze anos, menopausa aos 51 anos de idade,\nG1PN1A0, sem antecedentes familiares de câncer ginecológico. Foram solicitados exames com os\nseguintes resultados: Ecografia transvaginal: útero em AVF com volume de 80 cm³, endométrio de\n10 mm, ovários atróficos; Mamografia: BI-RADS 2; Estudo urodinâmico: incontinência urinária de\nesforço com defeito esfincteriano. Para o achado no estudo urodinâmico, a melhor opção\nterapêutica é a:","options":{"A":"Cirurgia de Kelly-Kennedy.","B":"Histerectomia vaginal.","C":"Correção de prolapso vesical.","D":"Videolaparoscopia para levantamento vesical.","E":"Cirurgia de alça (Sling)."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-108141","number":"108141","sourceNumber":"108141","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação aos distúrbios endócrinos e metabólicos, julgue o item que se segue. A\nmenopausa ocorre mais precocemente em\nmulheres multíparas, ao passo que a menopausa tardia\nrelaciona-se à nuliparidade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-79659","number":"79659","sourceNumber":"79659","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Trata-se de uma condição patológica que acomete mulheres, em sua maioria, após a\nmenopausa, resultando em herniação da parede vaginal posterior e o reto fica subjacente para o\ncanal vaginal. Esse quadro refere-se a:","options":{"A":"septo vaginal transverso.","B":"sarcoma botrioide.","C":"retocele.","D":"enterocele.","E":"cistos vaginais."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-82132","number":"82132","sourceNumber":"82132","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Julgue o item subsequente relativo a doenças benignas do aparelho reprodutor\nfeminino. A enterocele consiste na herniação\ndo intestino grosso para o lúmen vaginal, sendo um\ndistúrbio comum da sustentação pélvica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64252","number":"64252","sourceNumber":"64252","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à anatomia e fisiologia do trato genital feminino, julgue o item a seguir.\nLesões ou enfraquecimento na estrutura de\nsustentação dos órgãos pélvicos, constituídos pelo\ncomplexo cardinal-uterossacro, pode ocasionar prolapso uterino, enterocele ou prolapso da cúpula\nvaginal.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64738","number":"64738","sourceNumber":"64738","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente com 50 anos, sem queixas, menopausada há 3 anos procura a Unidade\nBásica de Saúde para exames de rotina ginecológica. Sendo assim, assinale a alternativa que\napresenta exames que devem ser solicitados para essa paciente.","options":{"A":"Ultrassonografia mamária bilateral, colposcopia e ultrassonografia transvaginal.","B":"Hormônio tireoestimulante e tiroxina livre anual, mamografia semestral e densitometria óssea se\napresentar fator de risco.","C":"Mamografia, citologia cervicovaginal e densitometria óssea.","D":"Mamografia, citologia oncótica, cervicovaginal semestral e calciúria de 24 horas.","E":"Mamografia, ultrassonografia de mama, ultrassonografia transvaginal, ácido úrico e fator\nreumatoide."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-49158","number":"49158","sourceNumber":"49158","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito de ginecologia, julgue o item seguinte. A cirurgia de Kelly-Kennedy para\ncorreção de incontinência urinária de esforço\ntem taxa de cura/melhoramento elevada, acima de\n60%.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-45733","number":"45733","sourceNumber":"45733","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 64 anos de idade procura atendimento médico com queixa de \"bola na\nvagina\". O exame ginecológico mostra os seguintes pontos da classificação POP-Q: Aa = +2, Ba =\n\n+2, C = -4, D = -6, Bp = -2, Ap = -2, HG = 4, CP = 3, CVT = 8. Nesse caso, o diagnóstico para o\ncaso é:","options":{"A":"distopia de parede vaginal anterior.","B":"distopia de parede vaginal posterior.","C":"prolapso uterino.","D":"prolapso de cúpula vaginal.","E":"hipertrofia de colo uterino."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37954","number":"37954","sourceNumber":"37954","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com referência à anatomia pélvica e o prolapso genital, julgue o item. O diafragma\nurogenital é uma estrutura muscular que fecha\na cavidade pélvica. Ele se origina no arco tendíneo,\ninsere-se no tendão central do períneo e tem como principal ação ajudar os músculos da parede\nanterior do abdome a conter o conteúdo abdominal e pélvico.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-37955","number":"37955","sourceNumber":"37955","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com referência à anatomia pélvica e prolapso genital, julgue o item. Distúrbios comuns\nda sustentação pélvica em mulheres, a cistocele\ne a retocele resultam da perda de suporte das\nparedes vaginais anterior e posterior, acarretando, respectivamente, herniação da bexiga através\nda parede anterior da vagina e protrusão do reto para a luz da vagina.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-29710","number":"29710","sourceNumber":"29710","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com referência às patologias benignas em ginecologia, julgue o item seguinte. A\nparidade é um fator de risco para o prolapso de órgãos pélvicos, entretanto a nuliparidade não\ngarante ausência de risco para essa patologia.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8602","number":"8602","sourceNumber":"8602","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 55 anos de idade, menopausada há 5 anos, já em uso de bifosfonato,\nsuplementação de cálcio e vitamina D prescritos\nhá 2 anos pela ginecologista. Traz densitometria\nóssea recente (D.O.- a seguir), solicita avaliação e orientação clínica.\n\nApós anamnese apropriada e exame clínico, conclui-se que não há outras alterações clínicas,\nantecedentes pessoais ou familiares de interesse. Foi então avaliada a D.O. (VER IMAGEM).\nPode-se concluir que a paciente apresenta:","options":{"A":"Exame normal.","B":"Osteopenia.","C":"Doença de Paget.","D":"Hiperparatireoidismo.","E":"Osteoporose."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/8602.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-7559","number":"7559","sourceNumber":"7559","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 50 anos de idade teve seu último ciclo menstrual há um ano após\nhisterectomia subtotal abdominal. Apresenta sintomas do tipo fogachos, déficit de memória e\nadinamia. Sua mãe, de 70 anos de idade, fraturou recentemente o quadril, e uma prima de 2° grau\ntem câncer de mama. A paciente está preocupada com a osteoporose e pergunta de que forma\nesta pode ser evitada. Um exame de densitometria óssea de três anos atrás quando menstruava\nmostrava valores abaixo da faixa etária esperada. Qual das seguintes medidas preventivas seria a\nmais útil para esta paciente?","options":{"A":"Iniciar um programa de exercício com atividade de impacto.","B":"Orientar a ingestão de cálcio para 1.500 mg/dia e vitamina D 800 UI/dia, além do sol e exercício\nfísico.","C":"Orientar a ingestão de cálcio para 1.500 mg/dia e vitamina D 400 UI/dia, monitorar através de\ndensitometria óssea até atingir níveis de osteoporose para iniciar droga antireabsortiva.","D":"Orientar a ingestão de cálcio para 1.000 mg/dia e vitamina D 800 UI/dia, associar terapia\nhormonal estrogênica.","E":"Orientar a ingestão de cálcio para 1.000 mg/dia e vitamina D 200 UI/dia, associar droga\nantireabsortiva."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8611","number":"8611","sourceNumber":"8611","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 58 anos de idade, em uso de terapia hormonal combinada contínua há 6\nanos. Há 4 meses apresenta sangramento vaginal esporádico discreto. A ultrassonografia mostra\nendométrio de 8 mm e miométrio homogêneo. Com esses dados a conduta é:","options":{"A":"suspender a medicação e solicitar mamografia.","B":"manter a medicação e indicar biópsia de endométrio.","C":"aumentar a dose de progestagênio e solicitar mamografia.","D":"suspender a medicação e indicar biópsia de endométrio.","E":"aumentar a dose de progestagênio e indicar biópsia de endométrio."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-334903","number":"334903","sourceNumber":"334903","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"No que se refere ao prolapso genital, assinale a alternativa correta.","options":{"A":"As pacientes com poucos ou nenhum sintoma, mesmo com prolapsos de graus pequenos (como\ngrau 2), devem ser orientadas a realizar\nprocedimentos cirúrgicos, a fim de prevenir a progressão\nda doença.","B":"A classificação de Baden-Walker utiliza, de forma quantitativa, as medidas dos diversos\ncompartimentos do assoalho pélvico, permitindo um método científico mais adequado para a\nclassificação dos prolapsos.","C":"O prolapso possui um impacto importante na qualidade de vida das pacientes e deve ser\navaliado de forma individualizada, para um melhor tratamento dessas pacientes.","D":"Os fatores de risco dos prolapsos costumam estar relacionados somente aos partos vaginais e\ninstrumentalizados, sendo a incidência de prolapsos nas pacientes nulíparas considerada rara.","E":"Não há tratamento conservador nos casos de prolapso vaginal descritos na literatura, sendo\nsomente o tratamento cirúrgico possível."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343445","number":"343445","sourceNumber":"343445","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"No que diz respeito à terapia hormonal no climatério, é INCORRETO afirmar:","options":{"A":"Embora comum em mulheres até 60 anos, o risco relacionado à terapia hormonal para eventos\ntromboembólicos venosos graves aumenta com a idade mesmo não associado com trombofilias.","B":"O principal objetivo do tratamento na atrofia vulvovaginal é o alívio dos sintomas, como falta de\nlubrificação, dispareunia e ressecamento vaginal. Para mulheres com sintomas moderados e\nseveros, as preparações de baixa dose de estrogênio vaginal são eficazes e geralmente seguras.","C":"A Colelitíase, a Colecistite e a Colecistectomia ocorrem mais frequentemente em mulheres que\nusam estrogenioterapia por via oral, presumidamente\npelo efeito hepático da primeira passagem\napós a ingestão oral.","D":"Os sintomas vasomotores frequentes na peri e pós-menopausa acometem até 80% das\nmulheres. A terapia hormonal é considerada o tratamento mais efetivo para essas mulheres no\nalívio desses sintomas."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-343461","number":"343461","sourceNumber":"343461","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 46 anos, chega ao ambulatório de ginecologia com queixa de irregularidade\nmenstrual há um ano. Conta que, no início,\nmenstruava duas vezes ao mês, mas que atualmente\nestá com atraso menstrual de três meses. Refere ondas de calor de moderada intensidade,\nsudorese noturna iniciadas no mesmo período. Relata ainda insônia, labilidade emocional e\nausência de lubrificação vaginal. De acordo com o fenômeno descrito acima, é CORRETO afirmar:","options":{"A":"A área pré-óptica medial do hipotálamo contém o núcleo termorregulador, que controla a\ntranspiração e a vasodilatação, originando sintomas vasomotores, como os fogachos.","B":"Baixas concentrações de estrogênios são mais importantes nos fogachos do que a rápida\noscilação ou supressão desse hormônio.","C":"A hiperplasia endometrial sem atipias é a situação perimenopáusica que melhor explicaria os\nsangramentos erráticos na transição menopausal.","D":"A produção hepática da Globulina Ligadora de Hormônios Sexuais (SHBG) sempre aumenta\napós a menopausa, o que diminui os níveis\nde esteroides sexuais livres, promovendo irregularidade\nmenstrual."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-307119","number":"307119","sourceNumber":"307119","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"As pacientes com queixa de perda urinária aos esforços são mais comuns após a\nquarta década de vida, porém essa condição pode ser observada em pacientes mais jovens.\nAcerca desse assunto, assinale a alternativa correta. Alternativas:","options":{"A":"A incontinência urinária de esforço por defeito esfincteriano intrínseco é mais comum em idosas\ne caracteriza-se por pressão de perda (VLPP)\nsuperior a 90 cmH2O.","B":"A incontinência urinária de esforço por hipermobilidade uretral é um defeito mais grave e\ncaracteriza-se por pressão de perda VLPP inferior a 60 cmH2O.","C":"A fisioterapia do assoalho pélvico é uma alternativa terapêutica bem indicada em casos de\nhipermobilidade uretral.","D":"Os slings de uretra média, embora haja uma discussão mundial com relação à segurança, à\neficácia e aos riscos, ainda são os tratamentos de escolha para a incontinência urinária de esforço\nem todas as pacientes.","E":"O uso de técnicas cirúrgicas com tecido nativo de correção da fáscia vesical (como a cirurgia de\nKelly-Kennedy) demonstrou ser boa alternativa ao uso de telas sintéticas na correção da\nincontinência urinária."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-301315","number":"301315","sourceNumber":"301315","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 58 anos de idade, G5PN4PC1, sem comorbidades, refere perda\nurinária ao tossir e sensação de \"bola na\nvagina\", que a incomoda durante o ato sexual. Foi\nhisterectomizada há 10 anos por miomatose uterina. Ao exame físico, identificam-se perda urinária\nsob valsalva e prolapso de cúpula vaginal. O estudo urodinâmico evidencia pressão de perda de\n102 cm H?O. Considerando o caso clínico apresentado, julgue os itens de 72 a 75. A paridade é\num fator de risco para o prolapso vaginal dos órgãos pélvicos, desde que a via de parto seja\nvaginal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-301316","number":"301316","sourceNumber":"301316","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 58 anos de idade, G5PN4PC1, sem comorbidades, refere perda\nurinária ao tossir e sensação de \"bola na\nvagina\", que a incomoda durante o ato sexual. Foi\nhisterectomizada há 10 anos por miomatose uterina. Ao exame físico, identificam-se perda urinária\nsob valsalva e prolapso de cúpula vaginal. O estudo urodinâmico evidencia pressão de perda de\n102 cm H?O. Considerando o caso clínico apresentado, julgue os itens de 72 a 75. A cirurgia de Le\nFort está contraindicada para a paciente em questão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-301317","number":"301317","sourceNumber":"301317","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 58 anos de idade, G5PN4PC1, sem comorbidades, refere perda\nurinária ao tossir e sensação de \"bola na\nvagina\", que a incomoda durante o ato sexual. Foi\nhisterectomizada há 10 anos por miomatose uterina. Ao exame físico, identificam-se perda urinária\nsob valsalva e prolapso de cúpula vaginal. O estudo urodinâmico evidencia pressão de perda de\n102 cm H?O. Considerando o caso clínico apresentado, julgue os itens de 72 a 75. A colpofixação\nsacroespinhosa é uma boa opção terapêutica para o caso em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-301318","number":"301318","sourceNumber":"301318","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 58 anos de idade, G5PN4PC1, sem comorbidades, refere perda\nurinária ao tossir e sensação de \"bola na\nvagina\", que a incomoda durante o ato sexual. Foi\nhisterectomizada há 10 anos por miomatose uterina. Ao exame físico, identificam-se perda urinária\nsob valsalva e prolapso de cúpula vaginal. O estudo urodinâmico evidencia pressão de perda de\n102 cm H?O. Considerando o caso clínico apresentado, julgue os itens de 72 a 75. O tratamento\nindicado para a perda urinária é a fisioterapia pélvica associada a medicação anticolinérgica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-301321","number":"301321","sourceNumber":"301321","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 49 anos de idade, com nódulo endurecido na mama direita e\nmamografia BI-RADS 5, teve diagnóstico de câncer\nde mama. Antecedentes pessoais e familiares:\nG3PN3, ciclos menstruais irregulares, DUM há quatro meses e mãe com diagnóstico de câncer de\nmama unilateral aos 66 anos de idade. Ao exame físico, constatam-se mamas de médio volume,\nretração no quadrante inferior lateral direito com desvio do mamilo ipsilateral, nódulo palpável na\nregião retroareolar direita de 4,5 cm X 3 cm e axila clinicamente negativa. O estudo\nanatomopatológico da lesão evidenciou carcinoma ductal invasivo, grau histológico 1 de\nNottingham e imuno-histoquímica com receptores hormonais (estrogênio e progesterona)\nnegativos, HER-2 positivo e índice de Ki-67 de 12%. Com base no caso clínico apresentado, julgue\no item a seguir. Considerando que a paciente está no período do climatério, o primeiro hormônio a\napresentar queda é a inibina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-263342","number":"263342","sourceNumber":"263342","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher com 48 anos de idade vai a uma consulta na Unidade Básica de Saúde\ncom queixa de calorões há três meses. As ondas\nde calor começam de repente, percorrem o tórax,\npescoço e cabeça, geram suor abundante e terminam espontaneamente após alguns minutos.\n\nUltimamente, os fogachos acontecem cerca de 3 a 4 vezes por dia e, às vezes, ocorrem durante a\nnoite, atrapalhando o sono. A paciente está ficando cansada e irritada desde que o sintoma\ncomeçou. Usa como método contraceptivo a laqueadura tubária. Ela teve ciclos menstruais\nirregulares nos últimos anos (menstruava a cada 2 ou 3 meses) e está em amenorreia há 6 meses.\nDeseja alguma solução para os calorões que a estão \"deixando louca\". Não fuma, nega doenças\ncrônicas e nega história de câncer de mama ou endométrio. Sua história familiar é negativa para\ndoenças ginecológicas. Em seu exame físico, apresenta IMC = 23,5 kg/m², PA = 110 x 70 mmHg e\nexame ginecológico e de mamas sem alterações dignas de nota. Todos os exames\ncomplementares de rotina estão normais. Considerando os dados clínicos da paciente, assinale a\nalternativa que apresenta a conduta adequada.","options":{"A":"Solicitar dosagem de FSH e ultrassonografia transvaginal para definir o diagnóstico de\nclimatério.","B":"Prescrever inibidor seletivo de recaptação de acetilcolina como primeira opção terapêutica.","C":"Solicitar dosagem de estradiol e progesterona para avaliar a função ovariana.","D":"Prescrever terapia hormonal com estrogênio e progestagênio."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-273322","number":"273322","sourceNumber":"273322","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 62 anos, G6P6A0, com quadro de ?bola na vagina? há 1 mês, referindo perda\nurinária aos pequenos esforços. O POP-Q da paciente é (Aa : +3 ) ( Ba : +7 ) ( C +7 ) ( Gh 4 ) ( Pb\n3 ) ( Cvt 10 ) ( Ap 0 ) ( Bp 0) (D -3). Paciente coronariopata com 2 stents prévios, obesa, com\ndisfunção miocárdica importante. Acerca da propedêutica do caso assinale a INCORRETA:","options":{"A":"Paciente tem prolapso uterino grau IV, associado a perda aos esforços portanto o tratamento\nsugerido é histerectomia vaginal associada a\nSling transobturatorio.","B":"Paciente com prolapso total associado a incontinência urinária de esforço que deve ser melhor\navaliada por meio de estudo urodinâmico, com indicação cirúrgica imediata.","C":"Paciente com prolapso apical associado a incontinência urinária de esforço porém com\ncontraindicação importante a cirurgia devido comorbidades.","D":"Paciente com alongamento hipertrófico do colo uterino com necessidade de tratamento com\npessario."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-268918","number":"268918","sourceNumber":"268918","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 70 anos de idade compareceu ao consultório médico com queixa de\nbola na vagina, associada a incontinência urinária. Refere urgência com urgeincontinência, noctúria\ncom três ou quatro episódios noturnos, sem dificuldade de esvaziamento vesical, com jato urinário\nforte. Nega perda urinária aos esforços. Ao exame físico, a paciente apresenta a distribuição de\nPOP-Q a seguir. Aa +3 Ba +5 C +8; Gh 6 Pb 1 cvt 9; Ap +3 Bp +5 D +5. Tendo em vista esse caso\nclínico, em relação à terapêutica indicada, assinale a alternativa correta.","options":{"A":"Nas pacientes com prolapso uterino grau 2, como nesse caso clínico, o tratamento pode incluir\nfisioterapia do assoalho pélvico, pessário e (ou) cirurgia.","B":"O tratamento da bexiga hiperativa, como no caso apresentado, inclui modificação dos hábitos de\nvida, micção programada e uso de medicações anticolinérgicas, como a mirabegrona, e (ou)\nsimpaticomiméticas, como a oxibutinina.","C":"O estudo urodinâmico deve ser realizado em todos os casos de incontinência urinária e permite\ndiferenciar as bexigas hiperativas dos defeitos esfincterianos.","D":"O tratamento dos prolapsos genitais pode incluir a plicatura do ligamento uterossacro\nvideolaparoscópica e a colpopromontofixação videolaparoscópica.","E":"A contraindicação ao uso de anticolinérgico na bexiga hiperativa inclui glaucoma de ângulo\naberto, Alzheimer e Parkinson."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-266480","number":"266480","sourceNumber":"266480","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Define-se distopia genital, conforme a Sociedade Internacional de Continência, como a\ndescida de, no mínimo, uma das seguintes estruturas: parede vaginal anterior, parede vaginal\nposterior ou ápice da vagina (útero ou cúpula vaginal após histerectomia). Acerca desse assunto,\njulgue o próximo item. Tendo em vista que o risco de desenvolvimento do prolapso dos órgãos\npélvicos aumenta com a idade, com a elevação da expectativa de vida, observa-se cada vez mais\ncasos desse problema acometendo a população: o quadro clínico da distopia é bastante variável,\nmas sabe-se que muitas pacientes são assintomáticas, o que dificulta o diagnóstico precoce; no\nentanto, quanto maior o grau da distopia, mais prevalente a sintomatologia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-266481","number":"266481","sourceNumber":"266481","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Define-se distopia genital, conforme a Sociedade Internacional de Continência, como a\ndescida de, no mínimo, uma das seguintes estruturas: parede vaginal anterior, parede vaginal\nposterior ou ápice da vagina (útero ou cúpula vaginal após histerectomia). Acerca desse assunto,\njulgue o próximo item. Uma paciente com urgência urinária e noctúria, na ausência de infecções do\ntrato urinário ou outra patologia urinária ou de prolapso aparente, deve ser submetida à\ninvestigação de incontinência urinária de esforço, pois, nesse caso, o diagnóstico mais provável é\nde síndrome da bexiga hiperativa e o tratamento padrão-ouro consiste na realização de um\nprocedimento de sling de uretra média.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-266482","number":"266482","sourceNumber":"266482","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Define-se distopia genital, conforme a Sociedade Internacional de Continência, como a\ndescida de, no mínimo, uma das seguintes estruturas: parede vaginal anterior, parede vaginal\nposterior ou ápice da vagina (útero ou cúpula vaginal após histerectomia). Acerca desse assunto,\njulgue o próximo item. Na classificação pop-q, são considerados pontos dinâmicos o Aa e o Ba\n(pontos da parede vaginal anterior); o AP e o BP (pontos na parede vaginal posterior; e o CVT\n(comprimento total da vagina).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-266483","number":"266483","sourceNumber":"266483","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Define-se distopia genital, conforme a Sociedade Internacional de Continência, como a\ndescida de, no mínimo, uma das seguintes estruturas: parede vaginal anterior, parede vaginal\nposterior ou ápice da vagina (útero ou cúpula vaginal após histerectomia). Acerca desse assunto,\njulgue o próximo item. No caso de uma gestante que desenvolva um prolapso estádio II durante\numa gestação de segundo trimestre, indica-se que, assim que a paciente fizer sua consulta de\n\npós-parto, ela seja encaminhada para propedêutica cirúrgica ginecológica para evitar danos\nmaiores futuramente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274664","number":"274664","sourceNumber":"274664","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A incontinência urinária é a perda involuntária da urina pela uretra, sendo englobada\npela Organização Mundial de Saúde nas grandes\nsíndromes geriátricas. Considerando os tipos\nmais comuns de incontinência urinária, quanto à incontinência urinária mista, é CORRETO afirmar:","options":{"A":"É a combinação das incontinências de transbordamento e por esforço, esta caracterizada pela\nperda de urina ao movimento do indivíduo.","B":"É a combinação das incontinências de urgência e por transbordamento, sendo esta\ncaracterizada pela vontade repentina de fazer xixi.","C":"É a combinação das incontinências de esforço e por transbordamento, sendo esta mais comum\nnos homens porque pode ser causada pelo\naumento do tamanho da próstata.","D":"É a combinação das incontinências de urgência e por esforço, sendo esta mais frequente no\nsexo feminino."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274666","number":"274666","sourceNumber":"274666","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A Infecção do Trato Urinário (ITU) é uma das causas mais comuns de infecção na\npopulação geral, sendo mais comuns no sexo feminino. As ITUs bacterianas podem acometer\nuretra, próstata, bexiga ou rins, tendo como características:","options":{"A":"A noctúria, que consiste na perda de urina ocorrendo durante o seu dia a dia.","B":"Enurese noturna, que consiste na vontade de urinar várias vezes durante a noite.","C":"Enurese noturna, que consiste na perda involuntária de urina durante o sono.","D":"A noctúria, que consiste no desejo imperioso e súbito de urinar."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-291536","number":"291536","sourceNumber":"291536","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 49 anos de idade foi atendida no ambulatório de ginecologia de um\nhospital na sua região. Suas principais\nqueixas eram sintomas genitourinários, como prurido, ardor,\nressecamento e irritação vulvar; disúria e urgência miccional de início há 8 meses. Esses sintomas\nlevaram à redução da libido e impacto negativo na sua vida sexual. A vulva apresenta hiperemia\nleve e a vagina hipotrófica. O útero tinha tamanho normal ao toque, com sua mobilidade preservada\ne indolor. Gesta 3; para 3 (partos normais). Nesse caso, o melhor esquema terapêutico para essa\nmulher é utilizar","options":{"A":"terapias hormonais locais.","B":"antifúngico oral.","C":"creme vaginal antifúngico.","D":"estradiol via transdérmica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-230604","number":"230604","sourceNumber":"230604","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher com pelo menos 2 ciclos menstruais aumentado, podendo ficar em amenorreia\npor 60 dias ou mais, segundo o consenso STRAW\n(Stages of Reproductive Aging Workshop)\nencontra-se na chamada:","options":{"A":"perimenopausal precoce.","B":"perimenopausal tardio.","C":"menopausal precoce.","D":"menopausal tardio."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-227436","number":"227436","sourceNumber":"227436","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação a patologias ginecológicas benignas, julgue o próximo item. Em mulheres,\nalterações estruturais e numéricas do cromossomo X levam ao desenvolvimento de falência\novariana prematura, pois ambos os cromossomos X devem estar intactos para que ocorra a\nmanutenção da função ovariana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-202977","number":"202977","sourceNumber":"202977","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 36 anos procura o consultório ginecológico, pois está tentando gestar\nhá oito meses sem sucesso. A última\nmenstruação ocorreu há um ano, desde que suspendeu o uso\nde anticoncepcional oral. Realizou exames para investigação. Nos exames laboratoriais,\n\nnotaram-se as seguintes alterações: FSH 96 mUI/ml e estradiol < 11 mUI/ml (valores de referência\nnormais, FSH < 10 mUI/ml e estradiol > 60 mUI/ml). Acerca desse caso clínico, quanto ao\ndiagnóstico mais provável, assinale a alternativa correta.","options":{"A":"Bloqueio menstrual por uso prolongado de anticoncepcional.","B":"Hipogonadismo hipergonadotrófico em razão de falência ovariana prematura.","C":"Hipogonadismo hipogonadotrófico hipotalâmico.","D":"Anovulação crônica, provavelmente por síndrome dos ovários micropolicísticos.","E":"Impossível de ser definido com esses dados. É necessário que seja feita a dosagem de LH e de\nprogesterona."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-203082","number":"203082","sourceNumber":"203082","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 52 anos de idade, com histórico de menopausa aos 45 anos de idade,\nestá em uso de tibolona 2,5 mg ao dia há seis meses em razão de queixa de fogachos. Em\necografia transvaginal realizada em consulta de rotina, foi evidenciado endométrio com espessura\nde 18 mm. Considerando-se esse caso clínico, assinale a alternativa correta.","options":{"A":"O uso de estrogênio oral por seis meses pode compensar o quadro, já que esse hormônio tem\npapel estabilizador de endométrio.","B":"Acompanhamento do crescimento da espessura endometrial, por meio de ecografia transvaginal\na cada três meses, deve ser feito.","C":"A histeroscopia com biópsia endometrial é o padrão ouro para investigação dessa paciente.","D":"A histerectomia total com salpingooforectomia bilateral é a primeira escolha como conduta\nterapêutica inicial.","E":"Não é necessário fazer investigação histopatológica, bastando suspender a reposição hormonal\npara resolução do espessamento endometrial."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-206095","number":"206095","sourceNumber":"206095","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente menopausada sem terapia de reposição hormonal. A concentração sérica de\nestradiol é de, aproximadamente,","options":{"A":"10 a 20 pg/ml.","B":"40 a 50 pg/ml.","C":"60 a 70 pg/ml.","D":"70 a 90 pg/ml."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-206105","number":"206105","sourceNumber":"206105","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em mulheres menopausadas e com útero, assinale a opção CORRETA em relação à\nTerapia de Reposição Hormonal (TRH):","options":{"A":"Deve ser utilizada somente progesterona.","B":"Deve ser utilizado somente estrógeno + progesterona cíclico.","C":"Deve ser utilizado somente estrógeno + progesterona contínuo.","D":"Pode ser utilizado estrógeno + progesterona de forma cíclica ou contínua."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-206112","number":"206112","sourceNumber":"206112","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à menopausa:","options":{"A":"O estradiol passa a ser o principal estrógeno produzido no tecido adiposo.","B":"O FSH só apresenta aumento significativo meses após a última menstruação.","C":"A produção de estrona passa a ser feita a partir da conversão periférica de testosterona.","D":"Os fogachos podem ter início ainda com ciclos menstruais regulares."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212049","number":"212049","sourceNumber":"212049","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à insuficiência ovariana primária, julgue o item que se segue. Níveis\nelevados de Hormônio Folículo Estimulante\n(FSH) nas pacientes em climatério, frequentemente,\nlevam à formação de cistos funcionais nos ovários por estímulo de folículos residuais; por isso,\nrecomenda-se a estrogenoterapia para evitar a formação desses cistos ou tratá-los.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212098","number":"212098","sourceNumber":"212098","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à insuficiência ovariana primária, julgue o item que se segue. Ao contrário\nda terapia de reposição hormonal por via oral,\nque pode aumentar o risco de ocorrerem eventos\ntromboembólicos venosos, o uso de estradiol transdérmico não tem sido associado a esse risco.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212032","number":"212032","sourceNumber":"212032","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à insuficiência ovariana primária, julgue o item que se segue. Embora o\ndiagnóstico da insuficiência ovariana primária seja clínico, a confirmação laboratorial poderá ser\nfeita por meio da dosagem plasmática de estrogênio.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-177236","number":"177236","sourceNumber":"177236","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 56 anos de idade, do sexo feminino, G1P1C0A0, com histórico de parto\nnormal sem intercorrências há 32 anos,\napresenta incontinência urinária, que está piorando com o\npassar dos anos. Atualmente, ela necessita usar forro íntimo continuamente. Não apresenta\ncomorbidades. Está ansiosa para solucionar tal problema. Ao exame físico, constatam-se paredes\nvaginais atróficas e ausência de distopia genital. A paciente realizou estudo urodinâmico, que\nevidenciou perdas urinárias esporádicas não relacionadas ao aumento da pressão abdominal.\n\nConsiderando o referido caso clínico assinale a alternatica correta.","options":{"A":"Uso de estrogênio tópico não está indicado nesse caso, mesmo que como coadjuvante no\ntratamento, por não ter efeito sobre a mucosa do trato urinário.","B":"Existe indicação de tratamento cirúrgico com sling transobturatório para a paciente.","C":"A primeira escolha para o tratamento da paciente é o uso de anticolinérgico.","D":"O tratamento ideal é a colporrafia anterior para sustentação da bexiga.","E":"Os principais causadores desse tipo de incontinência urinária são as contrações voluntárias do\nmúsculo detrusor e, por isso, a correção de hábitos costuma ser suficiente para a melhoria dos\nsintomas."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-175140","number":"175140","sourceNumber":"175140","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 58 anos, com queixa de perda urinária aos médios esforços. Menopausa\naos 49 anos, não fez terapia de reposição\nhormonal. Ao exame físico: cistocele discreta e manobra\nde valsalva negativa. A melhor abordagem inicial é:","options":{"A":"Realizar Cirurgia de Kelly-Kennedy.","B":"Administrar estrogênio tópico e solicitar estudo urodinâmico posteriormente.","C":"Realizar Cirurgia de Burch.","D":"Realizar histerectomia total abdominal e Cirurgia de Burch."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-175144","number":"175144","sourceNumber":"175144","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Geralmente, a primeira manifestação clínica do climatério é:","options":{"A":"Dispareunia.","B":"Atrofia urogenital.","C":"Insônia.","D":"Irregularidade menstrual."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-175164","number":"175164","sourceNumber":"175164","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em mulheres menopausadas não usuárias de terapia de reposição hormonal, a\navaliação colpocitológica demonstra predomínio de células do tipo:","options":{"A":"intermediárias","B":"basais","C":"superficiais","D":"metaplásicas"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183883","number":"183883","sourceNumber":"183883","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de quarenta e oito anos de idade queixa-se de irregularidade menstrual\ncaracterizada por atrasos frequentes nos\núltimos seis meses, sensação de fraqueza. ressecamento\nvaginal, dificuldade para dormir, episódios noturnos de calor e sudorese. Ela relata fazer uso\ndiário\nde sinvastatina e que o resultado da última mamografia realizada foi normal. No exame físico,\nevidenciou-se: obesidade - IMC de 34; PA de 140 mmHg x 85 mmHg; FC de 88 bpm; temperatura\nnormal, tireoide normal à palpação; exame cardiopulmonar sem alterações; exame mamário sem\nmassas ou secreção; a genitália externa não revela massa. Com relação a esse caso clínico, julgue\no item subsequente. A paciente pode apresentar alto risco de desenvolvimento de condições\ncrônicas como diabetes melito e doença cardiovascular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183889","number":"183889","sourceNumber":"183889","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de quarenta e oito anos de idade queixa-se de irregularidade menstrual\ncaracterizada por atrasos frequentes nos\núltimos seis meses, sensação de fraqueza. ressecamento\nvaginal, dificuldade para dormir, episódios noturnos de calor e sudorese. Ela relata fazer uso\ndiário\nde sinvastatina e que o resultado da última mamografia realizada foi normal. No exame físico,\nevidenciou-se: obesidade - IMC de 34; PA de 140 mmHg x 85 mmHg; FC de 88 bpm; temperatura\nnormal, tireoide normal à palpação; exame cardiopulmonar sem alterações; exame mamário sem\nmassas ou secreção; a genitália externa não revela massa. Com relação a esse caso clínico, julgue\no item subsequente. O diagnóstico mais provável é de estado perimenopausal (climatério).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-158016","number":"158016","sourceNumber":"158016","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 50 anos de idade, com última menstruação há quatro anos, deseja usar\nterapia de reposição hormonal, já que vem apresentando alteração de humor e fogachos que\ninterferem na qualidade do sono. Nega outras queixas ginecológicas. Antecedentes pessoais =\nG3P3C3A0, laqueadura tubária aos 35 anos. Nega outras cirurgias prévias. Com base no caso\nclínico, e considerando os conhecimentos médicos correlatos, assinale a alternativa CORRETA.","options":{"A":"O perfil hormonal característico da mulher no climatério é representado por FSH e estradiol\naumentados.","B":"Os fogachos podem ser tratados, de forma mais eficaz e com menos efeitos colaterais, com o\nuso de creme vaginal de estrogênio.","C":"Caso se opte pela reposição hormonal para essa paciente, deve ser feita inicialmente com\nestrogênio via oral isolado.","D":"Em pacientes em uso de reposição hormonal, o rastreio para câncer de mama deve ser feito\ncom intervalo de seis meses, mesmo na ausência de alterações.","E":"O uso da terapia de reposição hormonal aumenta o risco de câncer de mama e, por isso, a\nnecessidade de sua manutenção deve ser reavaliada periodicamente."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-154490","number":"154490","sourceNumber":"154490","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Acerca do climatério, assinale a afirmação INCORRETA:","options":{"A":"A menopausa costuma ocorrer mais cedo em tabagistas e nulíparas.","B":"O fogacho é um sintoma mais frequente durante a pré-menopausa embora possa ocorrer\ntambém após a menopausa em um grupo seleto de pacientes.","C":"Em pacientes não histerectomizadas a terapia hormonal com reposição de estrogênio deve ser\nsempre associada à progesterona.","D":"Durante o climatério, a osteoporose e os sintomas vasomotores constituem importantes\nproblemas de saúde.","E":"A menopausa acontece devido à depleção de folículos ovarianos capazes de responder às\ngonadotrofinas."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-159622","number":"159622","sourceNumber":"159622","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito do climatério e das terapias a ele relacionadas, julgue o item subsequente.\nNa terapia de reposição hormonal, o uso de\nprogestágenos tem efeito antimiótico, promove atrofia\nendomentrial e reduz o risco de câncer endometrial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-159618","number":"159618","sourceNumber":"159618","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito do climatério e das terapias a ele relacionadas, julgue o item subsequente.\nAs irregularidades menstruais ocorridas no período da\nperimenopausa devem-se à maturação\nirregular dos folículos ovarianos, o que pode resultar em ciclos ovulatórios ou não.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-159621","number":"159621","sourceNumber":"159621","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito do climatério e das terapias a ele relacionadas, julgue o item subsequente. A\nterapia de reposição hormonal feita com estrogênios e progesterona é contraindicada a pacientes\nportadoras de câncer colorretal, doença cujos fatores de risco são obesidade, sedentarismo e\ningesta de carne vermelha.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-159495","number":"159495","sourceNumber":"159495","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A respeito do climatério e das terapias a ele relacionadas, julgue o item subsequente. O\nuso de bifosfonados é indicado no\ntratamento de pacientes com osteoporose pós-menopáusica,\ndevido aos efeitos antirreabsortivos que apresenta nos osteoclatos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-104763","number":"104763","sourceNumber":"104763","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 49 anos de idade, em uso de DIU de progestágeno, consultou-se com\nginecologista, pois desejava saber a respeito da menopausa. Considerando esse caso hipotético,\nassinale a alternativa que apresenta o exame mais simples a ser solicitado para o diagnóstico do\nperíodo do climatério.","options":{"A":"Estradiol.","B":"Prolactina.","C":"Testosterona.","D":"FSH.","E":"LH."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-111276","number":"111276","sourceNumber":"111276","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na pós-menopausa, a redução dos níveis de estrogênio é responsável por numerosas\nmanifestações clínicas genitais e/ou extragenitais. Podemos dizer que as alterações hormonais\nnesse período se associam a(o):","options":{"A":"Aumento do colesterol total e HDL colesterol e diminuição do LDL colesterol.","B":"Aceleração no ritmo de maturação do epitélio vaginal.","C":"Diminuição do risco para câncer de cólon.","D":"Aumento da pressão intra-uretral.","E":"Aumento da reabsorção óssea."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-80712","number":"80712","sourceNumber":"80712","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 47 anos de idade, histerectomizada há seis anos por miomatose uterina,\ncomparece à consulta ginecológica\nreferindo fogachos há seis meses. Informa que há cerca de dois\nanos submeteu-se a uma cirurgia mamária devido à hiperplasia ductal com atipias, e faz uso de\ntamoxifeno desde então. Com base no caso hipotético, assinale a alternativa que apresenta a\nmelhor conduta para essa paciente.","options":{"A":"Prescrever estrógeno isolado cíclico.","B":"Prescrever estrógeno contínuo com progestágeno associado.","C":"Prescrever tibolona.","D":"Suspender o uso do tamoxifeno.","E":"Não prescrever terapia de reposição hormonal."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64427","number":"64427","sourceNumber":"64427","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São considerados fatores de risco para osteoporose:","options":{"A":"Raça branca, tabagismo, ingestão excessiva de cafeína.","B":"Deficiência de fósforo, hipogonadismo e sexo masculino.","C":"Menopausa precoce, idade acima de 50 anos, baixa estatura.","D":"Raça negra, tabagismo e sexo feminino.","E":"Ingestão excessiva de álcool, sexo masculino e raça negra."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-30974","number":"30974","sourceNumber":"30974","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à anatomia e fisiologia do sistema reprodutor feminino, julgue o seguinte\nitem: Os ligamentos de sustentação do útero\nconsistem nos ligamentos uterossacrais, ligamentos\ntransversos da cérvice, ligamentos redondos e ligamentos largos.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-138724","number":"138724","sourceNumber":"138724","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à osteoporose, é correto afirmar que","options":{"A":"são considerados fatores de risco de osteoporose não modificáveis: idade, pequena estrutura\ncorporal, origem étnica, história familiar de\nosteoporose.","B":"são considerados fatores de risco de osteoporose modificáveis: tabagismo, consumo excessivo\nde\n\nalcóol, terapia de reposição hormonal estrogênica.","C":"nas mulheres com antecedentes familiares de osteoporose, a avaliação diagnóstica da\ndensidade mineral óssea deve ser recomendada a partir de 40 anos.","D":"o uso de reposição de cálcio e vitamina D aliada ao uso de bifosfonatos deve ser considerado\napenas nos casos de ocorrência de fraturas\nprévias.","E":"os efeitos de depleção óssea, induzidos pelo uso prolongado de corticóides, no hipotireoidismo e\nna doença renal crônica podem ser evitados\npela ingesta complementar de cálcio."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321170","number":"321170","sourceNumber":"321170","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 48 anos, G5 PV4 A1, comparece à consulta ginecológica queixando perda\nde urina ao tossir e espirrar. Ao exame\nfísico observa-se perda objetiva de urina em manobra de\nvalsalva. Em relação ao tratamento da incontinência urinária de esforço, assinale a alternativa\nINCORRETA:","options":{"A":"A fisioterapia visando fortalecimento do assoalho pélvico constitui boa opção terapêutica.","B":"Mulheres incontinentes com sinal de atrofia vaginal podem se beneficiar do uso de estrogênio\ntópico.","C":"Em pacientes obesas ou com sobrepeso deve- se estimular a perda de peso.","D":"Os medicamentos anticolinérgicos são primeira linha para o tratamento desse tipo de\nincontinência."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-334740","number":"334740","sourceNumber":"334740","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 53 anos chega ao ambulatório queixando-se de fogachos, ressecamento\nvaginal e alterações de humor. Ela refere\namenorreia há 15 meses, obesidade grau 2, tem\ndislipidemia e infarto agudo do míocárdio há 3 meses. Assinale a alternativa que apresenta uma\nconduta terapêutica inadequada para essa paciente.","options":{"A":"Cimicifuga Actea via oral.","B":"Promestrieno via vaginal.","C":"Estradiol + noretisterona via oral.","D":"Inibidor seletivo da recaptação de serotonina."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-335091","number":"335091","sourceNumber":"335091","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério corresponde à transição da mulher do ciclo reprodutivo para o não\nreprodutivo, ocorrendo habitualmente entre os 40\ne 65 anos de idade. O uso de terapia hormonal\n(TH) nessa fase visa a reduzir os sintomas e prevenir disfunções causadas pela deficiência de\nestrogênio a longo prazo. Com relação às indicações da TH no climatério, assinale a alternativa\ncorreta.","options":{"A":"A TH protege contra doença de Alzheimer.","B":"A TH está contraindicada na presença de sintomas de atrofia vulvar e vaginal.","C":"A principal indicação para a TH é o alívio das ondas de calor e sintomas associados.","D":"A TH não evita a perda óssea associada à menopausa, mesmo quando iniciada precocemente."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-337650","number":"337650","sourceNumber":"337650","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O decréscimo folicular ovariano e, por consequência a perda na produção estrogênica,\nobservada durante a peri e pós-menopausa\ndesencadeia uma série de sinais e sintomas. Nesse\ncontexto, analise as afirmativas a seguir: I- A intensidade e a frequência dos fogachos têm pico na\nfase tardia da perimenopausa e na fase precoce da pós-menopausa. II- Mulheres com queixas de\nfogachos têm maior probabilidade de apresentar transtornos do sono. III- As alterações urogenitais\nsão mais frequentes na fase precoce da transição menopausal. IV- Na pós-menopausa, os valores\nde LDL-colesterol aumentam, com tendência a partículas menores, mais densas e potencialmente\nmais aterogênicas. V- O desempenho da memória e a velocidade de processamento diminuem\nligeiramente durante a transição da menopausa. Estão CORRETAS as afirmativas:","options":{"A":"I, II, III, IV e V.","B":"I, II, III e V apenas.","C":"I, II, IV e V apenas.","D":"II, III, IV e V apenas."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-345733","number":"345733","sourceNumber":"345733","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 90 anos desenvolve prolapso uterino grau IV. É portadora de\ncardiopatia grave. O Ginecologista orienta\nutilização de pessário. Após 30 dias a paciente retorna\ncom ulcerações vaginais causadas pelo pessário. A melhor conduta nesse caso é:","options":{"A":"Histerectomia vaginal.","B":"Colpocleise.","C":"Histerectomia abdominal.","D":"Colpopexia sacro-espinhal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-336298","number":"336298","sourceNumber":"336298","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao tratamento clínico de casos de incontinência urinária em mulheres, é\ncorreto afirmar que:","options":{"A":"Orientações sobre restrição a cafeína, refrigerantes e frutas cítricas não têm suporte teórico,\nnão\ntendo justificativa para essa medida.","B":"A utilização de estrogênios em tratamentos no trato urinário baixo é empírica e eficaz, mas não\nexistem receptores hormonais nessa região periuretral.","C":"A fisioterapia dispõe, além dos exercícios perineais, de recursos com biofeedback,\neletroestimulação e cones vaginais com resultados satisfatórios.","D":"O tratamento comportamental com orientações sobre ingesta hídrica e treinamento vesical é\nmais útil nas mulheres com infecção urinária de esforço do que nas portadoras de bexiga\nhiperativa."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-336300","number":"336300","sourceNumber":"336300","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 52 anos, multípara, relata fogachos há oito meses associado a secura vaginal.\nÚltima menstruação há 14 meses. Exame físico sem\nanormalidades. Todos exames laboratoriais no\nlimite da normalidade. Mamografia e citologia oncológica normais. Frente a esses dados, é indicado\nprescrever:","options":{"A":"Estrogênio e progesterona por via oral.","B":"Progesterona por via oral.","C":"Injeção de progesterona de depósito.","D":"Estrogênio por via transdérmica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-291614","number":"291614","sourceNumber":"291614","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 54 anos, GII PII (cesarianas) A0, antecedente de histerectomia total\nabdominal aos 45 anos por miomatose uterina, é\nexaminada no ambulatório de ginecologia para\navaliação de distopia genital. Abaixo segue a representação de distopia genital pelo Pelvic Organ\nProlapse Quantification System (POP-Q ) desta paciente. Com base nesta representação, assinale\na alternativa que apresenta a distopia observada na paciente.","options":{"A":"Defeito de compartimento anterior.","B":"Defeito de compartimento posterior.","C":"Prolapso uterino.","D":"Prolapso de cúpula vaginal.","E":"Não há distopia genital."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/291614.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-306709","number":"306709","sourceNumber":"306709","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em casos de incontinência urinária em mulheres, em relação ao tratamento clínico, é\ncorreto afirmar que:","options":{"A":"a utilização de estrogênios em tratamentos no trato urinário baixo é empírica e eficaz, mas não\nexistem receptores hormonais nessa região periuretral.","B":"orientações sobre restrição a cafeína, refrigerantes e frutas cítricas não têm suporte teórico,\nnão\ntendo justificativa para essa medida.","C":"a fisioterapia dispõe, além dos exercícios perineais, de recursos com biofeedback,\neletroestimulação e cones vaginais com resultados satisfatórios.","D":"o tratamento comportamental com orientações sobre ingesta hídrica e treinamento vesical é\nmais útil nas mulheres com IUE do que nas portadoras de bexiga hiperativa."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-305012","number":"305012","sourceNumber":"305012","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Os sintomas vasomotores afetam até 75% das mulheres na perimenopausa. Duram\ncerca de um a dois anos após a menopausa na\nmaioria das mulheres, mas podem continuar por\naté 10 anos ou mais em outras. Considerando os sintomas vasomotores das mulheres na\nperimenopausa, analise as afirmativas a seguir. I. Fitoestrogênios atuam como agonistas-\nantagonistas do estrogênio, diminuindo a gravidade e frequência das ondas de calor e,\ncomprovadamente, melhorando os sintomas vasomotores. II. Mulheres podem escolher usar\nterapias alternativas para o alívio dos sintomas, mas devem estar cientes de que a segurança e a\neficácia dessas abordagens muitas vezes não são comprovadas. III. Mulheres com sobrepeso e\nfumantes apresentam sintomas vasomotores mais graves do que mulheres com peso normal e não\nfumantes. IV. A terapia sistêmica com estrogênio é o tratamento mais eficaz para os sintomas\nvasomotores estando, portanto, indicada para todas as pacientes. Estão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"II, III e IV, apenas.","D":"I, II, III, IV."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-304863","number":"304863","sourceNumber":"304863","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação aos sintomas de disfunção do trato urinário baixo em mulheres é\nINCORRETO afirmar:","options":{"A":"Na inspeção dos órgãos genitais externos, a presença de dermatite amoniacal é um fator que\nindica gravidade na incontinência urinária de esforço.","B":"Lesões neurológicas como trauma, acidente vascular cerebral, tumor cerebral e mielite\ntransversa podem causar bexiga neurogênica.","C":"Na anamnese da incontinência urinária de esforço é importante caracterizar o tipo de perda\nurinária e os fatores que pioram ou\ndesencadeiam a perda urinária. No entanto, é muito importante\ntestes objetivos de propedêutica dessas pacientes.","D":"A hiperatividade vesical ou bexiga hiperativa é definida como a presença de contrações\nvoluntárias do músculo detrusor."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-304869","number":"304869","sourceNumber":"304869","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Nos dias atuais a osteoporose é considerada um problema importante de saúde\npública. Entre os fatores maiores de risco para osteoporose não se encontra:","options":{"A":"História pessoal de fratura na vida adulta.","B":"História atual de tabagismo.","C":"Uso de glicocorticoide.","D":"Obesidade."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-313317","number":"313317","sourceNumber":"313317","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Menopausa espontânea é conceituada como:","options":{"A":"Parada da menstruação imediata causada por intervenção médica (quimioterapia ou terapia de\nirradiação pélvica) ou intervenção cirúrgica.","B":"Menopausa que ocorre sem intervenção cirúrgica ou medicamentosa.","C":"Fase referente a transição do período reprodutivo para o período não reprodutivo feminino.","D":"Elenco de sintomas e sinais que podem ocorrer no climatério.","E":"Diagnóstico retrospectivo, sendo o último sangramento seguido de 12 meses de amenorreia."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-257350","number":"257350","sourceNumber":"257350","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao sistema genital feminino é INCORRETO afirmar que:","options":{"A":"O vestíbulo da vagina se estende do clitóris até a borda posterior do hímen e tem como limites\nlaterais, as bordas mediais dos pequenos lábios.","B":"A vagina posterior está fixada em dois pontos laterais, o que torna a parede posterior mais longa\nem relação à anterior em aproximadamente 4 a 6cm.","C":"As glândulas vulvo-vaginais localizam-se de cada lado do introito vaginal, apresentando seus\norifícios na parte posterior do vestíbulo.","D":"O levantador do ânus, o coccígeo, o obturador interno, o piriforme, o ísquio-cavernoso, o\nesfíncter externo da uretra e o esfíncter externo do ânus são músculos do períneo."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-283908","number":"283908","sourceNumber":"283908","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na pós-menopausa, a produção de estrogênio ocorre na forma de\n\npelo . A produção de se mantém pelo ovário nesse período.\nAssinale a alternativa que preenche, correta e respectivamente, as lacunas do trecho acima.","options":{"A":"estrona - ovário - testosterona","B":"estrona - tecido adiposo - testosterona","C":"estradiol - ovário - progesterona","D":"estradiol - tecido adiposo - progesterona","E":"progesterona - tecido adiposo - estradiol"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-227087","number":"227087","sourceNumber":"227087","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 62 anos comparece à consulta com ginecologista com relato de\nincontinência urinária. Informa que perde\nquantidade pequena de urina e sempre ?fica com a\ncalcinha molhada?. Relata que os sintomas prejudicam sua qualidade de vida, pois está sempre\nincomodada com o forte odor. Ao exame físico não são observadas distopias evidentes, mas a\npaciente apresenta perda discreta de urina quando é solicitada a realizar manobras de aumento de\npressão abdominal. Sobre o caso descrito, é INCORRETO afirmar que:","options":{"A":"Exames de rotina de urina e urocultura podem ser solicitados para afastar infecção do trato\nurinário.","B":"Drogas anticolinérgicas podem ser utilizadas no alívio dos sintomas.","C":"A fisioterapia do assoalho pélvico pode ser utilizada como opção terapêutica inicial.","D":"O enfraquecimento de músculos e estruturas pélvicas pode justificar os sintomas relatados."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234418","number":"234418","sourceNumber":"234418","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à inervação da genitália feminina, é INCORRETO afirmar que:","options":{"A":"O nervo pudendo atravessa por cima do músculo piriforme para seguir com os vasos pudendos\ninternos para a fossa isquio-retal, onde divide-se em três ramos terminais para fornecer inervação\nprimária para o períneo.","B":"Os ramos do nervo labial anterior do nervo ilioinguinal emergem do canal inguinal e atravessam\no anel inguinal superficial até o monte\npubiano e parte superior dos lábios maiores.","C":"O ramo genital do nervo genito-femoral entra no canal inguinal com o ligamento redondo e\natravessa o anel inguinal superficial até a vulva anterior.","D":"Os ramos perineais do nervo fêmuro-cutâneo posterior após deixar a pelve, através do forame\nisquiático maior, seguem por diante da tuberosidade isquiática até o períneo lateral, lábios menores\ne porção inferior da base do clitóris."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234420","number":"234420","sourceNumber":"234420","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao climatério, assinale a alternativa INCORRETA:","options":{"A":"O sintoma mais comum e significativo no climatério pré-menopausa é a irregularidade menstrual\ne ocorre em 90% das mulheres.","B":"A menopausa é um período que ocorre entre o início dos sintomas e a parada definitiva das\nmenstruações.","C":"A chamada menopausa precoce ocorre devido ao processo gradual existente durante vários\nanos em virtude de causas naturais, quimioterapia ou cirurgia.","D":"O ovário, antes da menopausa produz 50% de androstenediona e 25% da testosterona, o que\nresulta em concentração menor que um décimo do nível dos homens."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234422","number":"234422","sourceNumber":"234422","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à anatomia do períneo, é INCORRETO afirmar que:","options":{"A":"O triângulo urogenital inclui as estruturas genitais externas e a abertura uretral e cobrem os\nespaços superficial e profundo do períneo e são\nconhecidas como genitália externa.","B":"Os lábios maiores são um par de pregas fibroadiposas de pele que se estendem a partir do\nmonte pubiano para baixo e para trás para se encontrarem na linha média, na frente do ânus na\nfosseta posterior.","C":"Os lábios menores situam-se entre os lábios menores, com os quais se fundem posteriormente e\nsão separados em duas pregas quando se\naproximam do clitóris anteriormente e aí as pregas\nanteriores unem-se para formar o prepúcio do clitóris e as posteriores formam o freio do clitóris.","D":"O clitóris é órgão erétil com 2-3 centímetros de comprimento e consiste de dois pilares, um corpo\nesponjoso e dois corpos cavernosos, sendo coberto por tubérculo arredondado sensível (a glande)."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234423","number":"234423","sourceNumber":"234423","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao assoalho pélvico, assinale a alternativa INCORRETA:","options":{"A":"O diafragma pélvico estende-se transversalmente de forma semelhante a uma rede através da\npelve verdadeira, com um hiato central para a uretra, a vagina e o reto e pode ser dividido em dois\ncomponentes ? os internos e os externos.","B":"O componente externo do diafragma pélvico origina-se do arco tendíneo, estendendo-se do osso\npube até a espinha isquiática, que dá\norigem a fibras de diferentes direções, incluindo o músculo\npuboccígeo, o músculo iliococígeo e o músculo coccígeo.","C":"O componente interno do diafragma pélvico origina-se do osso pube acima e medialmente das\norigens do músculo pubococcígeo, porém mais espesso e mais forte.","D":"As fibras superiores do músculo puborretal formam uma alça ao redor do reto até a sínfise\npúbica e suas fibras inferiores inserem-se na borda inferior do osso púbis de cada lado."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-243006","number":"243006","sourceNumber":"243006","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 50 anos de idade procurou uma unidade básica de saúde devido\nqueixa de secura vaginal associada à perda de urina aos grandes esforços, com queda de sua\nqualidade de vida. A paciente é obesa, apresenta hipertensão compensada (uso de enalapril e\nhidroclorotiazida) e refere que a mãe teve câncer de mama.","options":{"A":"o uso da terapia de reposição hormonal sistêmica é superior ao uso da tópica na melhora de\nsintomas genitourinários.","B":"trata?se de um quadro típico de bexiga hiperativa e a fisioterapia mostra?se eficaz no caso.","C":"a paciente em questão teria benefícios com o uso de uma terapia de reposição tópica, entretanto\nhá contraindicação formal dessa terapia devido à\nhipertensão.","D":"as medicações utilizadas pela paciente não apresentam influência sobre o quadro de\nincontinência urinária dela.","E":"recomenda?se à paciente a perda de peso como medida inicial de tratamento."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-243011","number":"243011","sourceNumber":"243011","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério é o período que precede o término da vida reprodutiva da mulher. Analise\nas alternativas abaixo e assinale a CORRETA sobre\no climatério:","options":{"A":"a diminuição da progesterona durante o período pode estar associada ao aumento de casos de\ndepressão durante o climatério, principalmente em mulheres predispostas.","B":"é comum o aumento do líbido nessa época.","C":"a insuficiência estrogênica relativa, iniciada no climatério, não possui papel relevante para o\naparecimento ou agravamento de distopias, como o prolapso genital.","D":"o climatério também pode influenciar na diminuição do fator VII e do fibrinogênio, podendo levar\na um estado de hipocoagulabilidade,\ndiminuindo assim o risco de tromboembolismo no climatério.","E":"os fogachos constituem o sintoma mais comum nas mulheres ocidentais, manifestando-se como\numa sensação súbita, transitória e intensa de\ncalor na pele, principalmente em tronco, pescoço e\nface."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-255643","number":"255643","sourceNumber":"255643","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Zilda, 49 anos, procura o atendimento com o ginecologista/obstetra que a acompanhou\ndurante suas três gestações para discutir a\nchegada dos fogachos e da irregularidade menstrual.\n\nEm relação ao uso de estrogênio para o tratamento dos sintomas vasomotores (SVM) da\nmenopausa, MARQUE A CORRETA:","options":{"A":"As pacientes que apresentam sintomas vasomotores leves devem ser orientadas quanto à\nmudanças de estilo de vida e oferecido\ntratamento farmacológico com terapia hormonal em baixas\ndoses.","B":"A terapia com anticonvulsivantes têm eficácia semelhante a terapia hormonal para os sintomas\nvasomotores e para a síndrome genitourinária da menopausa.","C":"Mulheres que iniciam terapia hormonal (TH) mais de 10 ou 20 anos após o início da menopausa\nou têm 60 anos ou mais apresentam menores\nriscos absolutos de doença cardíaca coronária,\nacidente vascular cerebral (AVC), tromboembolia venosa e demência.","D":"Uma vez que as mulheres descontinuam a TH, há cerca de 50% de chance dos sintomas\nretornarem, independentemente da idade ou por quanto tempo estiver usando."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-255646","number":"255646","sourceNumber":"255646","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Maria, 62 anos, hipertensa e diabética, vai à Unidade Básica de Saúde (UBS) para sua\ncoleta trianual do exame citopatológico do colo do útero. A enfermeira questiona sobre perda\nurinária e ela responde positivamente, especialmente a noite. Para discutir o caso com o médico,\nrevisa o prontuário e observa que houve a prescrição de um novo anti-hipertensivo. Marque o\nmedicamento que pode estar relacionado ao aparecimento de sintomas de vias urinárias:","options":{"A":"Losartan.","B":"Anlodipina.","C":"Carvedilol.","D":"Metildopa."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-246385","number":"246385","sourceNumber":"246385","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São efeitos da tibolona:","options":{"A":"Alívio dos sintomas vasomotores.","B":"Redução do LDL colesterol.","C":"Sangramento transvaginal cíclico mensal.","D":"Redução da libído."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-246759","number":"246759","sourceNumber":"246759","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 47 anos se apresenta à consulta referindo que seus problemas de\nmudança de humor, insônia e secura vaginal\nsão por causa da menopausa. Ela foi submetida a\numa histerectomia há 10 anos por sangramento anormal, mas os ovários não foram retirados.\n\nComo ela não pode pagar por um perfil hormonal, realizamos o índice de maturação no seu\nesfregaço de Papanicolaou. De modo ideal, o estudo citológico das células para avaliação\nhormonal deve ser obtido a partir:","options":{"A":"Da ectocérvice.","B":"Da Endocérvice.","C":"Da parede vaginal lateral.","D":"Do fórnice vaginal posterior.","E":"Do fórnice vaginal anterior."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-246760","number":"246760","sourceNumber":"246760","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 47 anos se apresenta à consulta referindo que seus problemas de\nmudança de humor, insônia e secura vaginal\nsão por causa da menopausa. Ela foi submetida a\numa histerectomia há 10 anos por sangramento anormal, mas os ovários não foram retirados.\n\nComo ela não pode pagar por um perfil hormonal, realizamos o índice de maturação no seu\nesfregaço de Papanicolaou. Noventa por cento\n(90%) das células encontradas no seu esfregaço\napresentam citoplasma espesso, redondo e núcleos vesiculares roliços, com padrão intacto da\ncromatina. O índice de maturação (IM) mais provável seria:","options":{"A":"90/0/10.","B":"90/10/0.","C":"10/0/90.","D":"10/90/0.","E":"Nenhuma das alternativas anteriores é correta."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-246771","number":"246771","sourceNumber":"246771","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 56 anos, negando sintomas de climatério, com história familiar materna de\nosteoporose e densitometria óssea de coluna lombar com T-score L1?L4 de -2.7 desvios-padrão. A\nopção terapêutica, nesse caso, é:","options":{"A":"Carbonato ou citrato de cálcio associado à vitamina D.","B":"Terapia hormonal e cálcio associado à vitamina D.","C":"Bisfosfonatos associados ao cálcio e à vitamina D.","D":"Exercício associado ao cálcio e à vitamina D.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199519","number":"199519","sourceNumber":"199519","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 57 anos comparece ao consultório para exame periódico de saúde.\nEstá preocupada se tem osteoporose, porque a mãe\nde 75 anos teve fratura do colo do fêmur\nrecentemente. É hipertensa e usa hidroclorotiazida irregularmente. É tabagista há 20 anos, 1 maço\nao dia, e faz uso regular de cerveja, 2 garrafas de 600mL diariamente. Ao exame físico, a PA era\n150 x 95mmHg; sem outras alterações. Para prevenção da osteoporose, todas as orientações a\nseguir visam à correção de fatores de risco modificáveis, EXCETO:","options":{"A":"Interromper o tabagismo.","B":"Interromper o etilismo.","C":"Tratar a hipertensão arterial sistêmica\nadequadamente.","D":"Iniciar a prática regular de atividade física."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-220304","number":"220304","sourceNumber":"220304","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao climatério, é INCORRETO afirmar que:","options":{"A":"A menopausa natural é definida como a interrupção definitiva e permanente dos períodos\nmenstruais determinada retrospectivamente após amenorreia de 12 meses.","B":"As mulheres, nesse período, geralmente observam primeiro um alongamento no intervalo\nintermenstrual em contraste com o encurtamento que ocorre nos últimos anos reprodutivos.","C":"As mulheres, após o alongamento inicial do intervalo intermenstrual, desenvolvem mudanças\nmais dramáticas no ciclo menstrual com ciclos\nlongos, episódios de amenorreia e uma frequência\ncrescente de ciclos anovulatórios, fase essa referida como \"transição tardia\" e que normalmente\ndura de um a três anos antes do final do período menstrual.","D":"A detecção do período final das menstruações (climatério pré-menopausa) tem maior\nimportância do que simplesmente permitir que as\nmulheres saibam quando elas atingirão a\nmenopausa, pois a perda óssea acelerada e um aumento nos fatores de risco cardiovasculares\nocorrem no ano que antecede esse período final."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-220288","number":"220288","sourceNumber":"220288","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à anatomia da genitália interna, é INCORRETO afirmar que:","options":{"A":"O complexo ligamentar úterossacro/cardinal suspende o útero e a parte superior da vagina em\nsua orientação normal e tem a função de manter o\ncomprimento e o eixo vaginal quase horizontal\nem uma mulher em ortostatismo para que ele possa ser suportado pela placa levantadora.","B":"O espaço retovaginal inicia-se caudalmente na margem superior do corpo perineal, se estende\nsuperiormente entre a vagina posterior e o reto através do cul-de-sac posterior, sendo este a sua\nborda mais cefálica e seus limites laterais, os pilares retais e o feixe cardinal inferior à\nesquerda e a\nfáscia do músculo psoas à direita.","C":"Os ligamentos redondos são extensões da musculatura uterina, se inserem no fundo uterino\nanterior e inferior às trompas de falópio,\npercorrem retroperitonealmente as camadas do ligamento\nlargo, entram no canal inguinal e terminam nos grandes lábios e o seu homólogo masculino é o\ngubernaculum testis.","D":"As artérias uterinas se originam da divisão anterior das artérias ilíacas internas no\nretroperitônio\ne podem compartilhar uma origem comum com a\nartéria umbilical obliterada, pudenda interna ou\nartéria vaginal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199491","number":"199491","sourceNumber":"199491","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao climatério, assinale a alternativa INCORRETA:","options":{"A":"Os sintomas característicos da transição da menopausa/perimenopausa e nos primeiros anos de\npós-menopausa são os fogachos que ocorrem em até 80% das mulheres.","B":"Os fogachos tornam-se muito mais comuns durante a transição da menopausa, com uma\nfrequência de aproximadamente 40% na transição\ninicial, aumentando para 60 a 80% na transição\ntardia da menopausa e pós-menopausa precoce.","C":"O risco de doença cardiovascular aumenta após a menopausa, provavelmente devido, pelo\nmenos em parte, à deficiência de estrogênio,\nlevando, em parte, a mudanças nos fatores de risco\ncardiovascular, como os perfis lipídicos que aumentam o LDL com diminuição significativa do HDL.","D":"No diagnóstico diferencial do climatério pré- menopausa, o hipertireoidismo deve ser sempre\nconsiderado, já que menstruações irregulares, sudorese e alterações de humor são todas\nmanifestações clínicas potenciais dessa doença."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-199574","number":"199574","sourceNumber":"199574","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 58 anos, com menopausa aos 47 anos, procura atendimento ginecológico\npor queixa de dispareunia e secura vaginal. Nega\noutras queixas. Traz consigo colpocitologia\noncótica realizado há 6 meses com resultado negativo para malignidade. Apresenta ainda\nmamografia digital e ultrassonografia transvaginal sem anormalidades, realizados de rotina há 4\nmeses. O exame ginecológico evidenciou mucosa vaginal atrófica, colo uterino atrófico. Dentre as\nopções terapêuticas abaixo, qual é a melhor conduta para a paciente?","options":{"A":"Fitoestrogênio oral.","B":"Estrogênio vaginal.","C":"Progesterona oral.","D":"Não há necessidade de terapêutica, pois na maioria dos casos a queixa de resolve\nespontaneamente."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212957","number":"212957","sourceNumber":"212957","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diafragma pélvico é formado pelos seguintes músculos:","options":{"A":"Coccígeo e transverso profundo do períneo.","B":"Levantadores do ânus e coccígeo.","C":"Transversos profundos do períneo e puborretal.","D":"Transversos profundos do períneo e esfíncter da uretra.","E":"Esfíncter da uretra e coccígeo."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-212979","number":"212979","sourceNumber":"212979","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em se tratando de terapia hormonal no climatérico e seus riscos cardiovasculares, é\ncorreto afirmar que:","options":{"A":"A terapia hormonal por via oral diminui mais os riscos de fenômenos tromboembólicos venosos\nem comparação com outras vias de administração.","B":"História de tromboembolismo venoso prévio é contraindicação formal para uso de terapia\nhormonal por via oral.","C":"O uso de tibolona tem demonstrado aumento de riscos tromboembólicos.","D":"Sua utilização em mulheres sem doenças cardiovasculares exerce fator protetor quando\nadministrada em qualquer idade após a menopausa, desde que não haja contraindicações.","E":"Em mulheres com doença cardiovascular, sua administração deve ser incentivada mesmo após\no período considerado janela de oportunidade."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-215176","number":"215176","sourceNumber":"215176","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São possíveis opções terapêuticas para tratamento da incontinência urinária de\nesforço, EXCETO:","options":{"A":"Exercícios de Kegel.","B":"Redução do consumo de cafeína.","C":"Toxina botulínica.","D":"Sling retropubico.","E":"Nenhuma das anteriores."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-215178","number":"215178","sourceNumber":"215178","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Que fatores de risco podem se relacionar à ocorrência de distopias genitais?","options":{"A":"Tabagismo, paridade, história familiar de distopias.","B":"Cirurgias pélvicas prévias, baixo nível sócio econômico, DPOC.","C":"Idade avançada, lacerações perineais pós parto, sedentarismo.","D":"Osteoporose, esclerose múltipla, hipoestrogenismo.","E":"Nenhuma das anteriores."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-187492","number":"187492","sourceNumber":"187492","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual das situações abaixo não se constitui em fator de risco para osteoporose?","options":{"A":"Alcoolismo.","B":"Uso crônico de corticoides.","C":"Deficiência de vitamina D.","D":"Alto peso.","E":"Sedentarismo."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-188038","number":"188038","sourceNumber":"188038","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 52 anos, multipára, procura médico com queixas de fogachos há oito meses,\ncom secura vaginal e que não menstrua há 14\nmeses. Ao exame físico, não apresenta nenhuma\nanormalidade e todos seus exames laboratoriais estão nos limites da normalidade. Mamografia e\ncitologia oncológica normais. Frente a esses dados, é indicado prescrever:","options":{"A":"nada, somente observação;","B":"progesterona por via oral;","C":"estrogênio por via transdérmica;","D":"estrogênio e progesterona por via oral;","E":"injeção de progesterona de depósito."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-126888","number":"126888","sourceNumber":"126888","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao climatério, assinale a alternativa INCORRETA:","options":{"A":"A menopausa natural é definida como a permanente interrupção das menstruações após\nperíodo de 12 meses de amenorreia sem qualquer outro motivo patológico ou fisiológico.","B":"Ocorre em média aos 51.4 anos refletindo depleção completa ou incompleta dos ovários.","C":"A menopausa precoce é assim chamada quando ocorre antes dos 35 anos, acompanhada dos\nmesmos sintomas.","D":"O principal sintoma do climatério precoce é o fogacho que ocorre em torno de 50-60% das\nmulheres."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-126895","number":"126895","sourceNumber":"126895","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à incontinência urinária, assinale a alternativa INCORRETA.","options":{"A":"A incontinência urinária não faz parte do envelhecimento normal, embora a prevalência aumente\ncom a idade.","B":"Dentre os diagnósticos diferenciais da incontinência urinária encontramos o deslocamento do\ncolo vesical, instabilidade idiopática do detrusor e divertículo uretral.","C":"Várias drogas afetam o trato urinário inferior como os sedativos, álcool, drogas\nanticolinérgicas.","D":"Nos casos clássicos de incontinência urinária de esforço como em tosses frequentes e intensas,\na correção cirúrgica poderá ser realizada sem\ncompletar todos os exames."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127161","number":"127161","sourceNumber":"127161","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O tratamento farmacológico da incontinência urinária de esforço pode ser, inicialmente,\nrealizado com diversos medicamentos. Dentre\nos abaixo relacionados, qual apresenta a melhor\neficácia?","options":{"A":"Efedrina.","B":"Propranolol.","C":"Clembuterol.","D":"Imipramina.","E":"Duloxetina."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127170","number":"127170","sourceNumber":"127170","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 48 anos, 3 partos vaginais, menopausada há 2 anos, sem reposição\nhormonal, com queixa de perda urinária aos\npequenos esforços. Ao exame físico apresenta\ncistocele grau I, retocele grau II e perda de urina involuntária. O estudo urodinâmico evidenciou\nbexiga com complacência normal, capacidade vesical de 450 ml, detrusor estável e perda de urina\ncom uma pressão de 40 cm H2O. Qual o diagnóstico da incontinência urinária desta paciente?","options":{"A":"Bexiga hiperativa.","B":"Instabilidade do detrusor.","C":"Deficiência esfincteriana intrínseca.","D":"Hipermobilidade uretral.","E":"Incontinência urinária por transbordamento."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-131677","number":"131677","sourceNumber":"131677","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A indicação mais comum para pessário vaginal é:","options":{"A":"Prolapso de órgão pélvico;","B":"Divertículo uretral;","C":"Incontinência anal;","D":"Fístula retovaginal;","E":"Distúrbio anorretal funcional."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-101006","number":"101006","sourceNumber":"101006","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à Terapia Hormonal (TH), marque a resposta CORRETA.","options":{"A":"Está relacionada com o aumento do ganho de peso.","B":"Favorece o acúmulo de gordura na região da cintura.","C":"Reduz a perda mineral óssea e a incidência de câncer de colo-retal.","D":"É mais trombogênica que o uso de anticoncepcionais hormonais orais.","E":"É mais trombogênica que o ciclo grávido-puerperal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-88903","number":"88903","sourceNumber":"88903","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"<p>Mulher, 49 anos, refere ciclos oligomenorreicos há 2 anos, com última menstruação\nhá 6 meses. Apresenta-se com queixas de\nfogachos, insônia, labilidade emocional e diminuição da\nlibido, nega comorbidades. Frente a esse quadro, pode-se afirmar que: I. A paciente encontra-se na\nperimenopausa; II. Há indicação de terapia hormonal, e essa deverá ser combinada\n(estroprogestativa) ou com tibolona; III. Os ciclos anovulatórios são a principal causa de\nirregularidade menstrual nesse período; IV. Dosagens de FSH, LH e estradiol são fundamentais\npara o diagnóstico nessa paciente. Quais estão CORRETAS?</p>","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas I, II e III.","D":"Apenas II, III e IV.","E":"I, II, III e IV."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-77617","number":"77617","sourceNumber":"77617","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 42 anos, branca, 49 kg, altura: 1,60 m, foi atendida na CASA 2 do HUCAM\nrelatando ausência de menstruação há 8 meses, fogachos insuportáveis, sudorese, vagina\nressecada e dispareunia. É correto afimar, exceto:","options":{"A":"Essa paciente tem hipótese diagnóstica clínica de climatério sintomático e indicação de terapia\nhormonal do climatério.","B":"A terapia hormonal nessa paciente deve durar 5 anos ou no máximo 10 anos, pelo grande\naumento no risco de câncer de mama.","C":"Essa paciente é de alto risco para osteoporose se não fizer terapia hormonal.","D":"Estudos recentes sugerem que essa paciente terá menor risco cardiovascular se começar sua\nterapia hormonal aos 42 anos.","E":"O risco de tromboembolismo com o uso dos hormônios naturais na terapia hormonal do\nclimatério é bem menor que com o uso de\nanticoncepcional, que a paciente fez uso dos 30 aos 40\nanos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-77501","number":"77501","sourceNumber":"77501","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São considerados fatores de risco para prolapso uterino, exceto:","options":{"A":"Fator constitucional","B":"Partos vaginais sem assistência médica","C":"Doenças obstrutivas crônicas, como enfisema e constipação intestinal","D":"Idade e hipoestrogenismo","E":"Patologias orgânicas como a miomatose uterina"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-43300","number":"43300","sourceNumber":"43300","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à menopausa marque a alternativa CORRETA:","options":{"A":"Termo reservado exclusivamente à cessação espontânea do fluxo menstrual.","B":"Menopausa precoce é a cessação do fluxo menstrual que ocorre antes dos 30 anos de idade.","C":"Os sintomas de ?fogacho? (sensação de ondas de calor), não podem ser justificados por\nnenhuma alteração hormonal na menopausa. São\nrelacionados às alterações emocionais próprias\ndesse período.","D":"A queixa de dispaurenia, relativamente frequente nesse período da vida da mulher, encontra\njustificativa em alterações detectáveis ao exame ginecológico.","E":"A terapia de reposição hormonal mostrou significativo benefício cardiovascular, como ficou\nprovado com pelo menos 02 estudos randomizados e duplo-cegos, devendo ser prescrita para\npacientes na menopausa (a não ser que haja contraindicação ao seu uso)."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-43925","number":"43925","sourceNumber":"43925","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São estrógenos naturais empregados na Terapia Hormonal do climatério:","options":{"A":"Isoflavona e Cimicífuga.","B":"Isoflavona e Estradiol.","C":"Estrógenos Conjugados Equinos e Estradiol.","D":"Estrógenos Conjugados Equinos e Isoflavona.","E":"Cimicífuga e Estradiol."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-43927","number":"43927","sourceNumber":"43927","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A Terapia Hormonal do climatério deve ser iniciada:","options":{"A":"Quando a paciente completa 50 anos de idade, independente do FSH e de sintomas do\nclimatério.","B":"Quando a dosagem de FSH for superior a 30 mlU/ml, independente de sintomas do climatério.","C":"Quando a paciente completa 40 anos, para retardar o envelhecimento (anti-age).","D":"Quando se iniciam os sintomas do climatério, com FSH elevado, TSH e prolactina normais.","E":"Quando TSH normal, FSH e prolactina elevados."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-32482","number":"32482","sourceNumber":"32482","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"<p>Paciente atendida com queixa de Incontinência Urinária de Esforço (IUE). Na\ninvestigação da IUE é importante, EXCETO:</p>","options":{"A":"Anamnese e exame físico ginecológico.","B":"EAS e urocultura para afastar infecção urinária.","C":"Diário miccional.","D":"Estudo urodinâmico.","E":"Ultrassonografia do aparelho urinário."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-32470","number":"32470","sourceNumber":"32470","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Foi comprovado por grande estudo científico que a terapia hormonal reduz a incidência\nde:","options":{"A":"Câncer de mama.","B":"Câncer colorretal.","C":"Câncer do colo uterino.","D":"Câncer do endométrio.","E":"Câncer de ovário."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-27329","number":"27329","sourceNumber":"27329","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Pacientes que utilizam drogas anticolinérgicas podem levar à:","options":{"A":"Incontinência urinária","B":"Urgeincontinência","C":"Nocturia","D":"Dificuldade miccional","E":"Redução do fechamento uretral"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-23090","number":"23090","sourceNumber":"23090","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação a fisiologia do climatério é correto afirmar:","options":{"A":"A diminuição do estradiol circulante aumenta os níveis de SHBG (Sex Hormone\nBinding-globulin).","B":"A diminuição do estradiol circulante reduz os níveis de SHBG acarretando hiperandrogenismo\nabsoluto.","C":"A diminuição do estradiol circulante reduz os níveis de SHBG acarretando hiperandrogenismo\nrelativo.","D":"O aumento do estradiol circulante reduz os níveis de SHBG.","E":"A diminuição do estradiol é o único fator responsável pelo aumento do FSH."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8114","number":"8114","sourceNumber":"8114","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a afirmativa incorreta:","options":{"A":"A incontinência urinária é mais comum em mulheres e acomete 1/3 das mulheres com mais de\n60 anos.","B":"Em mulheres, a incontinência urinária pode ser causada por uma perda de suporte da bexiga e\nuretra.","C":"Entre as causas de incontinência urinária está a infecção urinária.","D":"A incontinência urinária de esforço (IUE) Tipo 3, segundo classificação de Blaivas e Olson,\nsignifica queixa típica de IUE e observa-se\nperda de urina ao exame físico e no exame urodinâmico,\ncaracterizando insuficiência esfincteriana uretral.","E":"Em geral, o tratamento de incontinência urinária de esforço nas mulheres é clínico e\ncomportamental."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9402","number":"9402","sourceNumber":"9402","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"As drogas anticolinérgicas comprometem:","options":{"A":"Contração do detrusor.","B":"Ovulação.","C":"Ciclo menstrual.","D":"Relaxamento uretral."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8143","number":"8143","sourceNumber":"8143","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 55 anos menopausada há 5 anos, com fogachos intensos. Como estão os\nhormônios desta paciente?","options":{"A":"Gonadotrofinas normais e os esteroides elevados.","B":"Gonadotrofinas normais e os esteroides normais.","C":"Gonadotrofinas elevadas e os esteroides elevados.","D":"Gonadotrofinas baixas e os esteroides normais.","E":"Gonadotrofinas elevadas e os esteroides baixos."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-355619","number":"355619","sourceNumber":"355619","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 62 anos, em acompanhamento regular por dor lombar. Antecedente de fratura\ncoluna lombar após queda. Está em uso de alendronato 70 mg há cinco anos. Exames\nlaboratoriais: creatinina 1,5 mg/dL. Densitometria óssea: T: (coluna) -3,2; (colo de fêmur) -2,3;\n(rádio) -3,5. Em relação ao caso, é correto:","options":{"A":"manter bifosfonato, pois eGFR > 30 ml/minuto/1,73 m²","B":"denosumab é a primeira opção terapêutica neste caso","C":"interromper o alendronato ('holliday\"\"), pois completou cinco anos de tratamento.","D":"repetir densitometria óssea anualmente para monitorar o tratamento."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-331981","number":"331981","sourceNumber":"331981","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério, a menopausa e a senilidade são definidas por intervalo de tempo. Qual\ndas alternativas abaixo representa o intervalo de tempo mais adequado para esses períodos de\nvida da mulher, respectivamente?","options":{"A":"12-49 anos, 39 ± 2 anos e >60 anos.","B":"39-49 anos, 49 ± 2 anos e >65 anos.","C":"39-65 anos, 49 ± 2 anos e >65 anos.","D":"49-65 anos, 59 ± 2 anos e >65 anos.","E":"39-65 anos, 40 ± 2 anos e >60 anos."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-339804","number":"339804","sourceNumber":"339804","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 60 anos, G4P4, partos vaginais, informa que, há seis meses, vem\napresentando perdas involuntárias de urina. Nega\ndemais queixas. O exame ginecológico revelou\nperda urinária durante a manobra de Valsalva. Realizou estudo urodinâmico que revelou pressão\nde perdas aos esforços de 100 cmH2O. Considerando o exposto acima, assinale a alternativa que\nindica o diagnóstico mais provável:","options":{"A":"Incontinência urinária aos esforços.","B":"Defeito esfincteriano intrínseco da uretra.","C":"Urge incontinência urinária.","D":"Fístula vesicovaginal.","E":"Enurese noturna."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-334828","number":"334828","sourceNumber":"334828","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A classificação do POP-Q (quantificação de prolapso de órgão pélvico) buscou\nquantificar a distância de cada prolapso\npara reduzir a divergência entre os observadores. Sabe-se\nque:","options":{"A":"Grau 3 - o ponto maior do prolapso vai até -4.","B":"Grau 2- o ponto maior do prolapso vai de -1 a +1.","C":"Grau 1- o ponto maior do prolapso vai até -3.","D":"Grau 0 - prolapso completo do órgão do assoalho pélvico."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-342661","number":"342661","sourceNumber":"342661","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 80 anos queixa-se de perda urinária frequente. Sem outra\nespecificação, qual é a principal causa para essa queixa na referida faixa etária?","options":{"A":"incontinência urinária de esforço anatômica","B":"divertículo uretral","C":"incontinência urinária de urgência","D":"fístula urinária"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-334161","number":"334161","sourceNumber":"334161","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Entre os benefícios da terapia de reposição hormonal na menopausa, o que não é\nesperado é:","options":{"A":"Melhora da atrofia urogenital.","B":"Diminuição dos fogachos.","C":"Diminuição do risco de fraturas de colo do fêmur.","D":"Aumento do LDL colesterol."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-342663","number":"342663","sourceNumber":"342663","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 35 anos, com amenorreia há 11 meses, em investigação laboratorial,\napresenta-se com os seguintes resultados dos exames laboratoriais: FSH = 40U/L; estradiol =\n30pg/mL, TSH = 3,5mU/L e beta-HCG negativo. Os exames foram repetidos em intervalo de 45\ndias, com confirmação dos resultados. Qual é principal hipótese diagnóstica?","options":{"A":"amenorreia hipotalâmica","B":"menopausa","C":"falência ovariana prematura","D":"pseudociese"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-334163","number":"334163","sourceNumber":"334163","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São consideradas perdas urinárias de caráter fisiológico, exceto:","options":{"A":"Urgência miccional.","B":"Fístula vesicovaginal.","C":"Bexiga hiperativa.","D":"Instabilidade do detrusor."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321625","number":"321625","sourceNumber":"321625","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 55 anos de idade, pós-menopausada há cinco anos e sem sintomas\nvasomotores deverá ser tratada para dispareunia\ncom diminuição secundária do desejo sexual,\nsalvo contraindicações, inicialmente com","options":{"A":"terapia sexual.","B":"testosterona transdérmica.","C":"associação de estradiol + progestágeno sistêmica.","D":"estrógenos tópicos via vaginal."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321630","number":"321630","sourceNumber":"321630","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A injeção dos chamados agentes de preenchimento na submucosa da uretra é um\nmétodo minimamente invasivo, disponível para tratar mulheres com","options":{"A":"bexiga hiperativa e dissinergia do músculo detrusor.","B":"urgeincontinênica urinária em pacientes idosas com mobilidade uretral.","C":"IUE decorrente de defeito esfincteriano intrínseco e ausência de mobilidade uretral.","D":"urgeincontinênica urinária sem defeito esficteriano e ausência de mobilidade uretral."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-321633","number":"321633","sourceNumber":"321633","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O objetivo primordial da terapêutica hormonal (TH) é o tratamento dos sintomas\nvasomotores associados ao climatério. Nesse sentido, o a SOBRAC (Sociedade Brasileira de\nClimatério) e a FEBRASGO (Federação Brasileira de Ginecologia e Obstetrícia) orientam às\npacientes em uso de TH","options":{"A":"a realização de ultrassonografia mamária e endovaginal.","B":"a realização anual de exames de mamografia.","C":"a realização de ultrassonografia endovaginal quando pacientes apresentarem sangramento\nuterino.","D":"a realização de exames complementares depois de efetuado rastreio de doenças\ncardiovasculares em usuárias de TH."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-308221","number":"308221","sourceNumber":"308221","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 55 anos, G3P3, menopausada há 10 anos, refere perda urinária aos esforços\ne urgência miccional há cerca de 2 anos . ao\nrealizar o estudo urodinâmico , foi detectada pressão\nvesical de perda(VLPP) de 100 cm H20. Não foram evidenciadas contrações não inibidas pelo\ndetrusor. Nesse caso clínico, o tipo de incontinência apresentada:","options":{"A":"Mista.","B":"De esforço por deficiência esfincteriana intrínseca.","C":"Por bexiga hiperativa.","D":"De esforço por hipermobilidade do colo vesical."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-300910","number":"300910","sourceNumber":"300910","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à Insuficiência Ovariana Prematura, assinale a alternativa CORRETA:","options":{"A":"Na presença de cromossomo Y, deve-se indicar remoção cirúrgica das gônadas.","B":"Não existe possibilidade de gravidez nesse caso.","C":"A terapia hormonal não deve ser utilizada rotineiramente.","D":"O diagnóstico de certeza é a dosagem de estradiol baixa."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-294262","number":"294262","sourceNumber":"294262","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O uso de antibióticos profiláticos pode ser considerado uma abordagem inespecífica\npara a prevenção de infecções do trato\nurinário (ITU) recorrentes. A eficácia da profilaxia foi\nquestionada, mesmo em crianças com refluxo vesico-ureteral (RVU), por várias séries\nrandomizadas relativamente pequenas, incluindo crianças com baixas notas de RVU. Como pode\nser esperado, o benefício dos antibióticos profiláticos é mais facilmente demonstrado quando\nusados em populações específicas sabidamente de alto risco para ITU recorrente. Em relação às\nITUs recorrentes é conhecido que:","options":{"A":"mesmo em populações que apresentam maior risco de ITU recorrente, como meninas com RVU\ncom dilatação do trato urinário (ou seja,\nmaior ou igual ao grau III), os antibióticos profiláticos não\ntêm se mostrado eficazes.","B":"a exposição a antibióticos aumenta a probabilidade de que quaisquer ITUs subsequentes sejam\ncausadas por bactérias resistentes aos antibióticos previamente prescritos. Isso está relacionado ao\nfato de que a flora vaginal frequentemente se torna resistente ao antibiótico de tratamento.","C":"o antibiótico ideal para profilaxia seria eficaz contra a maioria dos uropatógenos, ser\nfacilmente\nadministrado e tolerado, sem efeitos colaterais significativos, ter altas concentrações urinárias e\nbaixas concentrações séricas e ter pouco impacto na flora bacteriana nativa e na resistência\nbacteriana.","D":"as opções comuns de antibióticos profiláticos incluem sulfametoxazol e trimetroprima,\ntrimetroprima, nitrofurantoína, cefalosporinas de\nprimeira geração e ampicilina. Com o aumento da\nresistência de E. coli a sulfametoxazol e trimetroprima, seu uso dessa forma é cada vez mais\nquestionável."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-295369","number":"295369","sourceNumber":"295369","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, de 65 anos, assintomático, vem em consulta médica trazendo consigo resultado\nda densitometria óssea, conforme apresentada a\nseguir e de exames laboratoriais solicitados como\navaliação de rotina. Nega comorbidades ou fratura prévias. Nega uso de medicação contínua e faz\natividade física regularmente. Relata consumir ao menos três copos de leite a duas fatias de queijo\ntodos os dias. Exames laboratoriais: Ureia: 30 mg/dL (VR*: 16 - 40 mg/dL), Creatinina: 0,9 mg/dL\n(VR: 0,7 - 1,3 mg/dL), Cálcio sérico total: 8,9 mg/dL (VR: 8,5 - 10,2 mg/dL), 25-hi-droxivitamina D:\n18 ng/mL (VR: 30 - 60ng/mL). De acordo com o quadro clínico e análise da densitometria óssea, a\nmelhor conduta terapêutica nesse caso seria:","options":{"A":"suplementação de carbonato de cálcio 600 mg duas vezes ao dia, associado a vitamina D?\n\n50.000 UL uma vez na semana, por 8 semanas.","B":"suplementação de carbonato de cálcio 600 mg uma vez ao dia associado a vitamina D? 1.000 Ul\numa vez ao dia.","C":"suplementação de vitamina D? 50.000 Ul uma vez na semana, por 8 semanas.","D":"paciente não tem indicação de suplementação de cálcio e vitamina D?, já que apresenta cálcio\nsérico normal e não apresenta diagnóstico de osteoporose."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/295369.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-314132","number":"314132","sourceNumber":"314132","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A perda urinária por transbordamento em mulheres é causada, principalmente,","options":{"A":"pelo uso de anti-hipertensivos.","B":"pelo diabetes mellitus.","C":"pelas lesões medulares.","D":"pelo antecedente de parto normal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-316334","number":"316334","sourceNumber":"316334","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 67 anos G4P4A0C3 refere urgência miccional e perda urinária aos\nesforços tipo tossir e espirrar há\naproximadamente um ano. O exame ginecológico revelou a\npresença de cistocele grau II. O estudo urodinâmico identificou ausência de hiperatividade do\nmúsculo detrusor e perda urinária com pressão abdominal de 100 cm H?O. O provável diagnóstico\né:","options":{"A":"Incontinência urinária por hipermobilidade do colo vesical.","B":"Incontinência urinária mista.","C":"Urgência miccional.","D":"Incontinência urinária por cistocele moderada."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-316341","number":"316341","sourceNumber":"316341","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"J.C.V, 36 anos, refere que subitamente apresentou amenorréia secundária, não\napresentando sangramento nem mesmo após uso de progesterona. A avaliação das\ngonadotrofinas mostra FSH elevado. Provavelmente ocorre:","options":{"A":"Tumor hipofisário.","B":"Menopausa precoce.","C":"Tumor hipotalâmico D.","D":"Ovários policísticos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-311937","number":"311937","sourceNumber":"311937","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 65 anos, G3P3N, menopausada há 15 anos, queixa-se de perda urinária aos\nesforços e urgência miccional há 3 anos. Foi detectada, ao realizar o estudo da urodinâmica, uma\npressão vesical de perda (VLPP) de 40cm H?O, sem evidências de contrações involuntárias do\ndetrusor. O tipo de incontinência urinária apresentada nesse caso é","options":{"A":"por bexiga hiperativa.","B":"por transbordamento.","C":"de esforço por hipermobilidade do colo vesical.","D":"de esforço por deficiência esfincteriana intrínseca."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-311939","number":"311939","sourceNumber":"311939","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, 55 anos, comparece ao consultório ginecológico referindo-se a ondas de\ncalor. Essa queixa frequentemente leva as\nmulheres na perimenopausa a procurarem atendimento\nmédico. Essas ondas de calor implicam:","options":{"A":"vasodilatação periférica refletindo em aumento da temperatura corporal central.","B":"redistribuição periférica do fluxo sanguíneo que leva à sudorese e ao aumento da frequência\ncardíaca.","C":"vasodilatação periférica que resulta de uma ação direta do LH nos neurônios simpáticos.","D":"sintomas subjetivos sempre acompanhando sinais objetivos de instabilidade vasomotora."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-311940","number":"311940","sourceNumber":"311940","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Dentre as técnicas cirúrgicas para o tratamento da Incontinência Urinária de Esforço, a\ncirurgia de Burch, padrão ouro na segunda metade do século XX, suspendia os tecidos para\nuretrais a qual estrutura?","options":{"A":"Ao sacro.","B":"Ao ligamento inguinal.","C":"Ao ligamento de Cooper (pectíneo).","D":"Ao púbis."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-295394","number":"295394","sourceNumber":"295394","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"M.T.O., de 62 anos, viúva, comparece ao consultório com queixa principal de sensação\nde \"bola na vagina\". Relata sensação de\nabaulamento vaginal há dois anos, com piora dos\nsintomas há seis meses e dificuldade de iniciar a micção, com necessidade de reduzir o prolapso\npara urinar, associado à sensação de esvaziamento incompleto da bexiga. Nega perda de urina.\n\nTeve depressão, insônia e menopausa aos 40 anos de idade. Usa amitriptilina uma vez à noite. G6\nP5n A1, IMC: 34,65. Exame especular:\natrofia vulvovaginal, sem perda de urina, presença de\nprolapso uterino total, estágio IV e contração fraca da musculatura do assoalho pélvico. Em relação\nao diagnóstico da paciente, sabe-se que:","options":{"A":"a multiparidade e o parto normal transpélvico podem contribuir para a etiologia das distopias\ngenitais.","B":"o peso da paciente não influenciou na causa do prolapso, uma vez este que este está normal.","C":"o hiperestrogenismo decorrente da menopausa tardia pode ter contribuído para a causa do\nprolapso genital.","D":"aparentemente, a paciente não apresenta fatores de risco para distopias genitais e a causa do\nprolapso deve ser idiopática."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-295395","number":"295395","sourceNumber":"295395","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Segundo a Organização Mundial da Saúde, o climatério compreende o período de vida\nda mulher entre o final da fase reprodutiva e a senilidade. Em geral, varia dos 40 aos 65 anos.\n\nNesse período, ocorre a menopausa, definida como a interrupção permanente da menstruação\napós 12 meses de amenorreia. Sobre o climatério,\nsabe-se que:","options":{"A":"o diagnóstico deve ser confirmado com as dosagens de prolactina e LH.","B":"os fogachos são sensações transitórias súbitas de calor que se iniciam nos pés e sobem em\ndireção às pernas e joelhos.","C":"dentre os exames complementares para sua propedêutica, a RNM de tórax e cintilografia óssea\nsão mandatórias.","D":"a mamografia e a colpocitologia oncoparasitária são fundamentais na propedêutica básica do\nclimatério."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-300857","number":"300857","sourceNumber":"300857","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente, sexo feminino, 55 anos, foi submetida à histerectomia abdominal total\npreviamente. Relata que há 1 mês sente pressão\npélvica, dor na barriga, sensação de algo saindo\npela vagina. Tem tido quadro de incontinência urinária e dificuldade em evacuar. Relata, ainda, dor\nnas relações sexuais. Ao exame, há atrofia da vulva. Observa-se saliência da mucosa no introito. O\nrestante do exame pélvico, incluindo o exame retal e o teste do cotonete, é normal. Diagnóstico\nprovável de:","options":{"A":"Prolapso vaginal.","B":"Cistocele.","C":"Retocele.","D":"Enterocele."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-295396","number":"295396","sourceNumber":"295396","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapêutica hormonal (TH) é considerada como o tratamento mais eficaz para os\nsintomas vasomotores decorrentes da falência ovariana no climatério e envolve uma gama de\nhormônios (realizada com estrógenos, progestágenos e sua associação) por diferentes vias de\nadministração e doses e esquemas diversos. Sobre os benefícios do uso de TH, sabe-se que:","options":{"A":"São principalmente para o tratamento dos sintomas vasomotores e da atrofia vulvovaginal, no\nentanto, esta terapia pode levar à osteoporose e fraturas ósseas.","B":"São independentes da idade de início da terapia e da apresentação dos sintomas, da dosagem e\nda via de administração adotada.","C":"Para o tratamento dos sintomas vasomotores é considerada indicação primária a TH,\nespecialmente para mulheres sintomáticas abaixo dos 60 anos e com menos de 10 anos de\nmenopausa.","D":"Com a estrogenoterapia, ocorre uma atrofia celular vaginal reduzindo o fluxo sanguíneo e\ndiminuindo a espessura e a elasticidade vulvovaginal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-317985","number":"317985","sourceNumber":"317985","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Após a menopausa há, ainda, níveis de estrógenos circulantes por um período\nsignificativo. Nesta fase, o estrógeno predominante é","options":{"A":"a estrona.","B":"o estradiol.","C":"o estriol.","D":"o estetrol."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-294312","number":"294312","sourceNumber":"294312","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O tratamento da osteoporose em mulher de 55 anos, com sintomas vasomotores e\nmenopausa há cinco anos, deve ser iniciado com","options":{"A":"a vitamina D e o cálcio.","B":"a terapia hormonal da menopausa.","C":"os bifosfonados e o ácido zoledrônico.","D":"o anticorpo monocronal humano (denosumabe)."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-295400","number":"295400","sourceNumber":"295400","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A doença causada por urgência miccional, com ou sem incontinência, usualmente\nassociada com frequência urinaria aumentada e noctúria, na ausência de infecção urinaria é a","options":{"A":"incontinência urinaria de esforço.","B":"síndrome da bexiga hiperativa.","C":"fístula genital.","D":"distopia genital."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-317986","number":"317986","sourceNumber":"317986","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 48 anos, em amenorreia há cerca de um ano, com sintomas de fogachos\ncom desconforto social, associados a insônia,\nalterações de humor e inibição do desejo sexual.\nTem antecedentes de hipertensão arterial leve, histerectomia total e de avó materna com câncer de\nmama. Diante disso, a melhor opção terapêutica é","options":{"A":"a sertralina.","B":"as isoflavonas.","C":"a testosterona.","D":"o estradiol."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-317987","number":"317987","sourceNumber":"317987","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na prevenção e tratamento da osteoporose pós-menopausal, o efeito benéfico da\nterapia estro-progestínica se deve à sua ação","options":{"A":"antiabsortiva sobre os osteoclastos.","B":"estimuladora sobre a osteoclastogênese.","C":"antirreabsortiva e pró-formadora.","D":"estimuladora da função osteoblástica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-300868","number":"300868","sourceNumber":"300868","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Pós-menopausa é definido como o tempo decorrido após à última menstruação e tem\ninício 12 meses após a amenorreia espontânea. O conteúdo que se relaciona CORRETAMENTE\nao termo do enunciado é:","options":{"A":"Nesse período, os níveis de estradiona estão bruscamente reduzidos, consequência da perda de\nprodução folicular com a menopausa.","B":"Nesse período, a estrona, aromatizada pela androstenediona de fontes não foliculares, deixa de\ncircular.","C":"Nesse período, ocorre o evento de natureza endócrina que favorece as alterações menstruais,\nreduzindo acentuadamente a aptidão reprodutiva em muitos anos.","D":"Nesse período, há o aumento nas ?pausas? dos ciclos menstruais que começam de 2 a 8 anos\nantes da menopausa e se relacionam com a redução dos níveis séricos de inibina B (inibidor não\nesteroidal) da secreção do FSH hipofisário, em razão da queda de sua produção pelo folículo\nantral."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-300869","number":"300869","sourceNumber":"300869","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A menopausa é a menstruação final do ciclo reprodutivo feminino. Trata-se de um\nprocesso ovariano ocasionado pela perda da ação folicular e atresia fisiológica dos folículos\nprimordiais. Nesse contexto, são fatores que não afetam a idade da menopausa, EXCETO:","options":{"A":"Idade da menarca.","B":"Paridade.","C":"Etnia.","D":"Uso de anticoncepcionais."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-313254","number":"313254","sourceNumber":"313254","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Que tratamento não é indicado no prolapso de órgãos pélvicos?","options":{"A":"colpossuspensão retropúbica","B":"colpocleise","C":"colpopexia laparoscópica","D":"colporrafia posterior"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274445","number":"274445","sourceNumber":"274445","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Diante das evidências atuais, o câncer que parece ter sua incidência diminuída com a\nTerapia Hormonal da Menopausa é o de:","options":{"A":"Ovário.","B":"Endométrio.","C":"Cólon.","D":"Mama."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-265836","number":"265836","sourceNumber":"265836","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O tratamento considerado atualmente o MAIS eficaz nas queixas de fogachos na\nmenopausa é:","options":{"A":"Estrogênio.","B":"Tamoxifeno.","C":"Bazedoxifeno.","D":"Progesterona."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274447","number":"274447","sourceNumber":"274447","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Quando o sistema POP-Q evidencia os seguintes pontos: Ba +2; Bp -1; D-1, significa:","options":{"A":"Prolapso principal é apical e anterior.","B":"Paciente é histerectomizada.","C":"Prolapso posterior ultrapassa o hímen.","D":"Faltam dados para qualquer afirmação acima pois não temos as medidas."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274448","number":"274448","sourceNumber":"274448","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A pressão músculo detrusor da bexiga é avaliada:","options":{"A":"De forma direta, com a medição por meio de cateter vesical.","B":"De forma direta, com a medição por meio de cateter retal.","C":"De forma indireta, subtraindo a pressão abdominal da pressão vesical.","D":"De forma indireta, com medicação por meio de cateter vesical."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-285079","number":"285079","sourceNumber":"285079","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 65 anos, assintomática e sem comorbidades, chegou à menopausa\naos 50 anos e comparece ao consultório médico a\nfim de iniciar a terapia da menopausa. O\nprocedimento é:","options":{"A":"Indicar terapia de reposição hormonal via oral.","B":"Indicar terapia de reposição hormonal via transdérmica.","C":"Indicar terapia de reposição hormonal via subcutânea.","D":"Indicar terapia de reposição hormonal via percutânea.","E":"Não indicar terapia de reposição hormonal."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-277433","number":"277433","sourceNumber":"277433","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O conhecimento da fisiologia do trato urinário baixo e do mecanismo da continência\nurinária é importante no acompanhamento das\npacientes com disfunção miccional. Sobre esse\nmecanismo, é incorreto afirmar que:","options":{"A":"os receptores da bexiga de mais ampla aplicação clínica são os muscarínicos M2 e M3","B":"as fibras pré-ganglionares do sistema nervoso autônomo simpático se originam no núcleo sacral\nda micção","C":"as alterações do esvaziamento (exemplos: jato urinário fraco, ou micção com esforço) são raras\nna mulher","D":"na fase de enchimento vesical, ocorre predomínio do sistema nervoso autônomo simpático"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-281847","number":"281847","sourceNumber":"281847","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher climatérica de 49 anos, com ciclos irregulares, com períodos de amenorreia de\naté três meses, intercalados com menstruações com aumento da quantidade e duração, apresenta\nepisódios de fogachos noturnos, com prejuízos no sono. Neste caso, na ausência de\ncontraindicações, a melhor alternativa é o tratamento sistêmico com","options":{"A":"o progestágeno cíclico associado a hipnótico.","B":"a tibolona contínua associada ao ansiolítico.","C":"o estradiol associado ao progestágeno, contínuos.","D":"o estradiol contínuo associado ao progestágeno cíclico."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-281298","number":"281298","sourceNumber":"281298","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 90 anos é levada pela neta com queixa de apresentar \"uma bola na\nvagina\". Ao exame físico é constatado prolapso genital estágio III. A paciente tem insuficiência\ncardíaca, hipertensão e diabete. A melhor abordagem, nesse caso, é:","options":{"A":"Histerectomia vaginal.","B":"Histerectomia abdominal.","C":"Colpocleise.","D":"Sling."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-274790","number":"274790","sourceNumber":"274790","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 65 anos, queixando de sensação de peso no canal vaginal, com\nexteriorização de massa pelo canal vaginal\ncom início há 1 ano com piora progressiva. Nega perda\nde urina aos esforços e urgência miccional. Antecedentes obstétricos GIV PNIV. Ao exame físico\napresentou: Pode-se afirmar que:","options":{"A":"a cirurgia para correção deve ser a colporrafia anterior.","B":"correção cirúrgica deve ser a histerecetomia anterior e posterior.","C":"deve-se realizar a colporrafia posterior.","D":"deve-se realizar a colporrafia anterior e posterior."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/274790.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-257773","number":"257773","sourceNumber":"257773","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapia hormonal na menopausa","options":{"A":"é a mais efetiva para diminuir os fenômenos vasomotores.","B":"é a melhor opção para tratar os sintomas gênito-urinários, quando realizada via oral.","C":"não é efetiva para prevenir perdas ósseas e fraturas por fragilidade.","D":"aumenta a incidência de câncer colorretal (TH combinada)."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-257774","number":"257774","sourceNumber":"257774","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 52 anos, menopausada há dois anos, com fogachos que causam grande\ndesconforto noturno, prejudicando o sono.\nApresenta hipertensão arterial e diabetes mellitus (com\ncontrole irregular há cerca de 10 anos). Além disso, na dopplerfluxometria das carótidas,\n\nobserva-se placas ateromatosas bilateralmente. Diante desse quadro, a conduta mais indicada é:","options":{"A":"a terapia hormonal via oral.","B":"a venlafaxina ou desvenlafaxina.","C":"a terapia hormonal via transdérmica.","D":"os esteroides sexuais bioidênticos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-252725","number":"252725","sourceNumber":"252725","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 48 anos, que não menstrua há 14 meses, vem com queixa de ondas de\ncalor. Não tem antecedentes pessoais e/ou\nfamiliares oncológicos. Deseja fazer uso da Terapia de\nReposição Hormonal. Em relação à reposição hormonal neste caso, qual afirmativa é verdadeira?","options":{"A":"As evidências atuais são suficientes para demonstrar efeito significativo positivo da terapia\nhormonal no interesse sexual, excitação e resposta orgástica.","B":"As evidências são limitadas acerca dos efeitos da terapia de reposição hormonal na prevenção\nda osteoporose na pós-menopausa.","C":"A indicação primária da terapia de reposição hormonal é o controle das ondas de calor.","D":"Mesmo em mulheres pós-menopausa assintomáticas, há nível de evidência A de que a terapia\nde reposição hormonal melhore a qualidade de\nvida."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-232223","number":"232223","sourceNumber":"232223","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O cateterismo intermitente limpo (CIL) provou ser o meio mais eficaz e prático de\nmanter o paciente sem sondagem vesical de\ndemora na maioria dos pacientes que não conseguem\nesvaziar a bexiga espontaneamente. O CIL revolucionou o tratamento de casos difíceis de\ndisfunção neuromuscular vesical, fornecendo um método seguro e eficaz que preserva a\nindependência do paciente para esvaziar a bexiga nos casos em que a continência foi alcançada\nfarmacologicamente ou cirurgicamente, produzindo retenção urinária total ou parcial. Cateteres de\nlonga permanência devem ser considerados quando limitações anatômicas, funcionais ou familiares\nproíbem a realização do CIL. O cateterismo contínuo também pode ser indicado em pacientes com\ncomplicações de incontinência persistente ou disreflexia autonômica, apesar da terapia ou quando\numa pequena capacidade da bexiga proíbe CIL eficaz. Assim, em relação ao cateterismo vesical,\npode-se afirmar o seguinte:","options":{"A":"o cateterismo de longa permanência é inferior ao CIL, especificamente em relação às\ncomplicações do trato urinário e à qualidade de vida.","B":"a bacteriúria assintomática é incomum em pacientes que realizaram CIL ou são portadores de\ncateteres de longa permanência e não requerem tratamento, a menos que o paciente se torne\nsintomático.","C":"as complicações mais comuns associadas ao uso de cateter incluem infecções (epididimite,\nabscesso periuretral, pielonefrite), cálculos renais e da bexiga, estenose uretral e refluxo\nvesicoureteral.","D":"o paciente com lesão medular com um cateter vesical de uso crônico tem risco a longo prazo de\ncarcinoma vesical. Essa associação também foi identificada em pacientes que realizam cateterismo\nintermitente."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-247444","number":"247444","sourceNumber":"247444","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 60 anos com sintomas de urgência miccional e noctúria, nega perda de\nurina aos esforços. Apresenta exames de EAS e Urocultura sem alterações, não apresenta\ndiabetes e sem uso de medicações. A hipótese diagnóstica mais provável é:","options":{"A":"Incontinência urinária por deficiência esfincteriana intrínseca.","B":"Hipermobilidade uretral.","C":"Hiperatividade do detrusor.","D":"Fístula vesicovaginal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-229867","number":"229867","sourceNumber":"229867","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Lídia, 42 anos, secretária, vem à consulta na Unidade Básica de Saúde com queixa de\nperda de urina quando espirra ou quando agacha no trabalho há 2 anos. Nega disúria, polaciúria ou\nurgência urinária. Conta que a situação está piorando e está tendo prejuízo no seu desempenho do\ntrabalho. Tem medo de fazer cirurgia. Já passou por 3 cesáreas e sofreu muito no pós-operatório.\n\nConsiderando o caso de Lídia e seus conhecimentos sobre incontinência urinária, a melhor\nalternativa é","options":{"A":"o tratamento cirúrgico é necessário no caso de Lídia, pois trata-se de um caso de incontinência\nde esforço;","B":"o treinamento dos músculos do assoalho pélvico tem como objetivo o relaxamento da\nmusculatura do períneo;","C":"nesse caso, é necessário solicitar um estudo urodinâmico para definir o tipo de incontinência;","D":"a avaliação digital durante o toque vaginal ou retal é adequada para medir força e capacidade da\nmusculatura do assoalho pélvico."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-247445","number":"247445","sourceNumber":"247445","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 60 anos procurou atendimento ginecológico por queixa de perda urinária\naos esforços. Foi submetida a estudo urodinâmico\nque registrou pressão de perda uretral de 40 cm\nde h²0. Isso caracteriza incontinência urinária por:","options":{"A":"deficiência esfincteriana intrínseca.","B":"bexiga hiperativa.","C":"transbordamento.","D":"hiperatividade detrusora."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-248956","number":"248956","sourceNumber":"248956","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapia hormonal estroprogestacional na pós-menopausa é contraindicada em casos\nde: I - Encefalopatia herpética e\ntromboembolismo profundo; ll- Porfiria aguda e suspeita de câncer\nde endométrio; III - Câncer colorretal e cardiopatia isquêmica. Está(ão) correta (s):","options":{"A":"l, apenas","B":"II, apenas","C":"lll, apenas","D":"II, III"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-248957","number":"248957","sourceNumber":"248957","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A principal queixa das mulheres na perimenopausa é:","options":{"A":"fogacho","B":"ressecamento vaginal","C":"Iabilidade emocional","D":"ganho de peso"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-254268","number":"254268","sourceNumber":"254268","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Quando o sistema POP-Q evidencia os seguintes pontos: Ba+2;Bp-1; C+1; D-1,\nsignifica:","options":{"A":"Prolapso principal é apical e anterior.","B":"Paciente é histerectomizada.","C":"Prolaspo posterior ultrapassa o hímen.","D":"Faltam dados para qualquer afirmação acima, pois não temos as medidas."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-234369","number":"234369","sourceNumber":"234369","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diagnóstico da incontinência urinária é clínico, com ênfase no diário miccional e no\nexame físico. Os fatores mais importantes na\nanamnese são a duração do sintoma, que tipo de\nesforço provoca a perda, se a perda ocorre com pouco volume na bexiga, se usa absorvente,\nantecedentes de cirurgia ginecológica ou obstétrica, tosse crônica, obesidade, noctúria, urgência\nmiccional e enurese noturna. Com base no exposto,","options":{"A":"A incontinência urinária de esforço (IUE) é caracterizada por urgência miccional e noctúria.","B":"A síndrome da bexiga hiperativa (SBH) é definida pela perda involuntária de urina, associada à\ntosse, ao espirro ou ao esforço.","C":"A cirurgia de Kegel é o padrão-ouro no tratamento da incontinência urinária de esforço (IUE).","D":"O sling com passagem transobturatória tem melhores resultados quando há hipermobilidade\nuretral e IUE de graus 2 e 3."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-241764","number":"241764","sourceNumber":"241764","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 49 anos refere ciclos oligomenorreicos há 2 anos, com última menstruação\nhá seis meses. Apresenta-se com queixa de\nfogachos, insônia, labilidade emocional e diminuição\nda libido. Nega comorbidades. Frente a esse quadro, pode-se afirmar que: I. A paciente\n\nencontra-se na perimenopausa. II. Há indicação de terapia hormonal, e esta deverá ser combinada\n(estroprogestativa) ou com tibolona. III. Os ciclos anovulatórios são a principal causa de\nirregularidade menstrual nesse período. IV. Dosagens de FSH, LH e estradiol são fundamentais\npara o diagnóstico nessa paciente. Pode-se afirmar que:","options":{"A":"apenas os itens I e II estão corretos.","B":"apenas os itens I, II e III estão corretos.","C":"apenas os itens II e III estão corretos.","D":"apenas os itens II e IV estão corretos.","E":"todos os itens estão corretos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-229890","number":"229890","sourceNumber":"229890","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 54 anos, G3P2A1C1, com queixa de perda urinária aos esforços, urgência\nmiccional, nictúria e urgeincontinência, sem\ndistopia genital ao exame físico. O estudo urodinâmico\nevidenciou fase de esvaziamento normal e fase de enchimento apenas com algumas contrações\ninvoluntárias do detrusor, associadas com perdas urinárias. Com base nestas evidências, o\ndiagnóstico é de:","options":{"A":"Incontinência urinária de esforço.","B":"Bexiga hiperativa.","C":"Incontinência urinária mista.","D":"Bexiga neurogênica hipotônica."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-229892","number":"229892","sourceNumber":"229892","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 60 anos, viúva, tabagista, submetida à colpoperineoplastia há 2 anos,\npermanece com queixa de IUE. Ao estudo\nurodinâmico, foi diagnosticado hipermobilidade do colo\nvesical. Nesse caso o tratamento de escolha é:","options":{"A":"Medicamentoso.","B":"Sling.","C":"Burch.","D":"Colpocleise."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-229576","number":"229576","sourceNumber":"229576","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher procura ginecologista com queixa de perda urinária involuntária e constante,\nassociada a micções voluntárias. Refere que\nos sintomas começaram após uma cesárea com\nhisterectomia de urgência por acretismo placentário. A causa MAIS provável da sintomatologia é:","options":{"A":"fístula vesico-vaginal.","B":"fístula vesico-uterina.","C":"bexiga neurogênica.","D":"fístula uretero-vaginal unilateral."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-229897","number":"229897","sourceNumber":"229897","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério é caracterizado como a fase de transição entre o menacme e a senectude.\nSobre esta fase é CORRETO afirmar que as\nmulheres:","options":{"A":"Podem apresentar elevação de FSH, mesmo com ciclos menstruais presentes.","B":"Apresentam elevações do LH superiores as do FSH.","C":"Mantêm o estradiol como o principal estrogênio circulante no plasma.","D":"Apresentam uma queda abrupta nos níveis de testosterona plasmática."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216619","number":"216619","sourceNumber":"216619","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A osteoporose representa hoje um grave problema de saúde pública, apresentando um\nalto índice de morbimortalidade, sendo necessário uma abordagem multidisciplinar. Sobre essa\ndoença, verifica-se que:","options":{"A":"O exame de densitometria deve ser solicitado para todas as mulheres após 3 anos de\nmenopausa.","B":"T-score na densitometria é a comparação com a média das pacientes com a mesma idade e\netnia.","C":"A calcitonina e os bisfosfonatos são medicações com efeitos pró-formadores.","D":"Os bisfosfonatos são uma opção segura, mas podem ter como efeito colateral esofagite química."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216497","number":"216497","sourceNumber":"216497","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Representa fator de risco para osteoporose em mulheres:","options":{"A":"Hiperprolactinemia.","B":"Glaucoma.","C":"Obesidade.","D":"Hipertireoidismo"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-216667","number":"216667","sourceNumber":"216667","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 60 anos, apresentando urgência miccional há 1 ano, associado a\nnoctúria. Apresenta glicemia de jejum normal, urocultura negativa e estudo urodinâmico com\ncontrações não inibidas do detrusor. Sobre esse quadro clínico, tem-se o seguinte:","options":{"A":"A paciente teria indicação de realizar a cirurgia de Sling.","B":"A oxibutinina poderia ser utilizada, porém tem como efeitos colaterais: boca seca, obstipação\nintestinal, borramento visual e retenção urinária.","C":"A tolterodina poderia ser utilizada, porém apresenta mais efeitos colaterais que a oxibutinina.","D":"A idade da paciente contraindica o tratamento medicamentoso."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-214913","number":"214913","sourceNumber":"214913","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Quando se descreve a vascularização da pelve feminina, descarta-se a seguinte\nafirmação:","options":{"A":"o suprimento sanguíneo uterino vem do ramo ascendente da artéria uterina e do ramo medial da\nartéria ovariana","B":"a artéria uterina pode originar-se da ilíaca interna como ramo independente ou ter origem\ncomum com as artérias pudenda e vaginal","C":"cada artéria uterina dá origem a numerosos ramos que penetram na parede uterina e se dividem\nem grupos de artérias arqueadas anteriores e\nposteriores","D":"a artéria uterina, após passar por baixo do ureter, divide-se em ramo maior, ascendente, e\nmenor, descendente"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-201678","number":"201678","sourceNumber":"201678","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Para as pacientes em transição menopausal, sem sintomas vasomotores, com ciclos\nmenstruais irregulares, a prescrição mais adequada é:","options":{"A":"Estrogênios isolados de forma contínua.","B":"Progestagênios de 10 a 14 dias, simulando a segunda fase do ciclo.","C":"Associação estrogênios-progestagênios de forma contínua.","D":"Progestagênios isolados, em altas doses, de forma contínua."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-210578","number":"210578","sourceNumber":"210578","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Considere o caso: C.A.V, 48 anos, procura atendimento no posto de saúde com queixa\nde perda urinária ao tossir e realizar\natividades diárias como pegar peso. Relata sintomas iniciados\nhá 1 ano. Ao exame físico não apresenta prolapso genital e houve perda urinária ao realizar\nmanobra de valsalva. Sobre esse distúrbio tão prevalente na população feminina, assinale a\nalternativa incorreta.","options":{"A":"O tabagismo e a obesidade são fatores de risco.","B":"Na incontinência urinária paradoxal, a paciente possui vontade de urinar, mas apenas consegue\neliminar gotas de urina.","C":"Na incontinência urinária de urgência ocorrem distúrbios neurológicos e sensitivos ou\nhiperatividade motora do músculo detrusor.","D":"A incontinência urinária aos esforços está associada com urgência urinária.","E":"Exame de urina e urocultura devem ser solicitados na consulta inicial."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-210583","number":"210583","sourceNumber":"210583","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma queixa muito comum das pacientes nos ambulatórios de ginecologia são a\nsensação de \"peso na vagina\". Muitas vezes\ndiagnosticados como prolapsos vaginais ao realizar o\nexame físico. Sobre o prolapso vaginal, assinale a alternativa incorreta.","options":{"A":"É sempre indicação de correção cirúrgica.","B":"Na classificação POP-Q, o ponto Aa corresponde à localização proximal da prega uretrovesical.","C":"Entre os fatores de risco estão: aumento da pressão intra-abdominal, tabagismo e DPOC.","D":"No POP-Q, o hiato genital é medido a partir do meio do meato uretral externo até a linha média\ndo hímen posterior.","E":"A contração dos músculos levantadores do ânus estreia o hiato genital e previne prolapsos de\nórgãos pélvicos."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-214115","number":"214115","sourceNumber":"214115","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A principal causa de incontinência urinária em mulheres é a:","options":{"A":"Infecção urinária de repetição.","B":"Incontinência de esforço.","C":"Hiperatividade do detrusor.","D":"Sequela pós cirúrgica."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-215362","number":"215362","sourceNumber":"215362","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Normalmente o ângulo utetrovesical posterior mede","options":{"A":"50 graus.","B":"30 graus.","C":"120 graus.","D":"de 90 a 100 graus."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-210538","number":"210538","sourceNumber":"210538","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O climatério representa a transição da vida reprodutiva para a não reprodutiva. É um\nperíodo caracterizado por intensos sintomas e alterações no ciclo menstrual da mulher. Sobre o\nclimatério e a menopausa, assinale a alternativa correta.","options":{"A":"Os fogachos e sudorese são sintomas relacionados ao hiperestrogenismo no período do\nclimatério.","B":"A menopausa só é diagnosticada através da dosagem de FSH e estradiol.","C":"A paciente, ao entrar na menopausa, deverá realizar densitometria óssea anualmente.","D":"É mandatório o exame clínico das mamas e solicitação de ultrassonografia antes de se iniciar\nterapia de reposição hormonal.","E":"Pacientes histerectomizados podem realizar terapia de reposição hormonal apenas com\nestrogênio."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-205647","number":"205647","sourceNumber":"205647","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 47 anos, com quadro de depressão, sudorese excessiva, insônia e\nirritabilidade. Exames laboratoriais indicam anovulação. O diagnóstico mais provável é:","options":{"A":"Psicose.","B":"Transtorno bipolar.","C":"Menopausa.","D":"Depressão Maior."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-214156","number":"214156","sourceNumber":"214156","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Márcia, 50 anos, dona-de-casa, vem à consulta de revisão com seu médico de família.\nRelata que nos últimos meses tem apresentado episódios de calorões e insônia. Descreve\nepisódios súbitos de calor localizado em tórax superior e face, associados à sudorese profusa e\nintenso desconforto. Já teve o sono interrompido durante a noite por esses episódios e,\nultimamente, ao preparar-se para dormir, já imagina que irá acordar com esses sintomas. Algumas\nvezes, também fica acordada para esperar a filha voltar do curso noturno. Está preocupada com a\ndoença do pai, que tem enfisema e recentemente teve indicação e oxigenioterapia domiciliar.\n\nEmociona-se ao fazer este relato. Questionada, refere que há 4 meses não menstrua e, antes\ndisso, os ciclos estavam irregulares.\nPergunta ao médico se pode estar na menopausa. Menciona\nque a irmã mais velha disse que \"isso faz parte da idade\" e que ela \"irá se acostumar\". Reside com\nesposo e os três filhos mais novos. A filha mais velha é casada e tem filhos gêmeos de 2 anos, que\nsão cuidados por Márcia no turno da tarde. Nega desavenças ou problemas familiares, admitindo\napenas \"preocupações\". Apresenta sobrepeso e fez colecistectomia há 5 anos. A mãe é hipertensa\ne a tia paterna faleceu por câncer de mama. Questiona médico sobre a necessidade de dosagens\nhormonais e realização de densitometria óssea. Refere que \"quer fazer tudo o que for possível para\nviver bem na velhice\". O diagnóstico diferencial das manifestações do climatério inclui as seguintes\ncondições, exceto.","options":{"A":"hipoprolactinemia.","B":"gestação e lactação.","C":"efeitos adversos da medroxiprogesterona, do tamoxífeno e do danazol.","D":"hipertireoidismo."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-214163","number":"214163","sourceNumber":"214163","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Márcia, 50 anos, dona-de-casa, vem à consulta de revisão com seu médico de família.\nRelata que nos últimos meses tem apresentado episódios de calorões e insônia. Descreve\nepisódios súbitos de calor localizado em tórax superior e face, associados à sudorese profusa e\nintenso desconforto. Já teve o sono interrompido durante a noite por esses episódios e,\nultimamente, ao preparar-se para dormir, já imagina que irá acordar com esses sintomas. Algumas\nvezes, também fica acordada para esperar a filha voltar do curso noturno. Está preocupada com a\ndoença do pai, que tem enfisema e recentemente teve indicação e oxigenioterapia domiciliar.\n\nEmociona-se ao fazer este relato. Questionada, refere que há 4 meses não menstrua e, antes\ndisso, os ciclos estavam irregulares.\nPergunta ao médico se pode estar na menopausa. Menciona\nque a irmã mais velha disse que \"isso faz parte da idade\" e que ela \"irá se acostumar\". Reside com\nesposo e os três filhos mais novos. A filha mais velha é casada e tem filhos gêmeos de 2 anos, que\nsão cuidados por Márcia no turno da tarde. Nega desavenças ou problemas familiares, admitindo\napenas \"preocupações\". Apresenta sobrepeso e fez colecistectomia há 5 anos. A mãe é hipertensa\ne a tia paterna faleceu por câncer de mama. Questiona médico sobre a necessidade de dosagens\nhormonais e realização de densitometria óssea. Refere que \"quer fazer tudo o que for possível para\nviver bem na velhice\". Caso se indique o tratamento medicamentoso para os sintomas\nvasomotores, a melhor alternativa para Márcia seria:","options":{"A":"Fitoterápicos.","B":"Acupuntura.","C":"Terapia hormonal apenas com estrogênio.","D":"Terapia hormonal com estrogênio e progestogênio."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-185169","number":"185169","sourceNumber":"185169","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Entender a fisiopatologia da osteoporose pós-menopausa é importante, inclusive para\nevitar fratura osteoporótica, um dos efeitos mais deletérios ao paciente. A diminuição abrupta da\nmassa óssea tem relação com níveis decrescentes de","options":{"A":"progesterona.","B":"paratormônio.","C":"calcitonina.","D":"estrogênio."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-173518","number":"173518","sourceNumber":"173518","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diagnóstico de lesões vesicais, ao se fazer uma cistoscopia, como úlcera de Hunner,\nestá associado à seguinte patologia:","options":{"A":"câncer in situ vesical.","B":"câncer vesical superficial.","C":"cistite intersticial.","D":"esquistossomose vesical."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-175383","number":"175383","sourceNumber":"175383","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 30 anos, submetida há 2 meses a histerectomia total abdominal por\nmiomatose uterina, refere perda involuntária de urina sem associação a esforços ou vontade de\nurinar. O exame físico está normal, e o especular apresenta cúpula vaginal normal e excesso de\numidade na vagina. A principal hipótese diagnóstica é:","options":{"A":"incontinência urinária de esforço","B":"urgência miccional","C":"síndrome urinária","D":"fístula vesicovaginal","E":"hipermobilidade do colo vesical"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-175390","number":"175390","sourceNumber":"175390","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma senhora de 56 anos, multípara, queixa-se de sintomas vasomotores há cerca de 3\nanos, que pioraram após tratamento cirúrgico radical para mioma submucoso. Assinale a alternativa\nque apresenta a melhor terapia para tal sintomatologia:","options":{"A":"androstenediona","B":"acetato de medroxiprogesterona","C":"nandrolona","D":"estrogênios e progestogênios","E":"estradiol"},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-187705","number":"187705","sourceNumber":"187705","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A menopausa representa uma fase da vida onde são freqüentes sintomas vasomotores\ncomo os fogachos. A terapia de reposição\nhormonal com estrogênios no climatério é uma\norientação recomendada por muitos especialistas e possui algumas contra-indicações, como:","options":{"A":"Varizes de membros inferiores e osteoporose.","B":"Cisto ovariano e litíase renal.","C":"Câncer de mama e distúrbios tromboembólicos ativos.","D":"Hipotiroidismo e deficiência de vitamina D."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-185171","number":"185171","sourceNumber":"185171","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre o perfil hormonal pós-menopausa, verifica-se que","options":{"A":"ocorre o aumento do FSH e diminuição do LH.","B":"ocorre o aumento de testosterona total.","C":"o principal estrogênio circulante é a estrona.","D":"ocorre o aumento do sulfato de dehidroepiandrosterona circulante."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-185132","number":"185132","sourceNumber":"185132","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 50 anos, menopausada há 5 anos, sem comorbidades, vem à consulta\napenas com queixa de dispaurenia e secura\nvaginal, negando outros sintomas, como fogachos,\nirritabilidade, entre outros. O exame ginecológico está dentro da normalidade, apresentando\napenas uma mucosa vaginal hipotrófica. Qual o tratamento proposto para melhorar a queixa desta\npaciente?","options":{"A":"Uso de estrogênio tópico e lubrificantes.","B":"Dosagem de hormônio folículo estimulante (FSH) e estradiol (E2) para estabelecer a posologia\nhormonal a ser utilizada.","C":"Explicar à paciente que não há nada a fazer.","D":"Uso de tibolona visando à melhora do muco e da libido."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-186488","number":"186488","sourceNumber":"186488","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"No tratamento clínico da hiperatividade do detrusor, as drogas utilizadas incluem: I.\nAntimuscarínicos; II. Colinérgicos; III. Antidepressivos tricíclicos; IV. Beta-bloqueadores. Está\ncorreto apenas o contido em:","options":{"A":"I, II e III.","B":"I e III.","C":"II e IV.","D":"I e II."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-187580","number":"187580","sourceNumber":"187580","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A osteoporose é uma doença sistêmica, caracteriza por baixa massa óssea e\ndeterioração micro arquitetural do tecido ósseo,\ncom consequente aumento da fragilidade óssea e\nda suscetibilidade de fratura. O fator de risco relacionado a osteoporose primária é:","options":{"A":"alcoolismo.","B":"diminuição de estrógeno pós menopausa.","C":"uso de glicocorticoide.","D":"hiperparatireoidismo."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-186436","number":"186436","sourceNumber":"186436","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 48 anos, G3P3, tem perda de urina com tosse e espirro. Ela nega\ndisúria ou urgência urinária. Qual das\nalternativas seguintes provavelmente está presente no exame\nfísico?","options":{"A":"Uretra hipermóvel.","B":"Retocele.","C":"Bexiga hipertrófica.","D":"Defeito paravaginal."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-185187","number":"185187","sourceNumber":"185187","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 52 anos, GIII PNIII, com perda de urina aos mínimos esforços. Nega\nsintomas de urgência e Noctúria. Realizou\nestudo urodinâmico apresentando pressão de perda de\n50mmhg, sem contrações involuntárias. A melhor opção de tratamento para essa paciente é a\nindicação de","options":{"A":"cirurgia de Sling.","B":"uso de oxibutinina.","C":"cirurgia de Marshall Market Kranz.","D":"uso de toxina botulínica em musculo detrusor."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-186428","number":"186428","sourceNumber":"186428","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 51 anos apresenta oligomenorreia e fogachos. Qual dos mecanismos diretos\nde amenorreia a seguir melhor combina com a\nsituação clínica descrita?","options":{"A":"Insensibilidade do receptor de gonadotrofina.","B":"Disfunção pituitária.","C":"Insuficiência ovariana.","D":"Disfunção hipotalâmica."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-174132","number":"174132","sourceNumber":"174132","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diafragma pélvico é formado pelos músculos:","options":{"A":"levantador do ânus e coccígeo.","B":"transverso profundo do períneo e piriforme.","C":"piriforme e iliopsoas.","D":"obturador interno e levantador do ânus."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-173590","number":"173590","sourceNumber":"173590","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Alguns exames hormonais são utilizados para diagnóstico de baixa da reserva ovariana\ne para predizer a ocorrência de menopausa.\nAssim:","options":{"A":"O exame do nível de hormônio folículo estimulante (FSH) é realizado no terceiro dia do ciclo\nmenstrual, reflete a capacidade funcional do hipotálamo e da hipófise que, na proximidade da\nmenopausa, apresenta FSH acima de 2 mUI/ml.","B":"A avaliação do estradiol sanguíneo no terceiro dia do ciclo menstrual também pode fazer a\npredição de menopausa, quando os níveis se aproximam de 40 mUI/ml a menopausa ocorre em\nmenos de dois meses.","C":"O hormônio antimülleriano (AMH) é considerado como o melhor marcador de reserva ovariana e\nexames com valores inferiores a 1 mg/ml são indicadores de baixa reserva ovariana e sugerem a\nocorrência da menopausa em até cinco anos.","D":"O volume ovariano diminuído à ultrassonografia e a presença de 6 a 12 folículos antrais são\nindicativos de baixa reserva ovariana e de ocorrência de menopausa em, no máximo, um ano."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-187553","number":"187553","sourceNumber":"187553","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente menopausada há mais de 3 anos, comparece ao consultório queixando-se de\ndispaureunia e secura vaginal, sem outros sintomas. Exame ginecológico normal apresentando\napenas mucosa vaginal hipotrófica. A conduta médica imediata indicada para melhorar a queixa da\npaciente é o uso de","options":{"A":"hormônios após exames.","B":"estrogênios associados à progestágenos.","C":"estrogênios tópico e lubrificantes.","D":"tibolona e lubrificantes."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183239","number":"183239","sourceNumber":"183239","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação ao Prolapso Uretral, assinale a alternativa CORRETA:","options":{"A":"Pode causar sangramento.","B":"Acontece somente em mulheres na pós-menopausa.","C":"Pode ser tratado com progesterona tópica.","D":"Ocorre principalmente no menacme."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183319","number":"183319","sourceNumber":"183319","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Após cirurgia de histerectomia há 35 dias, paciente retorna referindo perda involuntária\nde urina pela vagina. O teste com azul de\nmetileno resulta negativo. A fístula é, portanto:","options":{"A":"Vesico-uterina.","B":"Uretero-vaginal.","C":"Vesico-vaginal.","D":"Ureto-vaginal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-183211","number":"183211","sourceNumber":"183211","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"?Dor pélvica crônica, pressão ou desconforto percebidos pelo doente como\nrelacionados com a bexiga, acompanhado de, pelo\nmenos, outro sintoma urológico com mais de\nseis meses de evolução, estando excluídas outras doenças identificáveis?. A definição acima se\nrefere a:","options":{"A":"Doença Hemolítico-urêmica.","B":"Doença Inflamatória Pélvica.","C":"Cistite Intersticial.","D":"Síndrome do Intestino Irritável."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-174459","number":"174459","sourceNumber":"174459","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Muito em ?moda? nas academias atualmente, a utilização de Testosterona em\nmulheres tem como possíveis efeitos todos os listados abaixo, EXCETO:","options":{"A":"Melhora da libido.","B":"Diminuição do risco de desenvolver Alzheimer.","C":"Diminuição do risco de osteroporose.","D":"Ganho de massa muscular."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-156406","number":"156406","sourceNumber":"156406","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Quais os ligamentos importantes, responsáveis pela sustentação do útero na pelve?","options":{"A":"Ligamentos redondos e cardinais.","B":"Ligamentos paracervicais e ligamento útero-sacro.","C":"Ligamentos pubo-vésico-uterino e ligamentos largo.","D":"Ligamentos útero-ováricos e ligamentos útero-sacro."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-156478","number":"156478","sourceNumber":"156478","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Segundo a Federação Brasileira das Associações de Ginecologia e Obstetrícia\n(FEBRASGO) a pós-menopausa inicia-se:","options":{"A":"6 meses após o último período menstrual","B":"9 meses após o último período menstrual","C":"12 meses após o último período menstrual","D":"18 meses após o último período menstrual"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-156479","number":"156479","sourceNumber":"156479","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Segundo Novak, é considerada insuficiência ovariana prematura, a ocorrência\nespontânea da menopausa antes de:","options":{"A":"30 anos","B":"35 anos","C":"38 anos","D":"40 anos"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-154644","number":"154644","sourceNumber":"154644","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação aos sintomas vasomotores (fogachos) observados em muitas mulheres na\nmenopausa, assinale a alternativa correta:","options":{"A":"A progesterona desempenha um papel importante no desenvolvimento do fogacho.","B":"Costumam iniciar após um ano de amenorreia em 90% das mulheres.","C":"Pacientes com menopausa cirúrgica não costumam apresentar fogachos.","D":"Duram em média de 1 a 5 minutos, a frequência cardíaca aumenta de 7 a 17 bpm e a\ntemperatura interna diminui de 0,1 a 0,9 °C\ndentro do período de 5 a 9 minutos após o início do\nsintoma.","E":"São mais prevalentes em mulheres com hipotireoidismo."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157012","number":"157012","sourceNumber":"157012","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação à Terapia Hormonal (TH) no climatério, assinale a alternativa correta.","options":{"A":"Está relacionada a aumento do ganho de peso.","B":"Favorece o acúmulo de gordura na região da cintura.","C":"Reduz a perda mineral óssea e a incidência de câncer colorretal.","D":"É mais trombogênica do que o uso de anticoncepcionais hormonais orais."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-160555","number":"160555","sourceNumber":"160555","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapia de reposição hormonal (TH) traz uma melhora significativa à qualidade de\nvida das mulheres na fase climatérica. Dessa forma, a conduta médica adequada inclui:","options":{"A":"Iniciar TH para todas as mulheres após os 45 anos de idade.","B":"Avaliar os fatores de risco para câncer de mama, antes de iniciar TH.","C":"O uso do estrogênio isolado, em baixas doses, é a primeira escolha.","D":"Mulheres tabagistas devem iniciar TH o mais precocemente possível."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-158471","number":"158471","sourceNumber":"158471","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"NÃO se configura contraindicação ao uso de terapia de reposição hormonal durante o\nclimatério:","options":{"A":"Hiperplasia ductal atípica da mama.","B":"Avó com câncer de mama.","C":"Hepatopatia grave.","D":"Trombose venosa profunda recente."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157055","number":"157055","sourceNumber":"157055","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 80 anos queixa-se de perda urinária frequente. Sem outra\nespecificação, qual é a principal causa para essa queixa na referida faixa etária?","options":{"A":"Incontinência urinária de esforço anatômica.","B":"Divertículo uretral.","C":"Incontinência urinária de urgência.","D":"Fístula urinária."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-158476","number":"158476","sourceNumber":"158476","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 75 anos procura atendimento no ambulatório de uroginecologia com\nantecedente de prolapso genital há 04 anos.\nAo exame ginecológico do estudo deste prolapso foi\nevidenciado: Aa=+3, Ba=+5, C=+6, D= , Ba=0, Bp=-1. Qual é o tratamento mais adequado?","options":{"A":"Sling vaginal.","B":"Histerectomia vaginal, correção de cistocele e retocele.","C":"Colpocleise por via vaginal.","D":"Colpossacrofixação por via abdominal."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-150214","number":"150214","sourceNumber":"150214","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 66 anos, sem relato de uso prévio de reposição hormonal, refere ausência\nde fluxo menstrual há aproximadamente 15 anos,\nressecamento vaginal e desconforto intenso\ndurante as relações sexuais. Neste caso, a terapia hormonal:","options":{"A":"Está contraindicada, se houver histórico de câncer de mama, em parente de primeiro grau.","B":"Está indicada com o uso de estrogênio tópico isoladamente em dose diária mínima.","C":"está indicada com o uso com o emprego de progestogênio isoladamente se a paciente tiver sido\nhisterectomizada.","D":"Tem o propósito de prevenir fraturas osteoporóticas, sendo apropriada e recomendada."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157388","number":"157388","sourceNumber":"157388","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 40 anos, submetida à histerectomia total abdominal, passa a apresentar\nperda urinária pela vagina. Nesse caso, qual é\na causa MAIS provável?","options":{"A":"Fístula ureterovesical.","B":"Bexiga neurogênica.","C":"Fístula vesicovaginal.","D":"Fístula retovesical."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-157373","number":"157373","sourceNumber":"157373","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à osteoporose, assinale a opção que apresenta a medida\ncomprovadamente eficaz para a sua prevenção:","options":{"A":"Evitar álcool e drogas.","B":"Exercícios físicos regulares e aumento da massa corporal.","C":"Evitar ingestão de cafeína.","D":"Ingestão de medicamentos antiácidos regularmente."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-138610","number":"138610","sourceNumber":"138610","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 56 anos de idade refere fogachos e sudorese noturna que atrapalham o\nsono. Informa que usou medicamentos não hormonais e até fito-hormônios, porém sem melhora.\nRefere que é tabagista (05 cigarros/dia) e hipertensa (faz uso de três fármacos anti-hipertensivos\npara controle). Qual o melhor esquema de terapia hormonal para essa paciente?","options":{"A":"Baixa dose de estrogênio por via não oral.","B":"Dose convencional de estrogênio e de progestagênio por via oral.","C":"Dose convencional de estrogênio e de androgênio por via intramuscular.","D":"Progestagênio por via de liberação intrauterina."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127686","number":"127686","sourceNumber":"127686","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Distúrbios miccionais são devidos ao mau funcionamento do trato urinário inferior,\nacometendo homens, mulheres e crianças. Nesses casos:","options":{"A":"A condição sine qua non para um diagnóstico preciso é o examinador realmente testemunhar a\nincontinência urinária.","B":"A sondagem vesical pós-miccional é o método menos invasivo para medida desse resíduo.","C":"Os agentes antimuscarínicos são o pilar do tratamento farmacológico da incontinência causada\npor insuficiência esfincteriana.","D":"O decréscimo de ingestão de líquidos e a micção programada pelo relógio têm sido usados para\ntratar incontinência urinária de esforço."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127980","number":"127980","sourceNumber":"127980","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A Dor Pélvica Crônica (DPC) é uma afecção frequente entre as mulheres. Sobre ela,\nassinale a alternativa INCORRETA:","options":{"A":"A etiologia é frequentemente incerta, sendo a região e a estrutura anatômica acometida um\nnorte mais utilizado para o planejamento propedêutico e terapêutico.","B":"A dor cíclica mensal pode ser identificada com a endometriose, embora quase 50% das\nmulheres com síndrome do intestino irritável\ntambém possam apresentar piora dos sintomas no\nperíodo pré-menstrual.","C":"Apesar dos estudos, não foi encontrada nenhuma relação entre DPC e a obesidade ou\nalterações posturais.","D":"A dor relacionada às varizes pélvicas e à congestão venosa é exarcebada no período\nmenstrual."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127988","number":"127988","sourceNumber":"127988","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Com relação aos sintomas vasomotores (fogachos) observados em muitas mulheres na\nmenopausa, assinale a alternativa CORRETA:","options":{"A":"A progesterona desempenha um papel importante no desenvolvimento do fogacho.","B":"Costumam iniciar-se após 1 ano de amenorreia em 90% dos casos das mulheres.","C":"Pacientes com menopausa cirúrgica não costumam apresentar fogachos.","D":"Duram em média de 1 a 5 minutos, a frequência cardíaca aumenta de 7 a 17bpm e a\ntemperatura interna diminui 0,1 a 0,9 graus\ncentígrados dentro do período de 5 a 9 minutos após o\ninício do sintoma."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-136652","number":"136652","sourceNumber":"136652","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 60 anos com incontinência urinária aos mínimos esforços e com piora após a\nmenopausa. Segundo a paciente, já foi submetida à Colpoperineoplastia sem sucesso. Exame\nfísico não apresenta distopias. Urodinâmica com pressão de perda menor que 60 cm de água.\n\nAcerca desse caso clínico, qual é o diagnóstico PROVÁVEL?","options":{"A":"IUE por fator intrínseco à uretra.","B":"IUE por fator extrínseco.","C":"Hipermobilidade vesical.","D":"Instabilidade Vesical."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-136649","number":"136649","sourceNumber":"136649","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 47 anos de idade, G2P2A0C2 + Laqueadura Tubárea, refere sangramento\nvaginal intenso há 15 dias, com cólicas e dor\nem baixo ventre, refere que menstruação sempre foi\nregulada com fluxo pequeno e duração de 5 dias, nega patologias e medicações em uso, vida\nsexual ativa, sem queixas, refere ondas de calor há 2 meses. Podemos afirmar que o diagnóstico\ndo caso acima é","options":{"A":"Perimenopausa.","B":"Menopausa Precoce.","C":"Endometriose.","D":"Síndrome Disfórica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-137029","number":"137029","sourceNumber":"137029","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A incontinência urinária de esforço (IUE) é uma afecção de grande importância pela sua\nmorbidade e constitui a queixa urinária mais frequente das pacientes que procuram os ambulatórios\nde ginecologia. Sobre IUE, verifica-se o seguinte:","options":{"A":"a IUE pode ser devido a alteração na mobilidade do colo vesical, deficiência esfincteriana\ninstrínseca e hiperatividade do detrusor.","B":"a perda de urina aos mínimos esforços sugere hipermobilidade uretral.","C":"considera-se insuficiência esfincteriana intrinseca quando a pressão de perda for maior que 90\ncmH2O.","D":"a IUE é definida como toda perda de urina através do meato externo da uretra e quando a\npressão vesical excede a pressão uretral, na ausência de contração do musculo detrusor."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-137039","number":"137039","sourceNumber":"137039","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O Prolapso de Orgãos Pélvicos é definido como o deslocamento caudal, parcial ou total\nde qualquer segmento ou órgão pélvico da sua localização habitual, abrangendo a procidência das\nparedes vaginais anterior, posterior e ápice e/ou do útero. Sobre os prolapsos genitais, sabe-se\nque:","options":{"A":"na classificação POP-Q o ponto Ap localizado na linha média em parede anterior, a três\ncentímetros da carúncula himenal.","B":"o aparelho de sustentação é composto pelo assoalho pélvico, sendo o conjunto de estruturas\nque fica entre o peritôneo pélvico e a pele da\nvulva. É composto apenas pelo diafragma pélvico e\nfáscia endopélvica.","C":"na classificação POP-Q o ponto Aa é o ponto que representa o local de maior prolapso da\nparede anterior.","D":"o aparelho de sustentação localiza-se entre o assoalho pélvico e peritôneo parietal, sendo\nformado por tecido conjuntivo elástico e musculatura lisa."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-137043","number":"137043","sourceNumber":"137043","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A idade da ocorrência da menopausa parece geneticamente programada para cada\nmulher, pelo número de folículos ovarianos,\nmas pode ser influenciada por fatores socioeconômicos\ne culturais, paridade, tabagismo, altitude e nutrição. Na pós-menopausa, o ovário produz\nprincipalmente:","options":{"A":"Testosterona e androstenediona.","B":"Estrona e estradiol.","C":"Estrona e testosterona.","D":"Estradiol e testosterona."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-136568","number":"136568","sourceNumber":"136568","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente com 52 anos, G6P6A0C0, DUM = há 9 meses, vida sexual ativa, refere perdas\nde urina aos pequenos esforços há 8 meses,\nnictúria (4 vezes), urgência miccional e\nurgeincontinência. Nega febre, disúria e polaciúria. Fez exame especular e exame de urina I com\nurocultura, que estavam normais. Diante de tal caso, que outro exame seria importante para a\nconclusão diagnóstica?","options":{"A":"Estudo urodinâmico.","B":"US abdominal.","C":"Urografia excretora.","D":"Exame de papanicolau."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127584","number":"127584","sourceNumber":"127584","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 47 anos, submetida à histerectomia há dez anos, apresenta sintomas\nde climatério descompensado. Foi-lhe indicada\nterapia hormonal (TH). Qual deve ser a prescrição?","options":{"A":"Estrogênio e progestogênio em uso contínuo.","B":"Estrogênio por 14 dias e estrogênio e progestogênio por mais 14 dias.","C":"Estrogênio em uso contínuo.","D":"Estrogênio e baixas doses de androgênio de forma contínua."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127589","number":"127589","sourceNumber":"127589","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"É considerado um beneficio adicional da TH, a redução:","options":{"A":"do número de gravidez ectópica.","B":"da atividade do osteoclasto.","C":"do número de câncer de mama.","D":"do número de câncer de colo uterino."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127596","number":"127596","sourceNumber":"127596","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diafragma urogenital é formado pelos músculos:","options":{"A":"Transverso profundo do períneo e esfíncter uretral externo.","B":"Levantador do ânus e coccígeos.","C":"Glúteo máximo e isquiococcígeo.","D":"Piriforme e pubococcígeo."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-129863","number":"129863","sourceNumber":"129863","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapia hormonal (TH) ainda é a melhor alternativa para tratar sintomas climatéricos,\nem especial os sintomas vasomotores e de atrofia\nurogenital. Contudo, existem condições que\ncontraindicam absolutamente o seu uso, como:","options":{"A":"Após câncer de ovário.","B":"Após cancêr hepático.","C":"Hipertensão arterial controlada.","D":"Doença coronariana."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127341","number":"127341","sourceNumber":"127341","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 47 anos de idade, G2P2A0C2 + Laqueadura Tubária, refere sangramento\nvaginal intenso há 15 dias, com cólicas e dor\nem baixo ventre, refere que menstruação sempre foi\nregulada com fluxo pequeno e duração de 5 dias, nega patologias e medicações em uso, vida\nsexual ativa, sem queixas, refere ondas de calor há 2 meses. Diante de tal caso, podemos afirmar\nque o diagnóstico do caso acima é:","options":{"A":"Perimenopausa.","B":"Menopausa precoce.","C":"Endometriose.","D":"Síndrome disfórica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-127271","number":"127271","sourceNumber":"127271","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 40 anos, com incontinência urinária aos mínimos esforços, nictúria e com\nurgincontinência. Nega ITU. Segundo a paciente, já foi submetida a uma colpoperineoplastia sem\nsucesso. Exame físico não apresenta distopias. Qual exame seria necessário para o tratamento\ndessa paciente?","options":{"A":"Uretrocistografia miccional.","B":"Ultrassonografia pélvica.","C":"Urografia excretora.","D":"Estudo urodinâmico."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-106723","number":"106723","sourceNumber":"106723","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Observe a figura abaixo. (VER IMAGEM). Na figura demonstrada, os números 1, 2, 3 e\n4, correspondem respectivamente a:","options":{"A":"Músculo isquiocarvernoso, músculo transverso superficial do períneo, centro tendíneo do\nperíneo e músculo elevador do ânus.","B":"Músculo bulbocavernoso, músculo isquiocavernoso, centro tendíneo do períneo, fáscia\nisquiorretal.","C":"Músculo pubococcígeo, músculo puborretal, músculo bulboesponjoso, ligamento iliossacro.","D":"Músculo transverso profundo do períneo, músculo isquiorretal, ligamento anococcígeo, músculo\nelevador do ânus."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/106723.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-106726","number":"106726","sourceNumber":"106726","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre as distopias genitais, é correto afirmar que:","options":{"A":"A cistocele é a responsável pela incontinência urinária de esforço.","B":"Os ligamentos uterossacros e redondos são os que evitam o prolapso uterino.","C":"A cistouretrocele pode ocorrer em pacientes nulíparas.","D":"A retocele é ocasionada pela ruptura da fáscia pubovesicocervical."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-106691","number":"106691","sourceNumber":"106691","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 68 anos de idade, G8P8A0 - (partos normais), com menopausa há 15 anos,\nrefere perda urinária aos esforços há 6\nanos, com piora progressiva e saída de grande quantidade\nde urina quando sorri, levanta peso ou anda rápido. Solicitado exame urodinâmico que evidenciou:\nurofluxometria com volume de 320 ml, fluxo médio de 15 ml/s, ausência de resíduo pós-miccional e\ncistometria com PPE (Pressão de Perda aos Esforços) de 55 cmH?O durante a manobra de\nValsalva, sem contrações involuntárias do detrusor. O diagnóstico é:","options":{"A":"Incontinência urinária de esforço por lesão esfincteriana.","B":"Incontinência urinária associada à cistite intersticial.","C":"Incontinência urinária por hiperatividade do músculo do detrusor.","D":"Incontinência urinária de esforço por hipermobilidade vesical."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-106696","number":"106696","sourceNumber":"106696","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual o tratamento inicial para os pacientes com bexiga hiperativa?","options":{"A":"Cirurgia de Kelly- Kennedy.","B":"Cirurgia de sling.","C":"Medicamentos anticolinérgicos.","D":"Medicamentos alfa-agonistas."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-109178","number":"109178","sourceNumber":"109178","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São fatores inevitáveis e aceleradores para o desenvolvimento da osteoporose no\nclimatério, EXCETO:","options":{"A":"Dieta hiperprotéica.","B":"Estatura (pequena e magra).","C":"Uso prolongado de anticoncepcioais orais.","D":"Gravidez."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-109333","number":"109333","sourceNumber":"109333","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A densidade mineral óssea frequentemente pode ser afetada de forma negativa por\ndiversas doenças e por drogas. Em ginecologia, algumas situações fisiológicas ou drogas de uso\ncomum e rotineiro podem diminuir a massa óssea. Das drogas usadas em ginecologia, qual está\nassociada à osteoporose?","options":{"A":"Anticoncepcional hormonal de progestina isolada.","B":"Tamoxifeno.","C":"Cabergolina.","D":"Raloxifeno."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-109341","number":"109341","sourceNumber":"109341","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher climatérica, de 50 anos, procura atendimento com queixas de fogachos com\ngrande desconforto. Tem antecedentes de duas\ngestações, dois partos normais, histerectomia há\ndez anos por miomas uterinos, menopausa há dois anos e sem comorbidades. Diante desse\nquadro, a opção terapêutica mais adequada é:","options":{"A":"associação estrógeno-progestina.","B":"estrógenos isolados.","C":"fito-hormônios.","D":"raloxifeno."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-101205","number":"101205","sourceNumber":"101205","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 46 anos apresenta queixa de noctúria, enurese\n\nnoturna e incontinência por urgência. O exame qualitativo de urina e a urocultura são negativos\npara infecção urinária. A ocorrência destes\nsintomas é característica de:","options":{"A":"incontinência urinária de esforço.","B":"uretrocele.","C":"bexiga hiperativa.","D":"cistocele."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-103638","number":"103638","sourceNumber":"103638","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 50 anos, G3P3A0C0, vida sexual ativa, refere há 4 meses não menstruar e\na sentir calorões intensos que sobem para o\npescoço e face à noite e na madrugada, irritação e\ninsônia. Diante desse caso, qual exame NÃO seria importante para o diagnóstico e possível\ntratamento?","options":{"A":"Mamografia.","B":"Dosagem de TSH.","C":"US endovaginal.","D":"Dosagem de Beta HCG."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-110212","number":"110212","sourceNumber":"110212","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 53 anos, GIV PIII AI, com queixa de perda de urina aos esforços, urgência\nmiccional, nictúria e urgeincontinência, sem distopia ao exame físico. O estudo urodinâmico\nevidenciou fase de esvaziamento normal e fase de enchimento apenas com algumas contrações\ninvoluntárias do detrusor associadas a perdas urinárias. Com base nessas evidências, o\ndiagnóstico é de:","options":{"A":"Incontinência urinária de esforço.","B":"Incontinência urinária mista.","C":"Bexiga neurogênica hipotônica.","D":"Bexiga hiperativa."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-110241","number":"110241","sourceNumber":"110241","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diafragma pélvico é formado pelos seguintes músculos:","options":{"A":"Coccígeo e diafragma urogenital.","B":"Levantadores do ânus e coccígeo.","C":"Transverso profundo do períneo.","D":"Transverso profundo do períneo e diafragma urogenital."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-110255","number":"110255","sourceNumber":"110255","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 65 anos, apresentando o seguinte exame pela classificação POP-Q: (VER\nIMAGEM). Com base no exame apresentado, conclui-se que a paciente apresenta:","options":{"A":"Defeito de parede anterior.","B":"Exame físico normal sem distopias.","C":"Prolapso uterino.","D":"Defeito posterior e é histerectomizada."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/110255.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-83688","number":"83688","sourceNumber":"83688","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher, 58 anos, obesa, apresentando urgência miccional, urgeincontinência e perda\nurinária aos esforços. Ao exame: distopia da parede vaginal anterior estádio 1, segundo o POP-Q.\nEstudo urodinâmico: pressão de perda uretral sob esforço de 50 cm de H?O e contrações não\ninibidas. Qual diagnóstico e tratamento mais adequado neste caso, respectivamente?","options":{"A":"Incontinência urinária de esforço; Cirurgia de sling + perineoplastia.","B":"Incontinência urinária mista; Cirurgia de sling + uso de bloqueadores adrenérgicos.","C":"Incontinência urinária de esforço; Cirurgia de Burch + perineoplastia.","D":"Incontinência urinária mista; Cirurgia de sling + uso de drogas anticolinérgicas.","E":"Hiperatividade do detrusor; uso de bloqueadores adrenérgicos."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-84688","number":"84688","sourceNumber":"84688","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A perda de massa óssea constitui-se num dos principais problemas de saúde da mulher\napós a menopausa, devido à morbidade e aos custos associados ao tratamento das fraturas\nosteoporóticas. O papel do ginecologista na prevenção e no controle da osteoporose\n\npós-menopausa inclui:","options":{"A":"A avaliação de densidade mineral óssea para todas as mulheres acima de 50 anos,\nindependente dos fatores de risco.","B":"O uso de estrogênios, de moduladores seletivos de receptor estrogênico ou dos bifosfonatos\nquando a avaliação da densidade mineral\nóssea apresenta índice t acima de -1.","C":"O uso de progestagênios para mulheres de risco para osteoporose com antecedente de\ntromboembolismo e intolerância gástrica aos bifosfonatos.","D":"O uso do raloxifeno, um modulador seletivo do receptor estrogênico, para pacientes com\nosteoporose e alto risco para câncer de mama.","E":"Nenhuma das anteriores."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-78126","number":"78126","sourceNumber":"78126","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Segundo Novak, é considerada insuficiência ovariana prematura a ocorrência\nespontânea da menopausa antes dos","options":{"A":"30 anos.","B":"35 anos.","C":"38 anos.","D":"40 anos."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-78109","number":"78109","sourceNumber":"78109","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Segundo Rezende, para usar metotrexato na prenhez ectópica (tratamento médico) a\nmassa tubária medida no ultrassom deve ter até","options":{"A":"6,5 cm","B":"5,5 cm","C":"3,5 cm","D":"1,5 cm"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-83825","number":"83825","sourceNumber":"83825","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre as vitaminas D, podemos afirmar, exceto:","options":{"A":"a vitamina D é metabolizada no fígado.","B":"o metabólito da vitamina D é o calcidiol.","C":"o calcidiol é metabolizado nos rins em calcitriol.","D":"a vitamina D2 (ergocalciferol) é derivada de óleos de peixe.","E":"a vitamina D3 (colecalciferol) é sintetizada na epiderme."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-84377","number":"84377","sourceNumber":"84377","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O tratamento de escolha para os sintomas urogenitais e infecção urinária de repetição\nem uma mulher menopausada há 7 anos,\nhisterectomizada, sem nunca ter realizado terapia\nhormonal de reposição é:","options":{"A":"Estrogênios conjugados via sistêmica.","B":"Estrogênios via vaginal.","C":"Fitoestrogênios.","D":"Associação estrógeno-progestágeno via sistêmica.","E":"Associação estrogenoandrogênica via vaginal."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-83861","number":"83861","sourceNumber":"83861","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São fatores de risco para osteoporose, EXCETO:","options":{"A":"Baixa ingestão de cálcio no período de crescimento.","B":"Deficiência de estrogênio.","C":"Deficiência de vitamina D.","D":"Obesidade.","E":"Tabagismo."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-85331","number":"85331","sourceNumber":"85331","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A principal estrutura responsável pelo fechamento e sustentação do assoalho pélvico é:","options":{"A":"aponeurose do músculo reto abdominal.","B":"músculo transverso do períneo.","C":"arco tendíneo do períneo.","D":"músculo elevador do ânus."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-85335","number":"85335","sourceNumber":"85335","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"No tratamento clínico da hiperatividade do detrusor, as drogas utilizadas incluem: I.\nAntimuscarínicos; II. Colinérgicos; III. Antidepressivos tricíclicos; IV. Betabloqueadores.","options":{"A":"I e III.","B":"I, II e III.","C":"I e IV.","D":"I, II e IV."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-85343","number":"85343","sourceNumber":"85343","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente apresenta o seguinte exame ginecológico: Aa = +3; Ba = +4; C = -8; Ap =\n\n-3; Bp = -3. Com base na classificação POP-Q, podemos concluir que ela:","options":{"A":"apresenta defeito anterior e prolapso uterino.","B":"apresenta defeito em parede posterior.","C":"apresenta defeito posterior e prolapso uterino.","D":"apresenta defeito de parede anterior acentuado."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-63682","number":"63682","sourceNumber":"63682","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente 50 anos, G III, PN II, com menopausa há dois anos, com antecedente de\ncolpoperineoplastia. Queixa-se de perda de urina aos médios esforços. Nega urgência miccional.\nRefere 01 (um) episódio de micção à noite. A paciente mede 1,60 m e pesa 80 kg. O exame\nginecológico não evidenciou presença de distopia de paredes vaginais e ficou evidente a presença\nde perda de urina aos esforços. O exame Urodinâmico evidenciou: ausência de contrações não\ninibidas do detrusor e pressão aos esforços de 50 cm de H2O. Qual a hipótese diagnóstica e\nconduta adequada:","options":{"A":"Hiperatividade do detrusor. Conduta: tratamento com oxibutinina.","B":"Incontinência urinária de esforço por deficiência intrínseca do esfíncter. Conduta: cirurgia de\n\"Sling\".","C":"Incontinência urinária de esforço por hipermobilidade uretral. Conduta: cirurgia de Burch.","D":"Incontinência urinária de esforço por deficiência intrínseca do esfíncter. Conduta: cirurgia de\nBurch."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-63685","number":"63685","sourceNumber":"63685","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à classificação dos prolapsos genitais dos órgãos pélvicos (POP-Q), a\npaciente apresentou o seguinte exame físico (VER IMAGEM):","options":{"A":"A paciente apresenta prolapso vaginal anterior.","B":"A paciente apresenta prolapso vaginal anterior e posterior.","C":"A paciente apresenta prolapso posterior.","D":"A paciente apresenta prolapso uterino."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":["question_bank/media/medcurso/medcurso-gineco-gin-3/63685.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64580","number":"64580","sourceNumber":"64580","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 48 anos, de peso normal, que tem prole definida, apresenta fogachos há\ndois meses e vem com quadro de polimenorreia há cinco meses, a conduta adequada, das abaixo\nrelacionadas, é prescrever:","options":{"A":"Contraceptivo injetável mensal.","B":"Desogestrel contínuo.","C":"Valerato de estradiol 1 mg contínuo associado a progestágeno na 2ª fase do ciclo.","D":"17-ß estradiol contínuo isoladamente.","E":"Acetato de medroxiprogesterona trimestral, aplicado via intramuscular."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64584","number":"64584","sourceNumber":"64584","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente de 67 anos, que apresenta urgeincontinência urinária há sete meses, é\nhipertensa e tem perfil depressivo. O seu\nclínico está pensando em prescrever medicamentos para\nela, em função do problema atual e de problemas intercorrentes. Dos medicamentos abaixo, o que\npode piorar o seu sintoma urinário é o (a):","options":{"A":"Atenolol.","B":"Amitriptilina.","C":"Losartana.","D":"Oxibutinina.","E":"Tolterodina."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-64599","number":"64599","sourceNumber":"64599","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"M.P.S., 52 anos, procura atendimento médico especializado com queixa de perda\nurinária aos médios esforços, urgência\nmiccional, urgeincontinência e noctúria. Relata que o quadro\niniciou-se há 18 meses, agravando-se nos últimos 4 meses. É gesta 3 para 3 (normais), e relata\ncirurgia de períneo há 15 anos. Apresenta ciclos menstruais irregulares com a última menstruação\nhá três meses. Refere ser hipertensa em tratamento e nega outras comorbidades. Ao exame físico\nencontra-se em bom estado geral, com vagina e vulva hipotróficas, sem distopias e teste de esforço\nnegativo.","options":{"A":"Trata-se de uma incontinência urinária de esforço e o tratamento indicado seria medicamentoso.","B":"Trata-se de uma incontinência urinária de esforço e o tratamento indicado seria cirúrgico,\natravés\nda colporrafia anterior a Kelly-Kennedy.","C":"Trata-se de uma incontinência urinária mista e o tratamento indicado seria medicamentoso.","D":"O estudo urodinâmico está indicado neste caso.","E":"Deve-se tratar infecção urinária, pois se trata de sintomas irritativos."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-62767","number":"62767","sourceNumber":"62767","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A terapia de reposição hormonal pode ser feita com vários tipos de medicação,\ndestacando-se, entre eles, a tibolona. A tibolona, no figado,","options":{"A":"aumenta a síntese de albumina.","B":"aumenta a gliconeogênese.","C":"reduz a produção de SHBG.","D":"estimula a formação da lipase hepática."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-63223","number":"63223","sourceNumber":"63223","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O citrato de clomifeno é a primeira linha para indução clínica da ovulação em pacientes\nportadoras da síndrome dos ovários polícisticos que desejam engravidar. Em relação ao\nmecanismo de ação desse medicamento, assinale a alternativa correta.","options":{"A":"Ação indireta sobre a hipófise ou ovário.","B":"Aumenta a alça de feedback de estrogênio ovariano-hipotálamo normal.","C":"Diminui a amplitude de pulso do GnRH.","D":"Imita a atividade de um antagonista estrogênico.","E":"Liga-se aos receptores de progesterona no hipotálamo por longos períodos."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-61830","number":"61830","sourceNumber":"61830","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A osteoporose constitui hoje um importante problema de saúde pública em todo o\nmundo, predispondo a um risco aumentado de fraturas, sendo uma causa importante de\nmorbidade, mortalidade e prejuízo da qualidade de vida das mulheres na pós-menopausa. Em\nrelação à osteoporose pode-se afirmar:","options":{"A":"Os exercícios com pesos constituem o mais eficiente estímulo conhecido para o aumento da\nmassa óssea.","B":"O consumo diminuído de proteína estimula as perdas de cálcio.","C":"A diminuição do consumo de sódio leva ao aumento da excreção renal de cálcio.","D":"O uso de anticonvulsivantes pode acelerar o ganho de massa óssea.","E":"As principais fontes de cálcio dietético com disponibilidade são os peixes."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-61836","number":"61836","sourceNumber":"61836","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher de 36 anos de idade procura atendimento com queixa da perda urinária aos\nesforços há 5 anos, após o último parto,\ncom piora no último ano e grande desconforto social. Tem\nantecedentes de três partos normais hospitalares, apresentando-se ao exame físico com IMC = 21,\nnormotensa e com uretrocistocele grau I, sem outras distopias genitais. Solicitado o estudo\nurodinâmico, o resultado mostrou perda urinária com 95 cmH20. Diante desse quadro, a opção\nterapêutica de eleição é:","options":{"A":"Estrogenoterapia.","B":"Drogas colinérgicas.","C":"Colpofixação retropúbica (Cirurgia de Burch).","D":"Colpoperineoplastia (Cirurgia de Kelly-Kennedy).","E":"Cirurgia de sling pubovaginal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-48823","number":"48823","sourceNumber":"48823","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"TUH, 65 anos, refere perda urinária aos esforços agravando nos últimos meses.\nAtualmente relata perda aos pequenos esforços\ncom tosse ou espirro. Teve cinco gestações, sendo\ntodas, partos normais. Ao exame físico apresentava o ponto Aa +3, C +3, Ap -3. A melhor conduta\nseria:","options":{"A":"Solicitar exames complementares para elucidação diagnóstica.","B":"Histerectomia abdominal associado à cirurgia de Burch.","C":"Histerectomia vaginal com correção do defeito, sítio específico e se necessário colocação de\nalça sintética suburetral através do forame obturatório.","D":"Colporrafia anterior a Kelly-Kennedy.","E":"Sling pubovaginal."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-48508","number":"48508","sourceNumber":"48508","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"PPV, 61 anos, queixa de perda de urina involuntária aos esforços há mais de 5 anos.\nComo antecedentes pessoais refere menopausa aos 50 anos, início da atividade sexual aos 20\nanos, histerectomia vaginal há 13 anos e dois partos normais a termo no hospital. Nos\nantecedentes familiares relata que sua mãe é hipertensa. Ao exame ginecológico foi visualizada a\ncúpula vaginal se exteriorizando através da rima vulvar. Sobre este caso, assinale a alternativa\nincorreta.","options":{"A":"A sociedade Internacional de Continência define prolapso genital como o descenso da parede\nvaginal anterior e/ou posterior, assim como do ápice da vagina (útero ou cúpula vaginal após\nhisterectomia).","B":"O progressivo aumento da expectativa de vida aumentou o número de pacientes com prolapso\ngenital.","C":"Não há aumento nas taxas de prolapso genital em mulheres com antecedente de um parto\nvaginal quando comparado com mulheres nulíparas.","D":"O prolapso genital pode ter como fator agravante o hipoestrogenismo e as cirurgias pélvicas\nprévias. Por isso as histerectomias devem ter indicações precisas.","E":"O prolapso da cúpula vaginal pode ser uma complicação da histerectomia vaginal por prolapso e\ntem incidência que pode chegar a aproximadamente 43% destas cirurgias."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-48837","number":"48837","sourceNumber":"48837","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"De acordo com a classificação POP-Q (Pelvic Organ Prolapse Quantification) proposta\npela Sociedade Internacional de Continência, NÃO\né correta a seguinte descrição:","options":{"A":"D: ponto mais profundo do fundo de saco posterior.","B":"Aa: linha média da parede vaginal anterior, 3 cm acima do hímen.","C":"C: ponto mais distal do colo uterino ou cúpula vaginal, se histerectomia prévia.","D":"Gh: medida do hiato genital (do meio do meato uretral externo até a margem posterior do\nhímen).","E":"Bp: análogo posterior do ponto Aa."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-53542","number":"53542","sourceNumber":"53542","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Assinale a alternativa em que NÃO está listada uma causa de incontinência urinária\nreversível.","options":{"A":"Infecção urinária.","B":"Vaginite atrófica.","C":"Hiperatividade do detrusor.","D":"Impactação fecal.","E":"Pós-RTU de próstata."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-49016","number":"49016","sourceNumber":"49016","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Mulher com 42 anos procura atendimento com queixa de que há cerca de 2 anos\npassou a apresentar perda urinária aos\nesforços associados à urgência miccional, polaciúria,\ndisúria, dor em peso em região hipogástrica e dispareunia. Apresenta antecedentes de infecção\nurinária de repetição, 3 partos normais hospitalares e cirurgia de colpoperineoplasia. Descartada\ninfecção urinária, a principal hipótese diagnóstica é:","options":{"A":"Incontinência urinária aos esforços genuína.","B":"Bexiga hiperativa.","C":"Incontinência urinária mista.","D":"Fístula vesicovaginal.","E":"Cistite intersticial."},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-48528","number":"48528","sourceNumber":"48528","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Dentre as causas de bexiga neurogênica, a que não é:","options":{"A":"Lesão secundária de Síndrome de Goodpasture.","B":"Mielomeningocele.","C":"Agenesia Sacral.","D":"Trauma medular.","E":"Lesão cirúrgica."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-51009","number":"51009","sourceNumber":"51009","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma mulher de 64 anos refere incontinência urinária há 3 anos. Ela descreve os\nepisódios de incontinência como pequenos\n\"vazamento\" que ocorrem quando espirra, tosse ou faz\nalguma atividade física. Ao exame, apresenta prolapso uterino leve e cistocele moderada. A\nurocultura é normal. O volume pós-miccional é normal. Cistometrograma é normal. Qual o\ndiagnóstico mais provável?","options":{"A":"instabilidade do detrusor","B":"incontinência urinária de esforço genuína","C":"bexiga neurogênica","D":"pielonefrite","E":"infecção do trato urinário"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-48149","number":"48149","sourceNumber":"48149","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Em relação à osteoporose é correto afirmar:","options":{"A":"Depois de meia-idade a incidência em homens e mulheres se iguala.","B":"Lombalgia é o sintoma mais comum.","C":"O nível sérico de cálcio está habitualmente diminuído na osteoporose primária.","D":"O nível sérico de fosfatase alcalina é um bom marcador para osteoporose.","E":"Evolui com malignização em 25% dos pacientes."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-47683","number":"47683","sourceNumber":"47683","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A incontinência urinária, sintoma frequente nos ambulatórios de ginecologia, é\nconsiderada problema social devido a\nrepercussões negativas na qualidade de vida das pacientes\nacometidas. Assim, a incontinência urinária de esforço:","options":{"A":"é a segunda causa mais comum de incontinência urinária.","B":"exige exames urodinâmicos formais para o diagnóstico.","C":"evidencia, no estudo urodinâmico, perda involuntária de urina durante o aumento da pressão\nintrauretral, na ausência de contração do detrusor.","D":"tem como base para o tratamento cirúrgico a suspensão do colo vesical."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-47629","number":"47629","sourceNumber":"47629","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Durante a fecundação pode ocorrer o surgimento de doença trofoblástica gestacional.\nEntão, na mola hidatiforme,","options":{"A":"A mola completa tem material genético exclusivo de origem paterna;","B":"A mola completa pode apresentar partes ou anexos fetais;","C":"As metástases são frequentes para cérebro e osso, quando ocorre transformação maligna;","D":"O coriocarcinoma origina-se obrigatoriamente de uma gestação molar anterior."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-53567","number":"53567","sourceNumber":"53567","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Sobre o climatério, é CORRETO afirmar que :","options":{"A":"o hipoestrogenismo que se segue à menopausa leva a uma diminuição da reabsorção óssea,\ncom perda da massa óssea e fraturas de corpos\nvertebrais, rádio distal e colo do fêmur.","B":"estudos observacionais mostram diminuição na incidência de cancro colorretal em mulheres\nusuárias de terapia hormonal.","C":"a hiperplasia ductal atípica na mama não é contraindicação para o uso de terapia hormonal.","D":"o uso de progestogênio contínuo parece ser adequado para proteger o endométrio com menor\ninterferência nos benefícios cardiovasculares.","E":"nenhuma das alternativas acima."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-35795","number":"35795","sourceNumber":"35795","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A primeira e mais constante alteração na transição para a menopausa é:","options":{"A":"Elevação dos níveis de progesterona.","B":"Elevação dos níveis de estriol.","C":"Queda dos níveis de estradiol.","D":"Elevação dos níveis de FSH.","E":"Queda dos níveis de estradiol com elevação dos níveis de estrona e estriol."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-22991","number":"22991","sourceNumber":"22991","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Uma paciente de 62 anos, IMC = 30, G8P7NA1, apresenta incontinência urinária ao\nsubir escada, pegar peso, tossir, espirrar e\ntem antecedente de duas cirurgias prévias para tratar\nincontinência urinária de esforço, uma por via vaginal e outra por via suprapúbica. Ao exame clínico\nobservou-se que ela apresenta ausência de cistocele, hipermobilidade uretral (teste do cotonete de\n45°), volume residual de urina normal e perda urinária aos pequenos esforços (deitada). O\ntratamento mais indicado para essa paciente é:","options":{"A":"a colporrafia anterior via vaginal.","B":"o sling transobturatório","C":"a fisioterapia.","D":"a uretropexia retropúbica"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-23003","number":"23003","sourceNumber":"23003","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Os exames laboratoriais que devem ser solicitados para acompanhamento clínico de\numa mulher de 49 anos de idade, menopausada há\ndois anos, sem queixas, com exame físico\ngeral e ginecológico normais, são:","options":{"A":"lipidograma, glicemia de jejum, TSH, FSH e mamografia.","B":"COP, lipidograma, FSH, mamografia e ultrassonografia endovaginal.","C":"lipidograma, glicemia de jejum, COP, mamografia e ultrassonografia endovaginal.","D":"mamografia, ultrassonografia e histeroscopia"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-26964","number":"26964","sourceNumber":"26964","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Margarida, 68 anos, obesa, branca, menopausada há 12 anos, vai ao consultório do\nginecologista, queixando- se de sangramento genital. Gesta III Para 0 Aborto III (provocados). O\nexame mostrou mama, vulva e vagina sem alterações; útero algo aumentado de tamanho. Qual a\npropedêutica indicada para o caso?","options":{"A":"Ultrassonografia transvaginal","B":"Videolaparoscopia","C":"Biópsia de endométrio","D":"Curetagem uterina diagnóstica","E":"Colpocitologia tríplice"},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9361","number":"9361","sourceNumber":"9361","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A bexiga hiperativa é caracterizada por urgência miccional, com ou sem incontinência\nde urgência e associada ao aumento da frequência\nmiccional, podendo ser primária (idiopática) ou\nsecundária. São causas conhecidas de bexiga hiperativa:","options":{"A":"HPB, cirurgias de amputação de reto, neuropatia periférica.","B":"obstrução do colo vesical, prolapso uterino, AVC.","C":"trauma raquimedular, histerectomia ampliada, neuropatia diabética.","D":"HPB, incontinência urinária de esforço, neuropatia periférica."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-11099","number":"11099","sourceNumber":"11099","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Na classificação de Baden e Walker, modificada por Juma em 1993, prolapso uterino\ngrau II, significa:","options":{"A":"Cistocele que ultrapassa o intrólio vaginal e colo uterino visível até o óstio vaginal","B":"Parede vaginal posterior até a linha do intróito vaginal e corpo uterino ultrapassa o óstio\nvaginal","C":"É visível que o colo uterino desce pelo canal vaginal até o óstio vaginal","D":"O corpo uterino ultrapassa o óstio vaginal","E":"o colo uterino ultrapassa o óstio vaginal"},"answer":"E","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9357","number":"9357","sourceNumber":"9357","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"São considerados fatores de risco para osteoporose:","options":{"A":"Raça branca, tabagismo, ingestão excessiva de cafeína.","B":"Deficiência de fósforo, hipogonadismo, sexo masculino.","C":"Menopausa precoce, idade acima de 50 anos, baixa estatura.","D":"Ingestão excessiva de álcool, sexo feminino, raça negra."},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-12730","number":"12730","sourceNumber":"12730","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O diafragma urogenital é formado pelos músculos:","options":{"A":"transverso profundo do períneo e esfíncter uretral externo","B":"levantador do ânus e coccígeos","C":"glúteo máximo e isquicoccígeo","D":"piriforme e pubococcígeo","E":"pubovesical"},"answer":"A","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-10614","number":"10614","sourceNumber":"10614","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Paciente obesa, idosa, branca, menopausada há 12 anos vai ao consultório do\nginecologista, queixando-se de sangramento genital, Gesta III Para 0 Aborto III (provocados). O\nexame mostrou mama, vulva e vagina sem alterações; útero algo aumentado de tamanho. Qual a\npropedêutica indicada para o caso?","options":{"A":"ultrassonografia transvaginal.","B":"curetagem uterina diagnóstica.","C":"citologia tríplice.","D":"biópsia de endométrio.","E":"videolaparoscopia."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9313","number":"9313","sourceNumber":"9313","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"O assoalho pélvico é composto de todas as estruturas que fecham a saída pélvica,\ndesde a pele inferiormente até o peritônio superiormente. Esse assoalho:","options":{"A":"é formado por uma estrutura muscular denominada elevador do ânus, que obstrui por completo a\nreferida saída pélvica.","B":"possui componente externo, que se inicia no arco tendíneo até o osso púbis e espinha isquiática\n(pelos mm. pubococcígeos, ileococcígeos e\ncoccígeos).","C":"compõe-se, na parte superior, da fáscia endopélvica, que se estende inferiormente para recobrir\nos mm. isquiocavernosos e bulbocavernosos.","D":"utiliza as estruturas musculares do diafragma pélvico e urogenital. Essa disposição em camada\núnica muscular proporciona a sustentação ideal para os órgãos pélvicos."},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-9274","number":"9274","sourceNumber":"9274","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"A incontinência urinária é definida como perda involuntária de urina, sendo um sintoma\ne não um diagnóstico. Perante uma paciente com\nesse sintoma, deve-se:","options":{"A":"solicitar estudo urodinâmico para confirmar o diagnóstico e indicar cirurgia ou tratamento\nclínico.","B":"concluir que a perda involuntária de urina tem como diagnóstico incontinência por\nhipermotilidade uretral.","C":"concluir que a incontinência é devido à hipermotilidade vesical e prescrever medicações\ninibidoras desta contratibilidade.","D":"solicitar exame urinário, medida de urina residual pós-miccional e gráfico de frequência e volume\nvesical."},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8986","number":"8986","sourceNumber":"8986","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"MCR, freira de 72 anos, branca, asmática com história de uso crônico e intermitente de\ncorticoides, hipertensa em uso de enalapril e hidroclortiazida, com Índice de Massa Corporal (IMC)\nde 19 Kg/m², sedentária, nuligesta, menopausa aos 46 anos e que nunca fez terapia de Reposição\nHormonal.\n\nMCR foi submetida a exame de densilometria óssea com os seguintes resultados:\n\n¾ Densidade Mineral Óssea (DMO) de L1-L4 de menos 3,7 desvios-padrão em relação à curva de\nmassa óssea ajustada para adultos jovens e\nmenos 2,9 desvios-padrão em relação à curva de\nmassa óssea ajustada para a mesma idade, peso e sexo. 3/4 DMO de colo femoral de menos 1,4\ndesvios-padrão em relação à curva de massa óssea ajustada para adultos jovens e menos 1,0\ndesvios-padrão em relação à curva de massa óssea ajustada para a mesma idade, peso e sexo.\n\nQuanto ao diagnóstico densitométrico, pode-se afirmar que a paciente tem:","options":{"A":"osteoporose de coluna e do colo do fêmur, sendo que apenas na coluna os resultados alertam\npara a possibilidade de osteoporose\nsecundária","B":"osteoporose de coluna e do colo do fêmur, sendo que tanto na coluna como no fêmur os\nresultados alertam para a possibilidade de osteoporose secundária","C":"osteoporose de coluna e osteopenia femoral,sendo que apenas na coluna os resultados alertam\npara a possibilidade de osteoporose\nsecundária","D":"osteoporose de coluna e osteopenia femoral,sendo que tanto na coluna como no fêmur os\nresultados não permitem suspeitar de osteoporose secundária"},"answer":"C","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8988","number":"8988","sourceNumber":"8988","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"MCR, freira de 72 anos, branca, asmática com história de uso crônico e intermitente de\ncorticoides, hipertensa em uso de enalapril e hidroclortiazida, com Índice de Massa Corporal (IMC)\nde 19 Kg/m², sedentária, nuligesta, menopausa aos 46 anos e que nunca fez terapia de Reposição\nHormonal.\n\nAlém de um programa de exercícios físicos, suporte nutricional e suplementação de cálcio e\nvitamina D e levando-se em conta a melhor relação custo-benefício, o que mais poderia ser\nprescrito para a freira MCR?","options":{"A":"Um modulador seletivo de receptor estrogênico (SERM) como o raloxifeno","B":"Um bifosfonato como o aleandronato ou o risedronato","C":"Não há necessidade de outras medidas além das descritas","D":"Terapia hormonal estrogênica por via transdérmica"},"answer":"B","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-3-8989","number":"8989","sourceNumber":"8989","collectionBlock":"medcurso:medcurso-gineco-gin-3","collectionLabel":"Medcurso · GIN 3","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 3","subtopic":"","stem":"Qual deve ser o tratamento proposto para incontinência urinária funcional apresentada\npor uma senhora de 69 anos, multípara, obesa,\nportadora de osteoartrose de joelhos e hipertensa?","options":{"A":"Impramina 25 mg ao deitar.","B":"Oxibutinina 5 mg 2 a 3 vezes ao dia.","C":"Terapia hormonal estrogênica.","D":"Facilitar o acesso ao banheiro."},"answer":"D","source":"Gineco/GIN 3/GIN 3.txt","sourceLabel":"Medcurso · GIN 3","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
